INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VqeeyUqr5Jp', 4, '{"title":"第2013031条・金匮要略14  水气病","description":"<p>32、心下坚，大如盘，边如旋盘，水饮所作，$f{枳术汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013031,"note":"","videoMemo":"","fangList":["枳术汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '32、心下坚，大如盘，边如旋盘，水饮所作，$f{枳术汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('inE2y0Fa4gs', 4, '{"title":"第2013032条・金匮要略14  水气病","description":"<p>*、$q{附方《外台》}$f{防己黄芪汤} 治风水，脉浮为在表，其人或头汗出，表无他病，病者但下重，从腰以上为和，腰以下当肿及阴，难以屈伸。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2013032,"note":"","videoMemo":"","fangList":["防己黄芪汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '*、$q{附方《外台》}$f{防己黄芪汤} 治风水，脉浮为在表，其人或头汗出，表无他病，病者但下重，从腰以上为和，腰以下当肿及阴，难以屈伸。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'wp5OKlKnUuK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0Wx7ETzEvlm', 4, '{"title":"第2014000条・金匮要略15  黄疸","description":"<p>1、寸口脉浮而缓，浮则为风，缓则为痹。痹非中风。四肢苦烦，脾色必黄，瘀热以行。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2014000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '1、寸口脉浮而缓，浮则为风，缓则为痹。痹非中风。四肢苦烦，脾色必黄，瘀热以行。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'r695ZbvlfYe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iQe0qQMTabL', 4, '{"title":"第2014001条・金匮要略15  黄疸","description":"<p>2、趺阳脉紧而数，数则为热，热则消谷，紧则为寒，食即为满。尺脉浮为伤肾，趺阳脉紧为伤脾。风寒相抟，食谷即眩，谷气不消，胃中苦浊，浊气下流，小便不通，阴被其寒，热流膀胱，身体尽黄，名曰谷疸。额上黑，微汗出，手足中热，薄暮即发，膀胱急，小便自利，名曰女劳疸，腹如水状不治。心中懊憹而热，不能食，时欲吐，名曰酒疸。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2014001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2、趺阳脉紧而数，数则为热，热则消谷，紧则为寒，食即为满。尺脉浮为伤肾，趺阳脉紧为伤脾。风寒相抟，食谷即眩，谷气不消，胃中苦浊，浊气下流，小便不通，阴被其寒，热流膀胱，身体尽黄，名曰谷疸。额上黑，微汗出，手足中热，薄暮即发，膀胱急，小便自利，名曰女劳疸，腹如水状不治。心中懊憹而热，不能食，时欲吐，名曰酒疸。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'r695ZbvlfYe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('X7hZ4IRy3Q1', 4, '{"title":"第2014002条・金匮要略15  黄疸","description":"<p>3、阳明病，脉迟者，食难用饱，饱则发烦头眩，小便必难，此欲作谷疸。虽下之，腹满如故，所以然者，脉迟故也。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2014002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '3、阳明病，脉迟者，食难用饱，饱则发烦头眩，小便必难，此欲作谷疸。虽下之，腹满如故，所以然者，脉迟故也。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'r695ZbvlfYe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a2GxzQ1XlHe', 4, '{"title":"第2014003条・金匮要略15  黄疸","description":"<p>4、夫病酒黄疸，必小便不利，其候心中热，足下热，是其证也。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2014003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '4、夫病酒黄疸，必小便不利，其候心中热，足下热，是其证也。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'r695ZbvlfYe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gfBW4JSQaJ7', 4, '{"title":"第2014004条・金匮要略15  黄疸","description":"<p>5、酒黄疸者，或无热，靖言了$a{《脉经》作了了}，腹满欲吐，鼻燥。其脉浮者，先吐之；沉弦者，先下之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2014004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '5、酒黄疸者，或无热，靖言了$a{《脉经》作了了}，腹满欲吐，鼻燥。其脉浮者，先吐之；沉弦者，先下之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'r695ZbvlfYe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TogTdopfuRl', 4, '{"title":"第2014005条・金匮要略15  黄疸","description":"<p>6、酒疸，心中热，欲呕者，吐之愈。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2014005,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '6、酒疸，心中热，欲呕者，吐之愈。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'r695ZbvlfYe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zhN98vmkPRj', 4, '{"title":"第2014006条・金匮要略15  黄疸","description":"<p>7、酒疸下之，久久为黑疸，目青面黑，心中如啖蒜齑状，大便正黑，皮肤爪之不仁，其脉浮弱，虽黑微黄，故知之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2014006,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '7、酒疸下之，久久为黑疸，目青面黑，心中如啖蒜齑状，大便正黑，皮肤爪之不仁，其脉浮弱，虽黑微黄，故知之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'r695ZbvlfYe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fn2vfn2hAOR', 4, '{"title":"第2014007条・金匮要略15  黄疸","description":"<p>8、师曰：病黄疸，发热烦喘，胸满口燥者，以病发时，火劫其汗，两热所得。然黄家所得，从湿得之。一身尽发热而黄，肚热，热在里，当下之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2014007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '8、师曰：病黄疸，发热烦喘，胸满口燥者，以病发时，火劫其汗，两热所得。然黄家所得，从湿得之。一身尽发热而黄，肚热，热在里，当下之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'r695ZbvlfYe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wrgiDQh7NZB', 4, '{"title":"第2014008条・金匮要略15  黄疸","description":"<p>9、脉沉，渴欲饮水，小便不利者，皆发黄。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2014008,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '9、脉沉，渴欲饮水，小便不利者，皆发黄。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'r695ZbvlfYe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gCoqhm4Ii3Q', 4, '{"title":"第2014009条・金匮要略15  黄疸","description":"<p>10、腹满，舌痿黄，燥不得睡，属黄家。$a{舌痿疑作身痿}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2014009,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '10、腹满，舌痿黄，燥不得睡，属黄家。$a{舌痿疑作身痿}', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'r695ZbvlfYe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('l72OKTc843O', 4, '{"title":"第2014010条・金匮要略15  黄疸","description":"<p>11、黄疸之病，当以十八日为期，治之十日以上瘥，反剧为难治。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2014010,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '11、黄疸之病，当以十八日为期，治之十日以上瘥，反剧为难治。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'r695ZbvlfYe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IylgbJqB2P6', 4, '{"title":"第2014011条・金匮要略15  黄疸","description":"<p>12、疸而渴者，其疸难治；疸而不渴者，其疸可治。发于阴部，其人必呕；阳部，其人振寒而发热也。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2014011,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '12、疸而渴者，其疸难治；疸而不渴者，其疸可治。发于阴部，其人必呕；阳部，其人振寒而发热也。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'r695ZbvlfYe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AO57hSUOZj8', 4, '{"title":"第2014012条・金匮要略15  黄疸","description":"<p>13、谷疸之为病，寒热不食，食即头眩，心胸不安，久久发黄，为谷疸，$f{茵陈蒿汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2014012,"note":"","videoMemo":"","fangList":["茵陈蒿汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '13、谷疸之为病，寒热不食，食即头眩，心胸不安，久久发黄，为谷疸，$f{茵陈蒿汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'r695ZbvlfYe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ePsnS7ZIdxn', 4, '{"title":"第2014013条・金匮要略15  黄疸","description":"<p>14、黄家日晡所发热，而反恶寒，此为女劳得之。膀胱急，少腹满，身尽黄，额上黑，足下热，因作黑疸。其腹胀如水状，大便必黑，时溏，此女劳之病，非水也。腹满者难治，$f{硝石矾石散}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2014013,"note":"","videoMemo":"","fangList":["硝石矾石散"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '14、黄家日晡所发热，而反恶寒，此为女劳得之。膀胱急，少腹满，身尽黄，额上黑，足下热，因作黑疸。其腹胀如水状，大便必黑，时溏，此女劳之病，非水也。腹满者难治，$f{硝石矾石散}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'r695ZbvlfYe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a0dp84YIU5S', 4, '{"title":"第2014014条・金匮要略15  黄疸","description":"<p>15、酒黄疸，心中懊憹或热痛，$f{栀子大黄汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2014014,"note":"","videoMemo":"","fangList":["栀子大黄汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '15、酒黄疸，心中懊憹或热痛，$f{栀子大黄汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'r695ZbvlfYe');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yuZy7t06Jcg', 4, '{"title":"第2014015条・金匮要略15  黄疸","description":"<p>16、诸病黄家，但利其小便。假令脉浮，当以汗解之，宜$f{桂枝加黄芪汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2014015,"note":"","videoMemo":"","fangList":["桂枝加黄芪汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '16、诸病黄家，但利其小便。假令脉浮，当以汗解之，宜$f{桂枝加黄芪汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'r695ZbvlfYe');
