INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('06xY5OXNVKd', 4, '{"title":"第2016000条・金匮要略17  呕吐哕下利","description":"<p>1、夫呕家有痈脓，不可治呕，脓尽自愈。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2016000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '1、夫呕家有痈脓，不可治呕，脓尽自愈。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'oD03MgEA8f2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('X3CA4BE3Ivf', 4, '{"title":"第2016001条・金匮要略17  呕吐哕下利","description":"<p>2、先呕却渴者，此为欲解；先渴却呕者，为水停心下，此属饮家。呕家本渴，今反不渴者，以心下有支饮故也，此属支饮。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2016001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2、先呕却渴者，此为欲解；先渴却呕者，为水停心下，此属饮家。呕家本渴，今反不渴者，以心下有支饮故也，此属支饮。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'oD03MgEA8f2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RST48O2dBaY', 4, '{"title":"第2016002条・金匮要略17  呕吐哕下利","description":"<p>3、问曰：病人脉数，数为热，当消谷引食，而反吐者，何也？师曰：以发其汗，令阳微，膈气虚，脉乃数。数为客热，不能消谷，胃中虚冷故也。脉弦者，虚也，胃气无余，朝食暮吐，变为胃反。寒在于上，医反下之，今脉反弦，故名曰虚。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2016002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '3、问曰：病人脉数，数为热，当消谷引食，而反吐者，何也？师曰：以发其汗，令阳微，膈气虚，脉乃数。数为客热，不能消谷，胃中虚冷故也。脉弦者，虚也，胃气无余，朝食暮吐，变为胃反。寒在于上，医反下之，今脉反弦，故名曰虚。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'oD03MgEA8f2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AveYtbcjNb9', 4, '{"title":"第2016003条・金匮要略17  呕吐哕下利","description":"<p>4、寸口脉微而数，微则无气，无气则荣虚，荣虚则血不足，血不足则胸中冷。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2016003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '4、寸口脉微而数，微则无气，无气则荣虚，荣虚则血不足，血不足则胸中冷。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'oD03MgEA8f2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pKc4Cy2WVt6', 4, '{"title":"第2016004条・金匮要略17  呕吐哕下利","description":"<p>5、趺阳脉浮而涩，浮则为虚，涩则伤脾，脾伤则不磨，朝食暮吐，暮食朝吐，宿谷不化，名曰胃反。脉紧而涩，其病难治。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2016004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '5、趺阳脉浮而涩，浮则为虚，涩则伤脾，脾伤则不磨，朝食暮吐，暮食朝吐，宿谷不化，名曰胃反。脉紧而涩，其病难治。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'oD03MgEA8f2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n4eWdAuT65w', 4, '{"title":"第2016005条・金匮要略17  呕吐哕下利","description":"<p>6、病人欲吐者，不可下之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2016005,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '6、病人欲吐者，不可下之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'oD03MgEA8f2');
