INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hyh4AijJCd3', 4, '{"title":"第2016024条・金匮要略17  呕吐哕下利","description":"<p>25、下利，脉沉弦者，下重；脉大者，为未止；脉微弱数者，为欲自止，虽发热不死。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2016024,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '25、下利，脉沉弦者，下重；脉大者，为未止；脉微弱数者，为欲自止，虽发热不死。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'oD03MgEA8f2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MTBsekvT7J5', 4, '{"title":"第2016025条・金匮要略17  呕吐哕下利","description":"<p>26、下利，手足厥冷，无脉者，灸之不温。若脉不还，反微喘者，死。少阴负趺阳者，为顺也。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2016025,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '26、下利，手足厥冷，无脉者，灸之不温。若脉不还，反微喘者，死。少阴负趺阳者，为顺也。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'oD03MgEA8f2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8a85uWMaS91', 4, '{"title":"第2016026条・金匮要略17  呕吐哕下利","description":"<p>27、下利，有微热而渴，脉弱者，今自愈。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2016026,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '27、下利，有微热而渴，脉弱者，今自愈。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'oD03MgEA8f2');
