INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lMATwc1k2vV', 4, '{"title":"第2016033条・金匮要略17  呕吐哕下利","description":"<p>34、下利，脉沉而迟，其人面少赤，身有微热，下利清谷者，必郁冒，汗出而解，病人必微热。所以然者，其面戴阳，下虚故也。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2016033,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '34、下利，脉沉而迟，其人面少赤，身有微热，下利清谷者，必郁冒，汗出而解，病人必微热。所以然者，其面戴阳，下虚故也。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'oD03MgEA8f2');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZJS12DQbURG', 4, '{"title":"第2016034条・金匮要略17  呕吐哕下利","description":"<p>35、下利后，脉绝，手足厥冷，晬时脉还，手足温者生，脉不还者死。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2016034,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '35、下利后，脉绝，手足厥冷，晬时脉还，手足温者生，脉不还者死。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'oD03MgEA8f2');
