INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dI4iFvxOAVB', 4, '{"title":"第2017001条・金匮要略18  疮痈肠痈浸淫","description":"<p>2、师曰：诸痈肿，欲知有脓无脓，以手掩肿上，热者为有脓，不热者为无脓。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2017001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2、师曰：诸痈肿，欲知有脓无脓，以手掩肿上，热者为有脓，不热者为无脓。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'PMhMk20Dhlf');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EWrbju91Bm3', 4, '{"title":"第2017002条・金匮要略18  疮痈肠痈浸淫","description":"<p>3、肠痈之为病，其身甲错，腹皮急，按之濡，如肿状，腹无积聚，身无热，脉数，此为腹内有痈脓，$f{薏苡附子败酱散}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2017002,"note":"","videoMemo":"","fangList":["薏苡附子败酱散"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '3、肠痈之为病，其身甲错，腹皮急，按之濡，如肿状，腹无积聚，身无热，脉数，此为腹内有痈脓，$f{薏苡附子败酱散}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'PMhMk20Dhlf');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5kSnZ0WWtn4', 4, '{"title":"第2017003条・金匮要略18  疮痈肠痈浸淫","description":"<p>4、肠痈者，少腹肿痞，按之即痛如淋，小便自调，时时发热，自汗出，复恶寒。其脉迟紧者，脓未成，可下之，当有血。脉洪数者，脓已成，不可下也。$f{大黄牡丹汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2017003,"note":"","videoMemo":"","fangList":["大黄牡丹汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '4、肠痈者，少腹肿痞，按之即痛如淋，小便自调，时时发热，自汗出，复恶寒。其脉迟紧者，脓未成，可下之，当有血。脉洪数者，脓已成，不可下也。$f{大黄牡丹汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'PMhMk20Dhlf');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Lew7EzaeWSU', 4, '{"title":"第2017004条・金匮要略18  疮痈肠痈浸淫","description":"<p>5、问曰：寸口脉浮微而涩，然当亡血，若汗出，设不汗者云何？答曰：若身有疮，被刀斧所伤，亡血故也。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2017004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '5、问曰：寸口脉浮微而涩，然当亡血，若汗出，设不汗者云何？答曰：若身有疮，被刀斧所伤，亡血故也。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'PMhMk20Dhlf');
