INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xk1KttQMfZs', 4, '{"title":"第2018003条・金匮要略19  趺蹶手指臂肿转筋阴狐疝蛔虫","description":"<p>4、阴狐疝气者，偏有小大，时时上下，$f{蜘蛛散}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2018003,"note":"","videoMemo":"","fangList":["蜘蛛散"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '4、阴狐疝气者，偏有小大，时时上下，$f{蜘蛛散}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'iq3DOXRDnS0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I6lxjFOBVip', 4, '{"title":"第2018004条・金匮要略19  趺蹶手指臂肿转筋阴狐疝蛔虫","description":"<p>5、问曰：病腹痛有虫，其脉何以别之？师曰：腹中痛，其脉当沉，若弦，反洪大，故有蛔虫。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2018004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '5、问曰：病腹痛有虫，其脉何以别之？师曰：腹中痛，其脉当沉，若弦，反洪大，故有蛔虫。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'iq3DOXRDnS0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IiAbO5aSmEX', 4, '{"title":"第2018005条・金匮要略19  趺蹶手指臂肿转筋阴狐疝蛔虫","description":"<p>6、蛔虫之为病，令人吐涎，心痛发作有时，毒药不止，$f{甘草粉蜜汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2018005,"note":"","videoMemo":"","fangList":["甘草粉蜜汤"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '6、蛔虫之为病，令人吐涎，心痛发作有时，毒药不止，$f{甘草粉蜜汤}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'iq3DOXRDnS0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OymYJuwp0sr', 4, '{"title":"第2018006条・金匮要略19  趺蹶手指臂肿转筋阴狐疝蛔虫","description":"<p>7、蛔厥者，当吐蛔。今病者静而复时烦，此为脏寒，蛔上入膈，故烦。须臾复止，得食而呕，又烦者，蛔闻食臭出，其人当自吐蛔。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2018006,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '7、蛔厥者，当吐蛔。今病者静而复时烦，此为脏寒，蛔上入膈，故烦。须臾复止，得食而呕，又烦者，蛔闻食臭出，其人当自吐蛔。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'iq3DOXRDnS0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k2m4Zc5hCzi', 4, '{"title":"第2018007条・金匮要略19  趺蹶手指臂肿转筋阴狐疝蛔虫","description":"<p>8、蛔厥者，$f{乌梅丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2018007,"note":"","videoMemo":"","fangList":["乌梅丸"],"bieMing":""}}', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '2024-09-17T00:57:29.000Z', '8、蛔厥者，$f{乌梅丸}主之。', '2024-09-17T00:57:29.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'iq3DOXRDnS0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8RXeeyJvvzM', 4, '{"title":"第2019000条・金匮要略20  妇人妊娠病","description":"<p>1、师曰：妇人得平脉，阴脉小弱，其人渴，不能食，无寒热，名妊娠，$f{桂枝汤}主之。于法六十日当有此证，设有医治逆者，却一月加吐下者，则绝之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2019000,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '1、师曰：妇人得平脉，阴脉小弱，其人渴，不能食，无寒热，名妊娠，$f{桂枝汤}主之。于法六十日当有此证，设有医治逆者，却一月加吐下者，则绝之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '8S0wDzCseKv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xFd90ZRxtFt', 4, '{"title":"第2019001条・金匮要略20  妇人妊娠病","description":"<p>2、妇人宿有癥病，经断未及三月，而得漏下不止，胎动在脐上者，为癥痼害。妊娠六月动者，前三月经水利时，胎也。下血者，后断三月衃也。所以血不止者，其症不去故也。当下其症，$f{桂枝茯苓丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2019001,"note":"","videoMemo":"","fangList":["桂枝茯苓丸"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2、妇人宿有癥病，经断未及三月，而得漏下不止，胎动在脐上者，为癥痼害。妊娠六月动者，前三月经水利时，胎也。下血者，后断三月衃也。所以血不止者，其症不去故也。当下其症，$f{桂枝茯苓丸}主之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '8S0wDzCseKv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FpBf4vIklBJ', 4, '{"title":"第2019002条・金匮要略20  妇人妊娠病","description":"<p>3、妇人怀娠六七月，脉弦发热，其胎愈胀，腹痛恶寒者，少腹如扇。所以然者，子脏开故也，当以$f{附子汤}温其脏。$a{方未见。}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2019002,"note":"","videoMemo":"","fangList":["附子汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '3、妇人怀娠六七月，脉弦发热，其胎愈胀，腹痛恶寒者，少腹如扇。所以然者，子脏开故也，当以$f{附子汤}温其脏。$a{方未见。}', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '8S0wDzCseKv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WCQKWPwfRqf', 4, '{"title":"第2019003条・金匮要略20  妇人妊娠病","description":"<p>4、师曰：妇人有漏下者，有半产后因续下血都不绝者，有妊娠下血者。假令妊娠腹中痛，为胞阻，$f{芎归胶艾汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2019003,"note":"","videoMemo":"","fangList":["芎归胶艾汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '4、师曰：妇人有漏下者，有半产后因续下血都不绝者，有妊娠下血者。假令妊娠腹中痛，为胞阻，$f{芎归胶艾汤}主之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '8S0wDzCseKv');
