INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dBiLSbR0TDT', 4, '{"title":"第2019009条・金匮要略20  妇人妊娠病","description":"<p>10、妊娠养胎，$f{白术散}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2019009,"note":"","videoMemo":"","fangList":["白术散"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '10、妊娠养胎，$f{白术散}主之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '8S0wDzCseKv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HI0m4tqz67E', 4, '{"title":"第2019010条・金匮要略20  妇人妊娠病","description":"<p>11、妇人伤胎，怀身腹满，不得小便，从腰以下重，如有水气状，怀身七月，太阴当养不养，此心气实，当刺泻劳宫及关元，小便微利则愈。$a{见$q{《玉函》}。}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2019010,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '11、妇人伤胎，怀身腹满，不得小便，从腰以下重，如有水气状，怀身七月，太阴当养不养，此心气实，当刺泻劳宫及关元，小便微利则愈。$a{见$q{《玉函》}。}', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '8S0wDzCseKv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5Mtn4C5cApA', 4, '{"title":"第2020000条・金匮要略21  妇人产后病","description":"<p>1、问曰：新产妇人有三病，一者病痉，二者病郁冒，三者大便难，何谓也？师曰：新产血虚，多汗出，喜中风，故令病痉；亡血复汗，寒多，故令郁冒；亡津液，胃燥，故大便难。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2020000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '1、问曰：新产妇人有三病，一者病痉，二者病郁冒，三者大便难，何谓也？师曰：新产血虚，多汗出，喜中风，故令病痉；亡血复汗，寒多，故令郁冒；亡津液，胃燥，故大便难。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '5YLCsHs07RW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GwHM1VAvq7P', 4, '{"title":"第2020001条・金匮要略21  妇人产后病","description":"<p>2、产妇郁冒，其脉微弱，$a{呕}不能食，大便反坚，但头汗出。所以然者，血虚而厥，厥而必冒，冒家欲解，必大汗出。以血虚下厥，孤阳上出，故头汗出。所以产妇喜汗出者，亡阴血虚，阳气独盛，故当汗出，阴阳乃复。大便坚，呕不能食，$f{小柴胡汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2020001,"note":"","videoMemo":"","fangList":["小柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2、产妇郁冒，其脉微弱，$a{呕}不能食，大便反坚，但头汗出。所以然者，血虚而厥，厥而必冒，冒家欲解，必大汗出。以血虚下厥，孤阳上出，故头汗出。所以产妇喜汗出者，亡阴血虚，阳气独盛，故当汗出，阴阳乃复。大便坚，呕不能食，$f{小柴胡汤}主之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '5YLCsHs07RW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8I7BRkHFf2W', 4, '{"title":"第2020002条・金匮要略21  妇人产后病","description":"<p>3、病解能食，七八日更发热者，此为胃实，$f{大承气汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2020002,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '3、病解能食，七八日更发热者，此为胃实，$f{大承气汤}主之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '5YLCsHs07RW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('boI4s3X2Iye', 4, '{"title":"第2020003条・金匮要略21  妇人产后病","description":"<p>4、产后腹中㽲痛，$f{当归生姜羊肉汤}主之，并治腹中寒疝，虚劳不足。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2020003,"note":"","videoMemo":"","fangList":["当归生姜羊肉汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '4、产后腹中㽲痛，$f{当归生姜羊肉汤}主之，并治腹中寒疝，虚劳不足。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '5YLCsHs07RW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Aya6oTEeTJ8', 4, '{"title":"第2020004条・金匮要略21  妇人产后病","description":"<p>5、产后腹痛，烦满不得卧，$f{枳实芍药散}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2020004,"note":"","videoMemo":"","fangList":["枳实芍药散"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '5、产后腹痛，烦满不得卧，$f{枳实芍药散}主之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '5YLCsHs07RW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('b4fgdlF6IMV', 4, '{"title":"第2020005条・金匮要略21  妇人产后病","description":"<p>6、师曰：产妇腹痛，法当以$f{枳实芍药散}。假令不愈者，此为腹中有干血着脐下，宜$f{下瘀血汤}主之，亦主经水不利。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2020005,"note":"","videoMemo":"","fangList":["枳实芍药散","下瘀血汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '6、师曰：产妇腹痛，法当以$f{枳实芍药散}。假令不愈者，此为腹中有干血着脐下，宜$f{下瘀血汤}主之，亦主经水不利。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '5YLCsHs07RW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('41JzHWY9W3s', 4, '{"title":"第2020006条・金匮要略21  妇人产后病","description":"<p>7、产后七八日，无太阳证，少腹坚痛，此恶露不尽。不大便，烦躁发热，切脉微实，再倍发热，日晡时烦躁者，不食，食则谵语，至夜即愈，宜$f{大承气汤}主之。热在里，结在膀胱也。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2020006,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '7、产后七八日，无太阳证，少腹坚痛，此恶露不尽。不大便，烦躁发热，切脉微实，再倍发热，日晡时烦躁者，不食，食则谵语，至夜即愈，宜$f{大承气汤}主之。热在里，结在膀胱也。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '5YLCsHs07RW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7ZrJRImT7bm', 4, '{"title":"第2020007条・金匮要略21  妇人产后病","description":"<p>8、产后风，续之数十日不解，头微痛，恶寒，时时有热，心下闷，干呕汗出，虽久，阳旦证续在耳，可与$f{阳旦汤}。$a{即}$f{桂枝汤}$a{。}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2020007,"note":"","videoMemo":"","fangList":["阳旦汤","桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '8、产后风，续之数十日不解，头微痛，恶寒，时时有热，心下闷，干呕汗出，虽久，阳旦证续在耳，可与$f{阳旦汤}。$a{即}$f{桂枝汤}$a{。}', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '5YLCsHs07RW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wBxDW7570Ts', 4, '{"title":"第2020008条・金匮要略21  妇人产后病","description":"<p>9、产后中风发热，面正赤，喘而头痛，$f{竹叶汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2020008,"note":"","videoMemo":"","fangList":["竹叶汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '9、产后中风发热，面正赤，喘而头痛，$f{竹叶汤}主之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '5YLCsHs07RW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HHRPNWMh5yV', 4, '{"title":"第2020009条・金匮要略21  妇人产后病","description":"<p>10、妇人乳中虚，烦乱呕逆，安中益气，$f{竹皮大丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2020009,"note":"","videoMemo":"","fangList":["竹皮大丸"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '10、妇人乳中虚，烦乱呕逆，安中益气，$f{竹皮大丸}主之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '5YLCsHs07RW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SKU7Tdz6jeQ', 4, '{"title":"第2020010条・金匮要略21  妇人产后病","description":"<p>11、产后下利虚极，$f{白头翁加甘草阿胶汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2020010,"note":"","videoMemo":"","fangList":["白头翁加甘草阿胶汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '11、产后下利虚极，$f{白头翁加甘草阿胶汤}主之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '5YLCsHs07RW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('K4nhpkyy3TM', 4, '{"title":"第2020011条・金匮要略21  妇人产后病","description":"<p>*、$q{附方《千金》}$f{三物黄芩汤} 治妇人在草蓐，自发露得风。四肢苦烦热，头痛者，与$f{小柴胡汤}。头不痛但烦者，此汤主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2020011,"note":"","videoMemo":"","fangList":["三物黄芩汤","小柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '*、$q{附方《千金》}$f{三物黄芩汤} 治妇人在草蓐，自发露得风。四肢苦烦热，头痛者，与$f{小柴胡汤}。头不痛但烦者，此汤主之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '5YLCsHs07RW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Daw1PlM56uq', 4, '{"title":"第2020012条・金匮要略21  妇人产后病","description":"<p>*、$q{《千金》}内补$f{当归建中汤} 治妇人产后虚羸不足，腹中刺痛不止，吸吸少气，或苦少腹中急，摩痛引腰者，不能食饮。产后一月，日得四五剂为善，令人强壮，宜。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2020012,"note":"","videoMemo":"","fangList":["当归建中汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '*、$q{《千金》}内补$f{当归建中汤} 治妇人产后虚羸不足，腹中刺痛不止，吸吸少气，或苦少腹中急，摩痛引腰者，不能食饮。产后一月，日得四五剂为善，令人强壮，宜。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', '5YLCsHs07RW');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4jZRZRJAT9P', 4, '{"title":"第2021000条・金匮要略22  妇人杂病","description":"<p>1、妇人中风，七八日续来寒热，发作有时，经水适断，此为热入血室，其血必结，故使如疟状，发作有时，$f{小柴胡汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2021000,"note":"","videoMemo":"","fangList":["小柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '1、妇人中风，七八日续来寒热，发作有时，经水适断，此为热入血室，其血必结，故使如疟状，发作有时，$f{小柴胡汤}主之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'Krxf3cMWLQC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('glJebdlcFNg', 4, '{"title":"第2021001条・金匮要略22  妇人杂病","description":"<p>2、妇人伤寒发热，经水适来，昼日明了，暮则谵语，如见鬼状者，此为热入血室，治之无犯胃气及上二焦，必自愈。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2021001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2、妇人伤寒发热，经水适来，昼日明了，暮则谵语，如见鬼状者，此为热入血室，治之无犯胃气及上二焦，必自愈。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'Krxf3cMWLQC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2WT4aNTve5W', 4, '{"title":"第2021002条・金匮要略22  妇人杂病","description":"<p>3、妇人中风，发热恶寒，经水适来，得七八日，热除脉迟，身凉和，胸胁满，如结胸状，谵语者，此为热入血室也，当刺期门，随其实而取之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2021002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '3、妇人中风，发热恶寒，经水适来，得七八日，热除脉迟，身凉和，胸胁满，如结胸状，谵语者，此为热入血室也，当刺期门，随其实而取之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'Krxf3cMWLQC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vrNw3WFIEui', 4, '{"title":"第2021003条・金匮要略22  妇人杂病","description":"<p>4、阳明病，下血谵语者，此为热入血室，但头汗出，当刺期门，随其实而泻之，濈然汗出者愈。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2021003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '4、阳明病，下血谵语者，此为热入血室，但头汗出，当刺期门，随其实而泻之，濈然汗出者愈。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'Krxf3cMWLQC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Of5oPF76sfn', 4, '{"title":"第2021004条・金匮要略22  妇人杂病","description":"<p>5、妇人咽中如有炙脔，$f{半夏厚朴汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2021004,"note":"","videoMemo":"","fangList":["半夏厚朴汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '5、妇人咽中如有炙脔，$f{半夏厚朴汤}主之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'Krxf3cMWLQC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('56jzIBtDYhG', 4, '{"title":"第2021005条・金匮要略22  妇人杂病","description":"<p>6、妇人脏躁，喜悲伤欲哭，象如神灵所作，数欠伸，$f{甘麦大枣汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2021005,"note":"","videoMemo":"","fangList":["甘麦大枣汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '6、妇人脏躁，喜悲伤欲哭，象如神灵所作，数欠伸，$f{甘麦大枣汤}主之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'Krxf3cMWLQC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u9TxfUiui3r', 4, '{"title":"第2021006条・金匮要略22  妇人杂病","description":"<p>7、妇人吐涎沫，医反下之，心下即痞。当先治其吐涎沫，$f{小青龙汤}主之；涎沫止，乃治痞，$f{泻心汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2021006,"note":"","videoMemo":"","fangList":["小青龙汤","泻心汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '7、妇人吐涎沫，医反下之，心下即痞。当先治其吐涎沫，$f{小青龙汤}主之；涎沫止，乃治痞，$f{泻心汤}主之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'Krxf3cMWLQC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CodYwLNKOmH', 4, '{"title":"第2021007条・金匮要略22  妇人杂病","description":"<p>8、妇人之病，因虚、积冷、结气，为诸经水断绝，至有历年，血寒积结胞门，寒伤经络。凝坚在上，呕吐涎唾，久成肺痈，形体损分；在中盘结，绕脐寒疝，或两胁疼痛，与脏相连；或结热中，痛在关元。脉数无疮，肌若鱼鳞，时着男子，非止女身。在下未多，经候不匀。冷阴掣痛，少腹恶寒，或引腰脊，下根气街，气冲急痛，膝胫疼烦，奄忽眩冒，状如厥癫，或有忧惨，悲伤多嗔，此皆带下，非有鬼神，久则羸瘦，脉虚多寒。三十六病，千变万端，审脉阴阳，虚实紧弦，行其针药，治危得安，其虽同病，脉各异源，子当辨记，勿谓不然。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2021007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '8、妇人之病，因虚、积冷、结气，为诸经水断绝，至有历年，血寒积结胞门，寒伤经络。凝坚在上，呕吐涎唾，久成肺痈，形体损分；在中盘结，绕脐寒疝，或两胁疼痛，与脏相连；或结热中，痛在关元。脉数无疮，肌若鱼鳞，时着男子，非止女身。在下未多，经候不匀。冷阴掣痛，少腹恶寒，或引腰脊，下根气街，气冲急痛，膝胫疼烦，奄忽眩冒，状如厥癫，或有忧惨，悲伤多嗔，此皆带下，非有鬼神，久则羸瘦，脉虚多寒。三十六病，千变万端，审脉阴阳，虚实紧弦，行其针药，治危得安，其虽同病，脉各异源，子当辨记，勿谓不然。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'Krxf3cMWLQC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R26G45ucyfP', 4, '{"title":"第2021008条・金匮要略22  妇人杂病","description":"<p>9、问曰：妇人年五十所，病下利数十日不止，暮即发热，少腹里急，腹满，手掌烦热，唇口干燥，何也？师曰：此病属带下。何以故？曾经半产，瘀血在少腹不去，何以知之？其证唇口干燥，故知之。当以$f{温经汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2021008,"note":"","videoMemo":"","fangList":["温经汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '9、问曰：妇人年五十所，病下利数十日不止，暮即发热，少腹里急，腹满，手掌烦热，唇口干燥，何也？师曰：此病属带下。何以故？曾经半产，瘀血在少腹不去，何以知之？其证唇口干燥，故知之。当以$f{温经汤}主之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'Krxf3cMWLQC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hwGv5oXbq27', 4, '{"title":"第2021009条・金匮要略22  妇人杂病","description":"<p>10、带下经水不利，少腹满痛，经一月再见者，$f{土瓜根散}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2021009,"note":"","videoMemo":"","fangList":["土瓜根散"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '10、带下经水不利，少腹满痛，经一月再见者，$f{土瓜根散}主之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'Krxf3cMWLQC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ba3UaM7Y0XN', 4, '{"title":"第2021010条・金匮要略22  妇人杂病","description":"<p>11、寸口脉弦而大，弦则为减，大则为芤，减则为寒，芤则为虚，寒虚相抟，此名曰革，妇人则半产漏下，$f{旋覆花汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2021010,"note":"","videoMemo":"","fangList":["旋覆花汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '11、寸口脉弦而大，弦则为减，大则为芤，减则为寒，芤则为虚，寒虚相抟，此名曰革，妇人则半产漏下，$f{旋覆花汤}主之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'Krxf3cMWLQC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('12mlrdfdCHK', 4, '{"title":"第2021011条・金匮要略22  妇人杂病","description":"<p>12、妇人陷经，漏下，黑不解，$f{胶姜汤}主之。$a{臣亿等校诸本无胶姜汤方，想是前妊娠中}$f{芎归胶艾汤}$a{。}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2021011,"note":"","videoMemo":"","fangList":["胶姜汤","芎归胶艾汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '12、妇人陷经，漏下，黑不解，$f{胶姜汤}主之。$a{臣亿等校诸本无胶姜汤方，想是前妊娠中}$f{芎归胶艾汤}$a{。}', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'Krxf3cMWLQC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('h2TA9McMudD', 4, '{"title":"第2021012条・金匮要略22  妇人杂病","description":"<p>13、妇人少腹满如敦状，小便微难而不渴，生后者，此为水与血并结在血室也，$f{大黄甘遂汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2021012,"note":"","videoMemo":"","fangList":["大黄甘遂汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '13、妇人少腹满如敦状，小便微难而不渴，生后者，此为水与血并结在血室也，$f{大黄甘遂汤}主之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'Krxf3cMWLQC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('P0OFzOaQ9XH', 4, '{"title":"第2021013条・金匮要略22  妇人杂病","description":"<p>14、妇人经水不利下，$f{抵当汤}主之。$a{亦治男子膀胱满急有瘀血者。}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2021013,"note":"","videoMemo":"","fangList":["抵当汤"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '14、妇人经水不利下，$f{抵当汤}主之。$a{亦治男子膀胱满急有瘀血者。}', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'Krxf3cMWLQC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2fnr0WhOE16', 4, '{"title":"第2021014条・金匮要略22  妇人杂病","description":"<p>15、妇人经水闭不利，脏坚癖不止，中有干血，下白物，$f{矾石丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2021014,"note":"","videoMemo":"","fangList":["矾石丸"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '15、妇人经水闭不利，脏坚癖不止，中有干血，下白物，$f{矾石丸}主之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'Krxf3cMWLQC');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('g9fMDx3gvj7', 4, '{"title":"第2021015条・金匮要略22  妇人杂病","description":"<p>16、妇人六十二种风，及腹中血气刺痛，$f{红蓝花酒}主之。$a{疑非仲景方。}</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2021015,"note":"","videoMemo":"","fangList":["红蓝花酒"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '16、妇人六十二种风，及腹中血气刺痛，$f{红蓝花酒}主之。$a{疑非仲景方。}', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'Krxf3cMWLQC');
