INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n4c2R6GqAPX', 4, '{"title":"第2021018条・金匮要略22  妇人杂病","description":"<p>19、问曰：妇人病，饮食如故，烦热不得卧，而反倚息者，何也？师曰：此名转胞，不得溺也。以胞系了戾，故致此病。但利小便则愈，宜$f{肾气丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"ydyQltIuQv6","receiptNo":2021018,"note":"","videoMemo":"","fangList":["肾气丸"],"bieMing":""}}', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '2024-09-17T00:57:30.000Z', '19、问曰：妇人病，饮食如故，烦热不得卧，而反倚息者，何也？师曰：此名转胞，不得溺也。以胞系了戾，故致此病。但利小便则愈，宜$f{肾气丸}主之。', '2024-09-17T00:57:30.000Z', 1, NULL, 'ydyQltIuQv6', 'section', 'Krxf3cMWLQC');
