INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1ctKEbsM4OC', 1, '{"title":"栝楼桂枝汤","description":"<p>1、$f{栝楼桂枝汤} $m{6味} $u{栝楼根}$w{二两}，$u{桂枝}$w{三两}，$u{芍药}$w{三两}，$u{甘草}$w{二两}，$u{生姜}$w{三两}，$u{大枣}$w{十二枚}</p>\n<p>\t$s{右六味}，以水九升，煮取三升。分温三服，取微汗。汗不出，食顷，啜热粥发之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":1,"yaoCount":6,"drinkNum":3,"yaoList":["栝楼根","桂枝","芍药","甘草","生姜","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"pyZLleBsXOb","amount":"二两","weight":200,"suffix":"","showName":"栝楼根","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":300,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:51.000Z', '2024-09-17T00:59:51.000Z', '2024-09-17T00:59:51.000Z', '1、$f{栝楼桂枝汤} $m{6味} $u{栝楼根}$w{二两}，$u{桂枝}$w{三两}，$u{芍药}$w{三两}，$u{甘草}$w{二两}，$u{生姜}$w{三两}，$u{大枣}$w{十二枚} $s{右六味}，以水九升，煮取三升。分温三服，取微汗。汗不出，食顷，啜热粥发之。', '2024-09-17T00:59:51.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OTFK3HCa5ls', 1, '{"title":"葛根汤","description":"<p>2、$f{葛根汤} $m{7味} $u{葛根}$w{四两}，$u{麻黄}$w{三两，去节}，$u{桂枝}$w{三两，去皮}，$u{芍药}$w{二两}，$u{甘草}$w{二两，炙}，$u{生姜}$w{三两}，$u{大枣}$w{十二枚}</p>\n<p>\t$s{右七味}，㕮咀，以水七升，先煮麻黄、葛根，减二升，去沫，内诸药，煮取三升，去滓。温服一升，覆取微似汗，不须啜粥，余如桂枝汤法将息及禁忌。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":2,"yaoCount":7,"drinkNum":3,"yaoList":["葛根","麻黄","桂枝","芍药","甘草","生姜","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"MzvPguhXJ5G","amount":"四两","weight":400,"suffix":"","showName":"葛根","extraProcess":"切"},{"yaoId":"nxz0hvgpJJf","amount":"三两","weight":300,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"二两","weight":200,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '2、$f{葛根汤} $m{7味} $u{葛根}$w{四两}，$u{麻黄}$w{三两，去节}，$u{桂枝}$w{三两，去皮}，$u{芍药}$w{二两}，$u{甘草}$w{二两，炙}，$u{生姜}$w{三两}，$u{大枣}$w{十二枚} $s{右七味}，㕮咀，以水七升，先煮麻黄、葛根，减二升，去沫，内诸药，煮取三升，去滓。温服一升，覆取微似汗，不须啜粥，余如桂枝汤法将息及禁忌。', '2024-09-17T00:59:52.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PQMJRyCuzdl', 1, '{"title":"大承气汤","description":"<p>3、$f{大承气汤} $m{4味} $u{大黄}$w{四两，$u{酒}洗}，$u{厚朴}$w{半斤，炙，去皮}，$u{枳实}$w{五枚，炙}，$u{芒硝}$w{三合}</p>\n<p>\t$s{右四味}，以水一斗，先煮二物，取五升，去滓，内大黄，煮取二升，去滓，内芒硝，更上火微一二沸。分温再服，得下止服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":3,"yaoCount":5,"drinkNum":2,"yaoList":["大黄","酒","厚朴","枳实","芒硝"],"fangList":[],"fangYaoList":[{"yaoId":"To31b37bc6Z","amount":"四两","weight":400,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":"8714SID7nWu","amount":"半斤","weight":800,"suffix":"","showName":"厚朴","extraProcess":"切"},{"yaoId":"FRaBwjHoVui","amount":"5枚","weight":50,"suffix":"","showName":"枳实","extraProcess":"切"},{"yaoId":"J7mL6gla0C0","amount":"三合","weight":300,"suffix":"","showName":"芒硝","extraProcess":"切"}]}}', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '3、$f{大承气汤} $m{4味} $u{大黄}$w{四两，$u{酒}洗}，$u{厚朴}$w{半斤，炙，去皮}，$u{枳实}$w{五枚，炙}，$u{芒硝}$w{三合} $s{右四味}，以水一斗，先煮二物，取五升，去滓，内大黄，煮取二升，去滓，内芒硝，更上火微一二沸。分温再服，得下止服。', '2024-09-17T00:59:52.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bKzIF0OhoR3', 1, '{"title":"麻黄加术汤","description":"<p>4、$f{麻黄加术汤} $m{5味} $u{麻黄}$w{三两，去节}，$u{桂枝}$w{二两，去皮}，$u{甘草}$w{一两，炙}，$u{杏仁}$w{七十个，去皮尖}，$u{白术}$w{四两}</p>\n<p>\t$s{右五味}，以水九升，先煮麻黄，减二升，去上沫，内诸药，煮取二升半，去滓。温服八合，覆取微似汗。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":4,"yaoCount":5,"drinkNum":3,"yaoList":["麻黄","桂枝","甘草","杏仁","白术"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"三两","weight":300,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"二两","weight":200,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":null,"amount":"一两","weight":100,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"Hs7PKqMqKRj","amount":"70个","weight":700,"suffix":"","showName":"杏仁","extraProcess":"切"},{"yaoId":"UIYZOmiE2xW","amount":"四两","weight":400,"suffix":"","showName":"白术","extraProcess":"切"}]}}', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '4、$f{麻黄加术汤} $m{5味} $u{麻黄}$w{三两，去节}，$u{桂枝}$w{二两，去皮}，$u{甘草}$w{一两，炙}，$u{杏仁}$w{七十个，去皮尖}，$u{白术}$w{四两} $s{右五味}，以水九升，先煮麻黄，减二升，去上沫，内诸药，煮取二升半，去滓。温服八合，覆取微似汗。', '2024-09-17T00:59:52.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uX5Yur6VHjl', 1, '{"title":"麻黄杏仁薏苡甘草汤","description":"<p>5、$f{麻黄杏仁薏苡甘草汤} $m{4味} $u{麻黄}$w{去节，半两，汤泡}，$u{甘草}$w{一两，炙}，$u{薏苡仁}$w{半两}，$u{杏仁}$w{十个，去皮尖，炒}</p>\n<p>\t$s{右四味}，剉麻豆大，每服四钱匕，水盏半，煮八分，去滓。温服，有微汗，避风。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":5,"yaoCount":4,"drinkNum":3,"yaoList":["麻黄","甘草","薏苡仁","杏仁"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"半两","weight":50,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":null,"amount":"一两","weight":100,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"rOi0RaqbWeB","amount":"半两","weight":50,"suffix":"","showName":"薏苡仁","extraProcess":"切"},{"yaoId":"Hs7PKqMqKRj","amount":"10个","weight":100,"suffix":"","showName":"杏仁","extraProcess":"切"}]}}', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '5、$f{麻黄杏仁薏苡甘草汤} $m{4味} $u{麻黄}$w{去节，半两，汤泡}，$u{甘草}$w{一两，炙}，$u{薏苡仁}$w{半两}，$u{杏仁}$w{十个，去皮尖，炒} $s{右四味}，剉麻豆大，每服四钱匕，水盏半，煮八分，去滓。温服，有微汗，避风。', '2024-09-17T00:59:52.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('omM04PmNFUU', 1, '{"title":"防己黄芪汤","description":"<p>6、$f{防己黄芪汤} $m{6味} $u{防己}$w{一两}，$u{甘草}$w{半两，炒}，$u{白术}$w{七钱半}，$u{黄芪}$w{一两一分，去芦}</p>\n<p>\t$s{右四味}，剉麻豆大，每抄五钱匕，$u{生姜}$w{四片}，$u{大枣}$w{一枚}，水盏半，煎八分，去滓。温服，良久再服。喘者，加$u{麻黄}$w{半两}；胃中不和者，加$u{芍药}$w{三分}；气上冲者，加$u{桂枝}$w{三分}；下有陈寒者，加$u{细辛}$w{三分}。服后当如虫行皮中，从腰下如冰，后坐被上，又以一被绕腰以下，温，令微汗，差。$q{《外台》}：治风水。脉浮为在表，其人或头汗出，表无他病，病者但下重，从腰以上为和，腰以下当肿及阴，难以屈伸。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":6,"yaoCount":10,"drinkNum":3,"yaoList":["防己","甘草","白术","黄芪","生姜","大枣","麻黄","芍药","桂枝","细辛"],"fangList":[],"fangYaoList":[{"yaoId":"M9HezPeSGkC","amount":"一两","weight":100,"suffix":"","showName":"防己","extraProcess":"切"},{"yaoId":null,"amount":"半两","weight":50,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"UIYZOmiE2xW","amount":"七钱半","weight":75,"suffix":"","showName":"白术","extraProcess":"切"},{"yaoId":"i7j1zMcc48a","amount":"一两一分","weight":125,"suffix":"","showName":"黄芪","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"4片(1服)","weight":30,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"1枚(1服)","weight":10,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '6、$f{防己黄芪汤} $m{6味} $u{防己}$w{一两}，$u{甘草}$w{半两，炒}，$u{白术}$w{七钱半}，$u{黄芪}$w{一两一分，去芦} $s{右四味}，剉麻豆大，每抄五钱匕，$u{生姜}$w{四片}，$u{大枣}$w{一枚}，水盏半，煎八分，去滓。温服，良久再服。喘者，加$u{麻黄}$w{半两}；胃中不和者，加$u{芍药}$w{三分}；气上冲者，加$u{桂枝}$w{三分}；下有陈寒者，加$u{细辛}$w{三分}。服后当如虫行皮中，从腰下如冰，后坐被上，又以一被绕腰以下，温，令微汗，差。$q{《外台》}：治风水。脉浮为在表，其人或头汗出，表无他病，病者但下重，从腰以上为和，腰以下当肿及阴，难以屈伸。', '2024-09-17T00:59:52.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VzxqhWiHKdX', 1, '{"title":"桂枝附子汤","description":"<p>7、$f{桂枝附子汤} $m{5味} $u{桂枝}$w{四两，去皮}，$u{生姜}$w{三两，切}，$u{附子}$w{三枚，炮，去皮，破八片}，$u{甘草}$w{二两，炙}，$u{大枣}$w{十二枚，擘}</p>\n<p>\t$s{右五味}，以水六升，煮取二升，去滓，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":7,"yaoCount":5,"drinkNum":3,"yaoList":["桂枝","生姜","附子","甘草","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"四两","weight":400,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"3枚炮","weight":300,"suffix":"","showName":"附子","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '7、$f{桂枝附子汤} $m{5味} $u{桂枝}$w{四两，去皮}，$u{生姜}$w{三两，切}，$u{附子}$w{三枚，炮，去皮，破八片}，$u{甘草}$w{二两，炙}，$u{大枣}$w{十二枚，擘} $s{右五味}，以水六升，煮取二升，去滓，分温三服。', '2024-09-17T00:59:52.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zMmTda3OEWB', 1, '{"title":"白术附子汤","description":"<p>8、$f{白术附子汤} $m{5味} $u{白术}$w{二两}，$u{附子}$w{一枚半，炮，去皮}，$u{甘草}$w{一两，炙}，$u{生姜}$w{一两半，切}，$u{大枣}$w{六枚}</p>\n<p>\t$s{右五味}，以水三升，煮取一升，去滓，分温三服。一服觉身痹，半日许再服，三服都尽，其人如冒状，勿怪，即是术、附并走皮中逐水气，未得除故耳。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":8,"yaoCount":5,"drinkNum":3,"yaoList":["白术","附子","甘草","生姜","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"UIYZOmiE2xW","amount":"二两","weight":200,"suffix":"","showName":"白术","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"1.5枚炮","weight":150,"suffix":"","showName":"附子","extraProcess":"切"},{"yaoId":null,"amount":"一两","weight":100,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"一两半","weight":150,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"6枚","weight":60,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '8、$f{白术附子汤} $m{5味} $u{白术}$w{二两}，$u{附子}$w{一枚半，炮，去皮}，$u{甘草}$w{一两，炙}，$u{生姜}$w{一两半，切}，$u{大枣}$w{六枚} $s{右五味}，以水三升，煮取一升，去滓，分温三服。一服觉身痹，半日许再服，三服都尽，其人如冒状，勿怪，即是术、附并走皮中逐水气，未得除故耳。', '2024-09-17T00:59:52.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('m8nzFrMLlHt', 1, '{"title":"甘草附子汤","description":"<p>9、$f{甘草附子汤} $m{4味} $u{甘草}$w{二两，炙}，$u{附子}$w{二枚，炮，去皮}，$u{白术}$w{二两}，$u{桂枝}$w{四两，去皮}</p>\n<p>\t$s{右四味}，以水六升，煮取三升，去滓。温服一升，日三服。初服得微汗则解。能食，汗出复烦者，服五合。恐一升多者，服六七合为妙。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":9,"yaoCount":4,"drinkNum":3,"yaoList":["甘草","附子","白术","桂枝"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"2枚炮","weight":200,"suffix":"","showName":"附子","extraProcess":"切"},{"yaoId":"UIYZOmiE2xW","amount":"二两","weight":200,"suffix":"","showName":"白术","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"四两","weight":400,"suffix":"","showName":"桂枝","extraProcess":"切"}]}}', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '9、$f{甘草附子汤} $m{4味} $u{甘草}$w{二两，炙}，$u{附子}$w{二枚，炮，去皮}，$u{白术}$w{二两}，$u{桂枝}$w{四两，去皮} $s{右四味}，以水六升，煮取三升，去滓。温服一升，日三服。初服得微汗则解。能食，汗出复烦者，服五合。恐一升多者，服六七合为妙。', '2024-09-17T00:59:52.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xjnJr6kaOqJ', 1, '{"title":"白虎加人参汤","description":"<p>10、$f{白虎加人参汤} $m{5味} $u{知母}$w{六两}，$u{石膏}$w{一斤，碎}，$u{甘草}$w{二两}，$u{粳米}$w{六合}，$u{人参}$w{三两}</p>\n<p>\t$s{右五味}，以水一斗，煮米熟汤成，去滓。温服一升，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":10,"yaoCount":5,"drinkNum":3,"yaoList":["知母","石膏","甘草","粳米","人参"],"fangList":[],"fangYaoList":[{"yaoId":"PeV28d5T6et","amount":"六两","weight":600,"suffix":"","showName":"知母","extraProcess":"切"},{"yaoId":"S7mhkBtEhPL","amount":"一斤","weight":1600,"suffix":"","showName":"石膏","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"2gRWUBY7CiY","amount":"六合","weight":600,"suffix":"","showName":"粳米","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"三两","weight":300,"suffix":"","showName":"人参","extraProcess":"切"}]}}', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '10、$f{白虎加人参汤} $m{5味} $u{知母}$w{六两}，$u{石膏}$w{一斤，碎}，$u{甘草}$w{二两}，$u{粳米}$w{六合}，$u{人参}$w{三两} $s{右五味}，以水一斗，煮米熟汤成，去滓。温服一升，日三服。', '2024-09-17T00:59:52.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pj9PYtTLpfx', 1, '{"title":"一物瓜蒂汤","description":"<p>11、$f{一物瓜蒂汤} $m{1味} $u{瓜蒂}$w{二七个}</p>\n<p>\t$s{右剉}，以水一升，煮取五合，去滓，顿服。又治诸黄。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":11,"yaoCount":1,"drinkNum":1,"yaoList":["瓜蒂"],"fangList":[],"fangYaoList":[{"yaoId":"zdySy9e78kG","amount":"二七个","weight":100,"suffix":"","showName":"瓜蒂","extraProcess":"切"}]}}', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '11、$f{一物瓜蒂汤} $m{1味} $u{瓜蒂}$w{二七个} $s{右剉}，以水一升，煮取五合，去滓，顿服。又治诸黄。', '2024-09-17T00:59:52.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q9LyoYIG1hT', 1, '{"title":"百合知母汤","description":"<p>12、$f{百合知母汤} $m{2味} $u{百合}$w{七枚，擘}，$u{知母}$w{三两，切}</p>\n<p>\t$s{右先以水洗百合}，渍一宿，当白沫出，去其水，更以泉水二升，煎取一升，去滓；别以泉水二升煎知母，取一升，去滓；后合和煎，取一升五合。分温再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":12,"yaoCount":2,"drinkNum":2,"yaoList":["百合","知母"],"fangList":[],"fangYaoList":[{"yaoId":"4lJokf6uHXR","amount":"7枚","weight":70,"suffix":"","showName":"百合","extraProcess":"切"},{"yaoId":"PeV28d5T6et","amount":"三两","weight":300,"suffix":"","showName":"知母","extraProcess":"切"}]}}', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '12、$f{百合知母汤} $m{2味} $u{百合}$w{七枚，擘}，$u{知母}$w{三两，切} $s{右先以水洗百合}，渍一宿，当白沫出，去其水，更以泉水二升，煎取一升，去滓；别以泉水二升煎知母，取一升，去滓；后合和煎，取一升五合。分温再服。', '2024-09-17T00:59:52.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AiPL4xPgXeL', 1, '{"title":"滑石代赭汤","description":"<p>13、$f{滑石代赭汤} $m{3味} $u{百合}$w{七枚，擘}，$u{滑石}$w{三两，碎，绵裹}，$u{代赭石}$w{如弹丸大一枚，碎，绵裹}</p>\n<p>\t$s{右先以水洗百合}，渍一宿，当白沫出，去其水，更以泉水二升，煎取一升，去滓；别以泉水二升煎滑石、代赭，取一升，去滓；后合和重煎，取一升五合，分温服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":13,"yaoCount":3,"drinkNum":2,"yaoList":["百合","滑石","代赭石"],"fangList":[],"fangYaoList":[{"yaoId":"4lJokf6uHXR","amount":"7枚","weight":70,"suffix":"","showName":"百合","extraProcess":"切"},{"yaoId":"u6WaDjpcWhR","amount":"三两","weight":300,"suffix":"","showName":"滑石","extraProcess":"切"},{"yaoId":"woIsPez0Ouc","amount":"弹丸大一枚","weight":70,"suffix":"","showName":"代赭石","extraProcess":"切"}]}}', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '2024-09-17T00:59:52.000Z', '13、$f{滑石代赭汤} $m{3味} $u{百合}$w{七枚，擘}，$u{滑石}$w{三两，碎，绵裹}，$u{代赭石}$w{如弹丸大一枚，碎，绵裹} $s{右先以水洗百合}，渍一宿，当白沫出，去其水，更以泉水二升，煎取一升，去滓；别以泉水二升煎滑石、代赭，取一升，去滓；后合和重煎，取一升五合，分温服。', '2024-09-17T00:59:52.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PAVmUWxvTlL', 1, '{"title":"百合鸡子汤","description":"<p>14、$f{百合鸡子汤} $m{2味} $u{百合}$w{七枚，擘}，$u{鸡子黄}$w{一枚}</p>\n<p>\t$s{右先以水洗百合}，渍一宿，当白沫出，去其水，更以泉水二升，煎取一升，去滓，内鸡子黄，搅匀，煎五分，温服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":14,"yaoCount":2,"drinkNum":1,"yaoList":["百合","鸡子黄"],"fangList":[],"fangYaoList":[{"yaoId":"4lJokf6uHXR","amount":"7枚","weight":70,"suffix":"","showName":"百合","extraProcess":"切"},{"yaoId":"wDdw8s8LVWE","amount":"1枚","weight":100,"suffix":"","showName":"鸡子黄","extraProcess":"切"}]}}', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '14、$f{百合鸡子汤} $m{2味} $u{百合}$w{七枚，擘}，$u{鸡子黄}$w{一枚} $s{右先以水洗百合}，渍一宿，当白沫出，去其水，更以泉水二升，煎取一升，去滓，内鸡子黄，搅匀，煎五分，温服。', '2024-09-17T00:59:53.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lIdEsbdOfpi', 1, '{"title":"百合地黄汤","description":"<p>15、$f{百合地黄汤} $m{2味} $u{百合}$w{七枚，擘}，$u{生地黄}$w{汁一升}</p>\n<p>\t$s{右以水洗百合}，渍一宿，当白沫出，出其水，更以泉水二升，煎取一升，去滓，内地黄汁，煎取一升五合，分温再服。中病，勿更服，大便当如漆。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":15,"yaoCount":2,"drinkNum":3,"yaoList":["百合","生地黄"],"fangList":[],"fangYaoList":[{"yaoId":"4lJokf6uHXR","amount":"7枚","weight":70,"suffix":"","showName":"百合","extraProcess":"切"},{"yaoId":"B2o1hdSD6X1","amount":"汁一升","weight":2000,"suffix":"","showName":"生地黄","extraProcess":"切"}]}}', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '15、$f{百合地黄汤} $m{2味} $u{百合}$w{七枚，擘}，$u{生地黄}$w{汁一升} $s{右以水洗百合}，渍一宿，当白沫出，出其水，更以泉水二升，煎取一升，去滓，内地黄汁，煎取一升五合，分温再服。中病，勿更服，大便当如漆。', '2024-09-17T00:59:53.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3NC3HspBiBU', 1, '{"title":"百合洗","description":"<p>16、$f{百合洗} $m{1味} $u{百合}$w{一升}</p>\n<p>\t$s{右以百合一升}，以水一斗，渍之一宿，以洗身。洗已，食煮饼，勿以盐豉也。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":16,"yaoCount":1,"drinkNum":1,"yaoList":["百合"],"fangList":[],"fangYaoList":[{"yaoId":"4lJokf6uHXR","amount":"一升","weight":80,"suffix":"","showName":"百合","extraProcess":"切"}]}}', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '16、$f{百合洗} $m{1味} $u{百合}$w{一升} $s{右以百合一升}，以水一斗，渍之一宿，以洗身。洗已，食煮饼，勿以盐豉也。', '2024-09-17T00:59:53.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oVpl589SXTc', 1, '{"title":"栝楼牡蛎散","description":"<p>17、$f{栝楼牡蛎散} $m{2味} $u{栝楼根}，$u{牡蛎}$w{熬，等分}</p>\n<p>\t$s{右为细末}，饮服方寸匕，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":17,"yaoCount":2,"drinkNum":1,"yaoList":["栝楼根","牡蛎"],"fangList":[],"fangYaoList":[{"yaoId":"pyZLleBsXOb","amount":"1/2方寸匕","weight":5,"suffix":"","showName":"栝楼根","extraProcess":"切"},{"yaoId":"MDfiJ4S7u0U","amount":"1/2方寸匕","weight":5,"suffix":"","showName":"牡蛎","extraProcess":"切"}]}}', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '17、$f{栝楼牡蛎散} $m{2味} $u{栝楼根}，$u{牡蛎}$w{熬，等分} $s{右为细末}，饮服方寸匕，日三服。', '2024-09-17T00:59:53.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
