INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vwSbp3OGK15', 1, '{"title":"甘草泻心汤","description":"<p>19、$f{甘草泻心汤} $m{7味} $u{甘草}$w{四两}，$u{黄芩}，$u{人参}，$u{干姜}$w{各三两}，$u{黄连}$w{一两}，$u{大枣}$w{十二枚}，$u{半夏}$w{半斤}</p>\n<p>\t$s{右七味}，水一斗，煮取六升，去滓，再煎。温服一升，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":19,"yaoCount":7,"drinkNum":3,"yaoList":["甘草","黄芩","人参","干姜","黄连","大枣","半夏"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"四两","weight":400,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"三两","weight":300,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"三两","weight":300,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"三两","weight":300,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"5GP5Zyu6577","amount":"一两","weight":100,"suffix":"","showName":"黄连","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"半斤","weight":800,"suffix":"","showName":"半夏","extraProcess":"切"}]}}', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '19、$f{甘草泻心汤} $m{7味} $u{甘草}$w{四两}，$u{黄芩}，$u{人参}，$u{干姜}$w{各三两}，$u{黄连}$w{一两}，$u{大枣}$w{十二枚}，$u{半夏}$w{半斤} $s{右七味}，水一斗，煮取六升，去滓，再煎。温服一升，日三服。', '2024-09-17T00:59:53.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gOaI0aNN8Ul', 1, '{"title":"苦参汤","description":"<p>20、$f{苦参汤} $m{1味} $u{苦参}$w{一升}</p>\n<p>\t$s{以水一斗}，煎取七升，去滓，熏洗，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":20,"yaoCount":1,"drinkNum":3,"yaoList":["苦参"],"fangList":[],"fangYaoList":[{"yaoId":"udN4qy4NAcw","amount":"一升","weight":1000,"suffix":"","showName":"苦参","extraProcess":"切"}]}}', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '20、$f{苦参汤} $m{1味} $u{苦参}$w{一升} $s{以水一斗}，煎取七升，去滓，熏洗，日三服。', '2024-09-17T00:59:53.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aNsNI8im8eX', 1, '{"title":"雄黄","description":"<p>21、$f{雄黄} $m{1味} $u{雄黄}</p>\n<p>\t$s{右一味为末}，筒瓦二枚合之，烧，向肛熏之。$a{$q{《脉经》}云：病人或从呼吸上蚀其咽，或从下焦蚀其肛阴，蚀上为惑，蚀下为狐，狐惑病者，$f{猪苓散}主之。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":21,"yaoCount":1,"drinkNum":1,"yaoList":["雄黄"],"fangList":[],"fangYaoList":[{"yaoId":"Ul8euTuPbq0","amount":"熏用","weight":200,"suffix":"","showName":"雄黄","extraProcess":"切"}]}}', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '21、$f{雄黄} $m{1味} $u{雄黄} $s{右一味为末}，筒瓦二枚合之，烧，向肛熏之。$a{$q{《脉经》}云：病人或从呼吸上蚀其咽，或从下焦蚀其肛阴，蚀上为惑，蚀下为狐，狐惑病者，$f{猪苓散}主之。}', '2024-09-17T00:59:53.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BfkRSr1t91Z', 1, '{"title":"赤豆当归散","description":"<p>22、$f{赤豆当归散} $m{2味} $u{赤小豆}$w{三升，浸令芽出，曝干}，$u{当归}$w{三两}</p>\n<p>\t$s{右二味}，杵为散，浆水服方寸匕，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":22,"yaoCount":2,"drinkNum":180,"yaoList":["赤小豆","当归"],"fangList":[],"fangYaoList":[{"yaoId":"xoqRCmUZylQ","amount":"三升","weight":5000,"suffix":"","showName":"赤小豆","extraProcess":"切"},{"yaoId":"JFnirDnffR9","amount":"三两","weight":300,"suffix":"","showName":"当归","extraProcess":"切"}]}}', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '22、$f{赤豆当归散} $m{2味} $u{赤小豆}$w{三升，浸令芽出，曝干}，$u{当归}$w{三两} $s{右二味}，杵为散，浆水服方寸匕，日三服。', '2024-09-17T00:59:53.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QRUtGO1feFB', 1, '{"title":"升麻鳖甲汤","description":"<p>23、$f{升麻鳖甲汤} $m{6味} $u{升麻}$w{二两}，$u{当归}$w{一两}，$u{蜀椒}$w{炒去汗，一两}，$u{甘草}$w{二两}，$u{鳖甲}$w{手指大一片，炙}，$u{雄黄}$w{半两，研}</p>\n<p>\t$s{右六味}，以水四升，煮取一升，顿服之。老少再服，取汗。$a{$q{《肘后》}、$q{《千金方》}：阳毒用升麻汤，无鳖甲，有桂；阴毒用甘草汤，无雄黄。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":23,"yaoCount":6,"drinkNum":1,"yaoList":["升麻","当归","蜀椒","甘草","鳖甲","雄黄"],"fangList":[],"fangYaoList":[{"yaoId":"dgPXrO7Zcb7","amount":"二两","weight":200,"suffix":"","showName":"升麻","extraProcess":"切"},{"yaoId":"JFnirDnffR9","amount":"一两","weight":100,"suffix":"","showName":"当归","extraProcess":"切"},{"yaoId":"03dIYYkyQRn","amount":"一两","weight":100,"suffix":"","showName":"蜀椒","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"14GklrlZE7t","amount":"指甲大一片","weight":70,"suffix":"","showName":"鳖甲","extraProcess":"切"},{"yaoId":"Ul8euTuPbq0","amount":"半两","weight":50,"suffix":"","showName":"雄黄","extraProcess":"切"}]}}', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '23、$f{升麻鳖甲汤} $m{6味} $u{升麻}$w{二两}，$u{当归}$w{一两}，$u{蜀椒}$w{炒去汗，一两}，$u{甘草}$w{二两}，$u{鳖甲}$w{手指大一片，炙}，$u{雄黄}$w{半两，研} $s{右六味}，以水四升，煮取一升，顿服之。老少再服，取汗。$a{$q{《肘后》}、$q{《千金方》}：阳毒用升麻汤，无鳖甲，有桂；阴毒用甘草汤，无雄黄。}', '2024-09-17T00:59:53.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DK0i4Hil6DL', 1, '{"title":"鳖甲煎丸","description":"<p>24、$f{鳖甲煎丸} $m{23味} $u{鳖甲}$w{十二分，炙}，$u{乌扇}$w{三分，烧}，$u{黄芩}$w{三分}，$u{柴胡}$w{六分}，$u{鼠妇}$w{三分，熬}，$u{干姜}$w{三分}，$u{大黄}$w{三分}，$u{芍药}$w{五分}，$u{桂枝}$w{三分}，$u{葶苈}$w{一分，熬}，$u{石苇}$w{三分，去毛}，$u{厚朴}$w{三分}，$u{牡丹}$w{五分，去心}，$u{瞿麦}$w{二分}，$u{紫葳}$w{三分}，$u{半夏}$w{一分}，$u{人参}$w{一分}，$u{䗪虫}$w{五分，熬}，$u{阿胶}$w{三分，炙}，$u{蜂窠}$w{四分，熬}，$u{赤硝}$w{十二分}，$u{蜣螂}$w{六分，熬}，$u{桃仁}$w{二分}</p>\n<p>\t$s{右二十三味为末}，取$u{煅灶下灰}$w{一斗}，$u{清酒}$w{一斛五斗}，浸灰，候酒尽一半，着鳖甲于中，煮令泛烂如胶漆，绞取汁，内诸药，煎为丸，如梧子大。空心服七丸，日三服。$a{$q{《千金方》}鳖甲片十二片，又有海藻三分，大戟一分，䗪虫五分，无鼠妇、赤硝二味，以鳖甲和诸药为丸。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":24,"yaoCount":25,"drinkNum":50,"yaoList":["鳖甲","乌扇","黄芩","柴胡","鼠妇","干姜","大黄","芍药","桂枝","葶苈","石苇","厚朴","牡丹","瞿麦","紫葳","半夏","人参","䗪虫","阿胶","蜂窠","赤硝","蜣螂","桃仁","煅灶下灰","清酒"],"fangList":[],"fangYaoList":[{"yaoId":"14GklrlZE7t","amount":"十二分","weight":300,"suffix":"","showName":"鳖甲","extraProcess":"切"},{"yaoId":"PEcY2j6wjoH","amount":"三分","weight":75,"suffix":"","showName":"乌扇","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"三分","weight":75,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"JMfcgoRTH0J","amount":"六分","weight":150,"suffix":"","showName":"柴胡","extraProcess":"切"},{"yaoId":"xg7IDhYbYBc","amount":"三分","weight":75,"suffix":"","showName":"鼠妇","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"三分","weight":75,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"To31b37bc6Z","amount":"三分","weight":75,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"五分","weight":125,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三分","weight":75,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"jD7lvOl6QAj","amount":"一分","weight":25,"suffix":"","showName":"葶苈","extraProcess":"切"},{"yaoId":"BFmkWqxUMUs","amount":"三分","weight":75,"suffix":"","showName":"石苇","extraProcess":"切"},{"yaoId":"8714SID7nWu","amount":"三分","weight":75,"suffix":"","showName":"厚朴","extraProcess":"切"},{"yaoId":"nP2w4ZP4Yic","amount":"五分","weight":125,"suffix":"","showName":"牡丹","extraProcess":"切"},{"yaoId":"Ug7wsIcyGqw","amount":"二分","weight":50,"suffix":"","showName":"瞿麦","extraProcess":"切"},{"yaoId":"eOGYO6mpDY8","amount":"三分","weight":75,"suffix":"","showName":"紫葳","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"一分","weight":25,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"一分","weight":25,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"nMnl8EhuWTn","amount":"五分","weight":125,"suffix":"","showName":"䗪虫","extraProcess":"切"},{"yaoId":"T3B7gaA2R03","amount":"三分","weight":75,"suffix":"","showName":"阿胶","extraProcess":"切"},{"yaoId":"GuKvN0MgqAD","amount":"四分","weight":100,"suffix":"","showName":"蜂窠","extraProcess":"切"},{"yaoId":"VbIDIYURZdR","amount":"十二分","weight":300,"suffix":"","showName":"赤硝","extraProcess":"切"},{"yaoId":"46OxMBGC5c7","amount":"六分","weight":150,"suffix":"","showName":"蜣螂","extraProcess":"切"},{"yaoId":"k2cI79Wat6h","amount":"二分","weight":50,"suffix":"","showName":"桃仁","extraProcess":"切"}]}}', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '24、$f{鳖甲煎丸} $m{23味} $u{鳖甲}$w{十二分，炙}，$u{乌扇}$w{三分，烧}，$u{黄芩}$w{三分}，$u{柴胡}$w{六分}，$u{鼠妇}$w{三分，熬}，$u{干姜}$w{三分}，$u{大黄}$w{三分}，$u{芍药}$w{五分}，$u{桂枝}$w{三分}，$u{葶苈}$w{一分，熬}，$u{石苇}$w{三分，去毛}，$u{厚朴}$w{三分}，$u{牡丹}$w{五分，去心}，$u{瞿麦}$w{二分}，$u{紫葳}$w{三分}，$u{半夏}$w{一分}，$u{人参}$w{一分}，$u{䗪虫}$w{五分，熬}，$u{阿胶}$w{三分，炙}，$u{蜂窠}$w{四分，熬}，$u{赤硝}$w{十二分}，$u{蜣螂}$w{六分，熬}，$u{桃仁}$w{二分} $s{右二十三味为末}，取$u{煅灶下灰}$w{一斗}，$u{清酒}$w{一斛五斗}，浸灰，候酒尽一半，着鳖甲于中，煮令泛烂如胶漆，绞取汁，内诸药，煎为丸，如梧子大。空心服七丸，日三服。$a{$q{《千金方》}鳖甲片十二片，又有海藻三分，大戟一分，䗪虫五分，无鼠妇、赤硝二味，以鳖甲和诸药为丸。}', '2024-09-17T00:59:53.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3Unsv9ryAFb', 1, '{"title":"白虎加桂枝汤","description":"<p>25、$f{白虎加桂枝汤} $m{5味} $u{知母}$w{六两}，$u{甘草}$w{二两，炙}，$u{石膏}$w{一斤}，$u{粳米}$w{二合}，$u{桂枝}$w{去皮，三两}</p>\n<p>\t$s{右剉}，每五钱，水一盏半，煎至八分，去滓。温服，汗出愈。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":25,"yaoCount":5,"drinkNum":2,"yaoList":["桂枝","粳米","石膏","甘草","知母"],"fangList":[],"fangYaoList":[{"yaoId":"PeV28d5T6et","amount":"六两","weight":600,"suffix":"","showName":"知母","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"S7mhkBtEhPL","amount":"一斤","weight":1600,"suffix":"","showName":"石膏","extraProcess":"切"},{"yaoId":"2gRWUBY7CiY","amount":"二合","weight":200,"suffix":"","showName":"粳米","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"}]}}', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '25、$f{白虎加桂枝汤} $m{5味} $u{知母}$w{六两}，$u{甘草}$w{二两，炙}，$u{石膏}$w{一斤}，$u{粳米}$w{二合}，$u{桂枝}$w{去皮，三两} $s{右剉}，每五钱，水一盏半，煎至八分，去滓。温服，汗出愈。', '2024-09-17T00:59:53.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hrhUsXBAQHC', 1, '{"title":"蜀漆散","description":"<p>26、$f{蜀漆散} $m{3味} $u{蜀漆}$w{烧去腥}，$u{云母}$w{烧二日夜}，$u{龙骨}$w{等分}</p>\n<p>\t$s{右三味}，杵为散，未发前，以浆水服半钱。温疟加$u{蜀漆}$w{半分}，临发时，服一钱匕。$a{一方云母作云实。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":26,"yaoCount":3,"drinkNum":1,"yaoList":["蜀漆","云母","龙骨"],"fangList":[],"fangYaoList":[{"yaoId":"gFgG38KNuFm","amount":"1/3半钱","weight":2,"suffix":"","showName":"蜀漆","extraProcess":"切"},{"yaoId":"MN2tqTw73w6","amount":"1/3半钱","weight":2,"suffix":"","showName":"云母","extraProcess":"切"},{"yaoId":"vL3tFGA7NwL","amount":"1/3半钱","weight":2,"suffix":"","showName":"龙骨","extraProcess":"切"}]}}', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '26、$f{蜀漆散} $m{3味} $u{蜀漆}$w{烧去腥}，$u{云母}$w{烧二日夜}，$u{龙骨}$w{等分} $s{右三味}，杵为散，未发前，以浆水服半钱。温疟加$u{蜀漆}$w{半分}，临发时，服一钱匕。$a{一方云母作云实。}', '2024-09-17T00:59:53.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xSBd8g2ft5O', 1, '{"title":"牡蛎汤","description":"<p>27、$q{附《外台秘要》}$f{牡蛎汤} $m{4味} 治牡疟。</p>\n<p>\t$u{牡蛎}$w{四两，熬}，$u{麻黄}$w{四两，去节}，$u{甘草}$w{二两}，$u{蜀漆}$w{三两}</p>\n<p>\t$s{右四味}，以水八升，先煮蜀漆、麻黄，去上沫，得六升，内诸药，煮取二升，温服一升。若吐，则勿更服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":27,"yaoCount":4,"drinkNum":2,"yaoList":["牡蛎","麻黄","甘草","蜀漆"],"fangList":[],"fangYaoList":[{"yaoId":"MDfiJ4S7u0U","amount":"四两","weight":400,"suffix":"","showName":"牡蛎","extraProcess":"切"},{"yaoId":"nxz0hvgpJJf","amount":"四两","weight":400,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"gFgG38KNuFm","amount":"三两","weight":300,"suffix":"","showName":"蜀漆","extraProcess":"切"}]}}', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '2024-09-17T00:59:53.000Z', '27、$q{附《外台秘要》}$f{牡蛎汤} $m{4味} 治牡疟。 $u{牡蛎}$w{四两，熬}，$u{麻黄}$w{四两，去节}，$u{甘草}$w{二两}，$u{蜀漆}$w{三两} $s{右四味}，以水八升，先煮蜀漆、麻黄，去上沫，得六升，内诸药，煮取二升，温服一升。若吐，则勿更服。', '2024-09-17T00:59:53.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kApQ4CH4Yn0', 1, '{"title":"柴胡去半夏加栝楼汤","description":"<p>28、$q{附《外台秘要》}$f{柴胡去半夏加栝楼汤} $m{7味} 治疟病发渴者，亦治劳疟。</p>\n<p>\t$u{柴胡}$w{八两}，$u{人参}，$u{黄芩}，$u{甘草}$w{各三两}，$u{栝楼根}$w{四两}，$u{生姜}$w{二两}，$u{大枣}$w{十二枚}</p>\n<p>\t$s{右七味}，以水一斗二升，煮取六升，去滓，再煎取三升。温服一升，日二服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":28,"yaoCount":7,"drinkNum":3,"yaoList":["柴胡","人参","黄芩","甘草","栝楼根","生姜","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"JMfcgoRTH0J","amount":"八两","weight":800,"suffix":"","showName":"柴胡","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"三两","weight":300,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"三两","weight":300,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":null,"amount":"三两","weight":300,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"pyZLleBsXOb","amount":"四两","weight":400,"suffix":"","showName":"栝楼根","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"二两","weight":200,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '28、$q{附《外台秘要》}$f{柴胡去半夏加栝楼汤} $m{7味} 治疟病发渴者，亦治劳疟。 $u{柴胡}$w{八两}，$u{人参}，$u{黄芩}，$u{甘草}$w{各三两}，$u{栝楼根}$w{四两}，$u{生姜}$w{二两}，$u{大枣}$w{十二枚} $s{右七味}，以水一斗二升，煮取六升，去滓，再煎取三升。温服一升，日二服。', '2024-09-17T00:59:54.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iLFvg4skO14', 1, '{"title":"柴胡桂枝干姜汤","description":"<p>29、$q{附《外台秘要》}$f{柴胡桂枝干姜汤} $m{7味} 治疟寒多，微有热，或但寒不热。</p>\n<p>\t$u{柴胡}$w{半斤}，$u{桂枝}$w{三两，去皮}，$u{干姜}$w{二两}，$u{栝楼根}$w{四两}，$u{黄芩}$w{三两}，$u{牡蛎}$w{三两，熬}，$u{甘草}$w{二两，炙}</p>\n<p>\t$s{右七味}，以水一斗二升，煮取六升，去滓，再煎取三升。温服一升，日三服。初服微烦，复服汗出便愈。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":29,"yaoCount":7,"drinkNum":3,"yaoList":["柴胡","桂枝","干姜","栝楼根","黄芩","牡蛎","甘草"],"fangList":[],"fangYaoList":[{"yaoId":"JMfcgoRTH0J","amount":"半斤","weight":800,"suffix":"","showName":"柴胡","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"二两","weight":200,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"pyZLleBsXOb","amount":"四两","weight":400,"suffix":"","showName":"栝楼根","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"三两","weight":300,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"MDfiJ4S7u0U","amount":"三两","weight":300,"suffix":"","showName":"牡蛎","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"}]}}', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '29、$q{附《外台秘要》}$f{柴胡桂枝干姜汤} $m{7味} 治疟寒多，微有热，或但寒不热。 $u{柴胡}$w{半斤}，$u{桂枝}$w{三两，去皮}，$u{干姜}$w{二两}，$u{栝楼根}$w{四两}，$u{黄芩}$w{三两}，$u{牡蛎}$w{三两，熬}，$u{甘草}$w{二两，炙} $s{右七味}，以水一斗二升，煮取六升，去滓，再煎取三升。温服一升，日三服。初服微烦，复服汗出便愈。', '2024-09-17T00:59:54.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('g8ryVlpZ85A', 1, '{"title":"侯氏黑散","description":"<p>30、$f{侯氏黑散} $m{14味} 治大风，四肢烦重，心中恶寒不足者。$q{《外台》}治风癫。</p>\n<p>\t$u{菊花}$w{四十分}，$u{白术}$w{十分}，$u{细辛}$w{三分}，$u{茯苓}$w{三分}，$u{牡蛎}$w{三分}，$u{桔梗}$w{八分}，$u{防风}$w{十分}，$u{人参}$w{三分}，$u{矾石}$w{三分}，$u{黄芩}$w{五分}，$u{当归}$w{三分}，$u{干姜}$w{三分}，$u{芎䓖}$w{三分}，$u{桂枝}$w{三分}。</p>\n<p>\t$s{上十四味}，杵为散，$u{酒}服方寸匕，日一服。初服二十日，温酒调服，禁一切鱼、肉、大蒜，常宜冷食，六十日止，即药积在腹中不下也，热食即下矣，冷食自能助药力。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":30,"yaoCount":15,"drinkNum":60,"yaoList":["菊花","白术","细辛","茯苓","牡蛎","桔梗","防风","人参","矾石","黄芩","当归","干姜","芎䓖","桂枝","酒"],"fangList":[],"fangYaoList":[{"yaoId":"8ZuiC9ADA2V","amount":"四十分","weight":1000,"suffix":"","showName":"菊花","extraProcess":"切"},{"yaoId":"UIYZOmiE2xW","amount":"十分","weight":250,"suffix":"","showName":"白术","extraProcess":"切"},{"yaoId":"MCBshcFNHhk","amount":"三分","weight":75,"suffix":"","showName":"细辛","extraProcess":"切"},{"yaoId":"VHE7Y68l232","amount":"三分","weight":75,"suffix":"","showName":"茯苓","extraProcess":"切"},{"yaoId":"MDfiJ4S7u0U","amount":"三分","weight":75,"suffix":"","showName":"牡蛎","extraProcess":"切"},{"yaoId":"t7DkIvGNO8b","amount":"八分","weight":200,"suffix":"","showName":"桔梗","extraProcess":"切"},{"yaoId":"blvt71sB8Zu","amount":"十分","weight":250,"suffix":"","showName":"防风","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"三分","weight":75,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"ozDrmO1Ighz","amount":"三分","weight":75,"suffix":"","showName":"矾石","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"五分","weight":125,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"JFnirDnffR9","amount":"三分","weight":75,"suffix":"","showName":"当归","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"三分","weight":75,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"Sfmcy2PNzjm","amount":"三分","weight":75,"suffix":"","showName":"芎䓖","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三分","weight":75,"suffix":"","showName":"桂枝","extraProcess":"切"}]}}', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '30、$f{侯氏黑散} $m{14味} 治大风，四肢烦重，心中恶寒不足者。$q{《外台》}治风癫。 $u{菊花}$w{四十分}，$u{白术}$w{十分}，$u{细辛}$w{三分}，$u{茯苓}$w{三分}，$u{牡蛎}$w{三分}，$u{桔梗}$w{八分}，$u{防风}$w{十分}，$u{人参}$w{三分}，$u{矾石}$w{三分}，$u{黄芩}$w{五分}，$u{当归}$w{三分}，$u{干姜}$w{三分}，$u{芎䓖}$w{三分}，$u{桂枝}$w{三分}。 $s{上十四味}，杵为散，$u{酒}服方寸匕，日一服。初服二十日，温酒调服，禁一切鱼、肉、大蒜，常宜冷食，六十日止，即药积在腹中不下也，热食即下矣，冷食自能助药力。', '2024-09-17T00:59:54.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NsGNijoL9VI', 1, '{"title":"风引汤","description":"<p>31、$f{风引汤} $m{12味} 除热瘫癎。</p>\n<p>\t$u{大黄}，$u{干姜}，$u{龙骨}$w{各四两}，$u{桂枝}$w{三两}，$u{甘草}，$u{牡蛎}$w{各二两}，$u{寒水石}，$u{滑石}，$u{赤石脂}，$u{白石脂}，$u{紫石英}，$u{石膏}$w{各六两}。</p>\n<p>\t$s{上十二味}，杵，粗筛，以韦囊盛之。取三指撮，井花水三升，煮三沸，温服一升。$a{治打人风引，少小惊痫瘈疭，日数十发，医所不能疗，除热方。巢氏云：脚气宜风引汤。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":31,"yaoCount":12,"drinkNum":60,"yaoList":["大黄","干姜","龙骨","桂枝","甘草","牡蛎","寒水石","滑石","赤石脂","白石脂","紫石英","石膏"],"fangList":[],"fangYaoList":[{"yaoId":"To31b37bc6Z","amount":"四两","weight":400,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"四两","weight":400,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"vL3tFGA7NwL","amount":"四两","weight":400,"suffix":"","showName":"龙骨","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"MDfiJ4S7u0U","amount":"二两","weight":200,"suffix":"","showName":"牡蛎","extraProcess":"切"},{"yaoId":"i4fuYlgraQ2","amount":"六两","weight":600,"suffix":"","showName":"寒水石","extraProcess":"切"},{"yaoId":"u6WaDjpcWhR","amount":"六两","weight":600,"suffix":"","showName":"滑石","extraProcess":"切"},{"yaoId":"1rOkrjGOCab","amount":"六两","weight":600,"suffix":"","showName":"赤石脂","extraProcess":"切"},{"yaoId":"cSR0rsnZv7C","amount":"六两","weight":600,"suffix":"","showName":"白石脂","extraProcess":"切"},{"yaoId":"KeCSoielG2F","amount":"六两","weight":600,"suffix":"","showName":"紫石英","extraProcess":"切"},{"yaoId":"S7mhkBtEhPL","amount":"六两","weight":600,"suffix":"","showName":"石膏","extraProcess":"切"}]}}', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '31、$f{风引汤} $m{12味} 除热瘫癎。 $u{大黄}，$u{干姜}，$u{龙骨}$w{各四两}，$u{桂枝}$w{三两}，$u{甘草}，$u{牡蛎}$w{各二两}，$u{寒水石}，$u{滑石}，$u{赤石脂}，$u{白石脂}，$u{紫石英}，$u{石膏}$w{各六两}。 $s{上十二味}，杵，粗筛，以韦囊盛之。取三指撮，井花水三升，煮三沸，温服一升。$a{治打人风引，少小惊痫瘈疭，日数十发，医所不能疗，除热方。巢氏云：脚气宜风引汤。}', '2024-09-17T00:59:54.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yW9MPxQ0Ypi', 1, '{"title":"防己地黄汤","description":"<p>32、$f{防己地黄汤} $m{5味} 治病如狂状，妄行，独语不休，无寒热，其脉浮。</p>\n<p>\t$u{防己}$w{一分}，$u{桂枝}$w{三分}，$u{防风}$w{三分}，$u{甘草}$w{一分}。</p>\n<p>\t$s{上四味}，以$u{酒}$w{一杯}，渍之一宿，绞取汁。$u{生地黄}$w{二斤}，㕮咀，蒸之如斗米饭久，以铜器盛其汁，更绞地黄汁，和分再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":32,"yaoCount":6,"drinkNum":2,"yaoList":["防己","桂枝","防风","甘草","酒","生地黄"],"fangList":[],"fangYaoList":[{"yaoId":"M9HezPeSGkC","amount":"一分","weight":25,"suffix":"","showName":"防己","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三分","weight":75,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"blvt71sB8Zu","amount":"三分","weight":75,"suffix":"","showName":"防风","extraProcess":"切"},{"yaoId":null,"amount":"一分","weight":25,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"B2o1hdSD6X1","amount":"二斤蒸绞汁","weight":3200,"suffix":"","showName":"生地黄","extraProcess":"切"}]}}', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '32、$f{防己地黄汤} $m{5味} 治病如狂状，妄行，独语不休，无寒热，其脉浮。 $u{防己}$w{一分}，$u{桂枝}$w{三分}，$u{防风}$w{三分}，$u{甘草}$w{一分}。 $s{上四味}，以$u{酒}$w{一杯}，渍之一宿，绞取汁。$u{生地黄}$w{二斤}，㕮咀，蒸之如斗米饭久，以铜器盛其汁，更绞地黄汁，和分再服。', '2024-09-17T00:59:54.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5r5v6A1TriB', 1, '{"title":"头风摩散方","description":"<p>33、$f{头风摩散方} $m{2味} $u{大附子}$w{一枚，炮}，$u{盐}$w{等分}</p>\n<p>\t$s{上二味}，为散，沐了，以方寸匕，已摩疢上，令药力行。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":33,"yaoCount":2,"drinkNum":10,"yaoList":["大附子","盐"],"fangList":[],"fangYaoList":[{"yaoId":"jT011T7yIVO","amount":"1枚大者炮","weight":150,"suffix":"","showName":"大附子","extraProcess":"切"},{"yaoId":"DThHnTLC5ju","amount":"1枚附子大","weight":100,"suffix":"","showName":"盐","extraProcess":"切"}]}}', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '33、$f{头风摩散方} $m{2味} $u{大附子}$w{一枚，炮}，$u{盐}$w{等分} $s{上二味}，为散，沐了，以方寸匕，已摩疢上，令药力行。', '2024-09-17T00:59:54.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qudZkWGo0X2', 1, '{"title":"桂枝芍药知母汤","description":"<p>34、$f{桂枝芍药知母汤} $m{9味} $u{桂枝}$w{四两}，$u{芍药}$w{三两}，$u{甘草}$w{二两}，$u{麻黄}$w{二两}，$u{生姜}$w{五两}，$u{白术}$w{五两}，$u{知母}$w{四两}，$u{防风}$w{四两}，$u{附子}$w{二枚，炮}</p>\n<p>\t$s{右九味}，以水七升，煮取二升，温服七合，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":34,"yaoCount":9,"drinkNum":3,"yaoList":["桂枝","芍药","甘草","麻黄","生姜","白术","知母","防风","附子"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"四两","weight":400,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":300,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"nxz0hvgpJJf","amount":"二两","weight":200,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"五两","weight":500,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"UIYZOmiE2xW","amount":"五两","weight":500,"suffix":"","showName":"白术","extraProcess":"切"},{"yaoId":"PeV28d5T6et","amount":"四两","weight":400,"suffix":"","showName":"知母","extraProcess":"切"},{"yaoId":"blvt71sB8Zu","amount":"四两","weight":400,"suffix":"","showName":"防风","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"2枚炮","weight":200,"suffix":"","showName":"附子","extraProcess":"切"}]}}', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '34、$f{桂枝芍药知母汤} $m{9味} $u{桂枝}$w{四两}，$u{芍药}$w{三两}，$u{甘草}$w{二两}，$u{麻黄}$w{二两}，$u{生姜}$w{五两}，$u{白术}$w{五两}，$u{知母}$w{四两}，$u{防风}$w{四两}，$u{附子}$w{二枚，炮} $s{右九味}，以水七升，煮取二升，温服七合，日三服。', '2024-09-17T00:59:54.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('z7DT4nNCBXo', 1, '{"title":"乌头汤","description":"<p>35、$f{乌头汤} $m{5味} 治脚气疼痛，不可屈伸。</p>\n<p>\t$u{麻黄}，$u{芍药}，$u{黄芪}$w{各三两}，$u{甘草}$w{三两，炙}，$u{川乌}$w{五枚，㕮咀，以$u{蜜}二升，煎取一升，即出乌头}</p>\n<p>\t$s{右五味}，㕮咀四味，以水三升，煮取一升，去滓，内$u{蜜}煎中，更煎之。服七合，不知，尽服之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":35,"yaoCount":6,"drinkNum":3,"yaoList":["麻黄","芍药","黄芪","甘草","川乌","蜜"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"三两","weight":300,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":300,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"i7j1zMcc48a","amount":"三两","weight":300,"suffix":"","showName":"黄芪","extraProcess":"切"},{"yaoId":null,"amount":"三两","weight":300,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"dFbCWGnQmeQ","amount":"5枚","weight":500,"suffix":"","showName":"川乌","extraProcess":"切"}]}}', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '35、$f{乌头汤} $m{5味} 治脚气疼痛，不可屈伸。 $u{麻黄}，$u{芍药}，$u{黄芪}$w{各三两}，$u{甘草}$w{三两，炙}，$u{川乌}$w{五枚，㕮咀，以$u{蜜}二升，煎取一升，即出乌头} $s{右五味}，㕮咀四味，以水三升，煮取一升，去滓，内$u{蜜}煎中，更煎之。服七合，不知，尽服之。', '2024-09-17T00:59:54.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VBycvBZxZvR', 1, '{"title":"矾石汤","description":"<p>36、$f{矾石汤} $m{1味} 治脚气冲心</p>\n<p>\t$u{矾石}</p>\n<p>\t$s{上一味}，以浆水一斗五升，煎三、五沸，浸脚良。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":36,"yaoCount":1,"drinkNum":1,"yaoList":["矾石"],"fangList":[],"fangYaoList":[{"yaoId":"ozDrmO1Ighz","amount":"任意量","weight":500,"suffix":"","showName":"矾石","extraProcess":"切"}]}}', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '36、$f{矾石汤} $m{1味} 治脚气冲心 $u{矾石} $s{上一味}，以浆水一斗五升，煎三、五沸，浸脚良。', '2024-09-17T00:59:54.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vFyQsyNrfRI', 1, '{"title":"续命汤","description":"<p>37、$q{附方《古今录验》}$f{续命汤} $m{9味} 治中风痱，身体不能自收，口不能言，冒昧不知痛处，或拘急不得转侧。</p>\n<p>\t$u{麻黄}，$u{桂枝}，$u{当归}，$u{人参}，$u{石膏}，$u{干姜}，$u{甘草}$w{各三两}，$u{芎䓖}$w{一两}，$u{杏仁}$w{四十枚}</p>\n<p>\t$s{右九味}，以水一斗，煮取四升，温服一升，当小汗，薄覆脊，凭几坐，汗出则愈。不汗更服，无所禁，勿当风。并治但伏不得卧，咳逆上气，面目浮肿。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":37,"yaoCount":9,"drinkNum":4,"yaoList":["麻黄","桂枝","当归","人参","石膏","干姜","甘草","芎䓖","杏仁"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"三两","weight":300,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"JFnirDnffR9","amount":"三两","weight":300,"suffix":"","showName":"当归","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"三两","weight":300,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"S7mhkBtEhPL","amount":"三两","weight":300,"suffix":"","showName":"石膏","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"三两","weight":300,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":null,"amount":"三两","weight":300,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"Sfmcy2PNzjm","amount":"一两","weight":100,"suffix":"","showName":"芎䓖","extraProcess":"切"},{"yaoId":"Hs7PKqMqKRj","amount":"40枚","weight":400,"suffix":"","showName":"杏仁","extraProcess":"切"}]}}', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '37、$q{附方《古今录验》}$f{续命汤} $m{9味} 治中风痱，身体不能自收，口不能言，冒昧不知痛处，或拘急不得转侧。 $u{麻黄}，$u{桂枝}，$u{当归}，$u{人参}，$u{石膏}，$u{干姜}，$u{甘草}$w{各三两}，$u{芎䓖}$w{一两}，$u{杏仁}$w{四十枚} $s{右九味}，以水一斗，煮取四升，温服一升，当小汗，薄覆脊，凭几坐，汗出则愈。不汗更服，无所禁，勿当风。并治但伏不得卧，咳逆上气，面目浮肿。', '2024-09-17T00:59:54.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XASPSdTWsSU', 1, '{"title":"三黄汤","description":"<p>38、$q{《千金》}$f{三黄汤} $m{5味} 治中风手足拘急，百节疼痛，烦热心乱，恶寒，经日不欲饮食。</p>\n<p>\t$u{麻黄}$w{五分}，$u{独活}$w{四分}，$u{细辛}$w{二分}，$u{黄芪}$w{二分}，$u{黄芩}$w{三分}</p>\n<p>\t$s{右五味}，以水六升，煮取二升。分温三服，一服小汗，二服大汗。心热加$u{大黄}$w{二分}，腹满加$u{枳实}$w{一枚}，气逆加$u{人参}$w{三分}，悸加$u{牡蛎}$w{三分}，渴加$u{栝楼根}$w{三分}，先有寒加$u{附子}$w{一枚}。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":38,"yaoCount":11,"drinkNum":3,"yaoList":["麻黄","独活","细辛","黄芪","黄芩","大黄","枳实","人参","牡蛎","栝楼根","附子"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"五分","weight":125,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"SU1RKPtaRtw","amount":"四分","weight":100,"suffix":"","showName":"独活","extraProcess":"切"},{"yaoId":"MCBshcFNHhk","amount":"二分","weight":50,"suffix":"","showName":"细辛","extraProcess":"切"},{"yaoId":"i7j1zMcc48a","amount":"二分","weight":50,"suffix":"","showName":"黄芪","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"三分","weight":75,"suffix":"","showName":"黄芩","extraProcess":"切"}]}}', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '38、$q{《千金》}$f{三黄汤} $m{5味} 治中风手足拘急，百节疼痛，烦热心乱，恶寒，经日不欲饮食。 $u{麻黄}$w{五分}，$u{独活}$w{四分}，$u{细辛}$w{二分}，$u{黄芪}$w{二分}，$u{黄芩}$w{三分} $s{右五味}，以水六升，煮取二升。分温三服，一服小汗，二服大汗。心热加$u{大黄}$w{二分}，腹满加$u{枳实}$w{一枚}，气逆加$u{人参}$w{三分}，悸加$u{牡蛎}$w{三分}，渴加$u{栝楼根}$w{三分}，先有寒加$u{附子}$w{一枚}。', '2024-09-17T00:59:54.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Tl2MSyFaMy6', 1, '{"title":"术附子汤","description":"<p>39、$q{《近效方》}$f{术附子汤} $m{3味} 治风虚头重眩，苦极，不知食味，暖肌补中，益精气。</p>\n<p>\t$u{白术}$w{二两}，$u{附子}$w{一枚半，炮，去皮}，$u{甘草}$w{一两，炙}</p>\n<p>\t$s{右三味}，剉，每五钱匕，$u{姜}$w{五片}，$u{枣}$w{一枚}，水盏半，煎七分，去滓，温服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":39,"yaoCount":3,"drinkNum":3,"yaoList":["白术","附子","甘草"],"fangList":[],"fangYaoList":[{"yaoId":"UIYZOmiE2xW","amount":"二两","weight":200,"suffix":"","showName":"白术","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"1.5枚炮","weight":150,"suffix":"","showName":"附子","extraProcess":"切"},{"yaoId":null,"amount":"一两","weight":100,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"5片(1服)","weight":38,"suffix":"","showName":"姜","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"1枚(1服)","weight":10,"suffix":"","showName":"枣","extraProcess":"切"}]}}', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '39、$q{《近效方》}$f{术附子汤} $m{3味} 治风虚头重眩，苦极，不知食味，暖肌补中，益精气。 $u{白术}$w{二两}，$u{附子}$w{一枚半，炮，去皮}，$u{甘草}$w{一两，炙} $s{右三味}，剉，每五钱匕，$u{姜}$w{五片}，$u{枣}$w{一枚}，水盏半，煎七分，去滓，温服。', '2024-09-17T00:59:54.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7930gxg4rlI', 1, '{"title":"八味丸","description":"<p>40、$q{崔氏}$f{八味丸} $m{8味} 治脚气上入，少腹不仁。</p>\n<p>\t$u{干地黄}$w{八两}，$u{山茱萸}，$u{薯蓣}$w{各四两}，$u{泽泻}，$u{茯苓}，$u{牡丹皮}$w{各三两}，$u{桂枝}，$u{附子}$w{炮，各一两}</p>\n<p>\t$s{右八味}，末之，炼$u{蜜}和丸梧子大。$u{酒}下十五丸，日再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":40,"yaoCount":10,"drinkNum":20,"yaoList":["干地黄","山茱萸","薯蓣","泽泻","茯苓","牡丹皮","桂枝","附子","蜜","酒"],"fangList":[],"fangYaoList":[{"yaoId":"B2o1hdSD6X1","amount":"八两","weight":800,"suffix":"","showName":"干地黄","extraProcess":"切"},{"yaoId":"ASxxg5RfLMb","amount":"四两","weight":400,"suffix":"","showName":"山茱萸","extraProcess":"切"},{"yaoId":"n7KV9vTrthx","amount":"四两","weight":400,"suffix":"","showName":"薯蓣","extraProcess":"切"},{"yaoId":"TvTXZli2dE7","amount":"三两","weight":300,"suffix":"","showName":"泽泻","extraProcess":"切"},{"yaoId":"VHE7Y68l232","amount":"三两","weight":300,"suffix":"","showName":"茯苓","extraProcess":"切"},{"yaoId":"nP2w4ZP4Yic","amount":"三两","weight":300,"suffix":"","showName":"牡丹皮","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"一两","weight":100,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"一两炮","weight":100,"suffix":"","showName":"附子","extraProcess":"切"}]}}', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '2024-09-17T00:59:54.000Z', '40、$q{崔氏}$f{八味丸} $m{8味} 治脚气上入，少腹不仁。 $u{干地黄}$w{八两}，$u{山茱萸}，$u{薯蓣}$w{各四两}，$u{泽泻}，$u{茯苓}，$u{牡丹皮}$w{各三两}，$u{桂枝}，$u{附子}$w{炮，各一两} $s{右八味}，末之，炼$u{蜜}和丸梧子大。$u{酒}下十五丸，日再服。', '2024-09-17T00:59:54.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iD0sEt1AvQV', 1, '{"title":"越婢加术汤","description":"<p>41、$q{《千金方》}$f{越婢加术汤} $m{6味} 治肉极热，则身体津脱，腠理开，汗大泄，厉风气，下焦脚弱。</p>\n<p>\t$u{麻黄}$w{六两}，$u{石膏}$w{半斤}，$u{生姜}$w{三两}，$u{甘草}$w{二两}，$u{白术}$w{四两}，$u{大枣}$w{十五枚}</p>\n<p>\t$s{右六味}，以水六升，先煮麻黄，去上沫，内诸药，煮取三升，分温三服。恶风加$u{附子}$w{一枚，炮}。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":41,"yaoCount":6,"drinkNum":3,"yaoList":["麻黄","石膏","生姜","甘草","白术","大枣","附子"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"六两","weight":600,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"S7mhkBtEhPL","amount":"半斤","weight":800,"suffix":"","showName":"石膏","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"UIYZOmiE2xW","amount":"四两","weight":400,"suffix":"","showName":"白术","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"15枚","weight":150,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '41、$q{《千金方》}$f{越婢加术汤} $m{6味} 治肉极热，则身体津脱，腠理开，汗大泄，厉风气，下焦脚弱。 $u{麻黄}$w{六两}，$u{石膏}$w{半斤}，$u{生姜}$w{三两}，$u{甘草}$w{二两}，$u{白术}$w{四两}，$u{大枣}$w{十五枚} $s{右六味}，以水六升，先煮麻黄，去上沫，内诸药，煮取三升，分温三服。恶风加$u{附子}$w{一枚，炮}。', '2024-09-17T00:59:55.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('btldO97z0t2', 1, '{"title":"黄芪桂枝五物汤","description":"<p>42、$f{黄芪桂枝五物汤} $m{5味} $u{黄芪}$w{三两}，$u{芍药}$w{三两}，$u{桂枝}$w{三两}，$u{生姜}$w{六两}，$u{大枣}$w{十二枚}</p>\n<p>\t$s{右五味}，以水六升，煮取二升。温服七合，日三服。$a{一方有人参}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":42,"yaoCount":5,"drinkNum":3,"yaoList":["黄芪","芍药","桂枝","生姜","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"i7j1zMcc48a","amount":"三两","weight":300,"suffix":"","showName":"黄芪","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":300,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"六两","weight":600,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '42、$f{黄芪桂枝五物汤} $m{5味} $u{黄芪}$w{三两}，$u{芍药}$w{三两}，$u{桂枝}$w{三两}，$u{生姜}$w{六两}，$u{大枣}$w{十二枚} $s{右五味}，以水六升，煮取二升。温服七合，日三服。$a{一方有人参}', '2024-09-17T00:59:55.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yJWlXAPzjjT', 1, '{"title":"桂枝加龙骨牡蛎汤","description":"<p>43、$f{桂枝加龙骨牡蛎汤} $m{7味} $a{《小品》云：虚弱浮热汗出者，除桂，加白薇、附子各三分，故曰二加龙骨汤。}</p>\n<p>\t$u{桂枝}，$u{芍药}，$u{生姜}$w{各三两}，$u{甘草}$w{二两}，$u{大枣}$w{十二枚}，$u{龙骨}，$u{牡蛎}$w{各三两}</p>\n<p>\t$s{右七味}，以水七升，煮取三升，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":43,"yaoCount":7,"drinkNum":3,"yaoList":["桂枝","芍药","生姜","甘草","大枣","龙骨","牡蛎"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":300,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"vL3tFGA7NwL","amount":"三两","weight":300,"suffix":"","showName":"龙骨","extraProcess":"切"},{"yaoId":"MDfiJ4S7u0U","amount":"三两","weight":300,"suffix":"","showName":"牡蛎","extraProcess":"切"}]}}', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '43、$f{桂枝加龙骨牡蛎汤} $m{7味} $a{《小品》云：虚弱浮热汗出者，除桂，加白薇、附子各三分，故曰二加龙骨汤。} $u{桂枝}，$u{芍药}，$u{生姜}$w{各三两}，$u{甘草}$w{二两}，$u{大枣}$w{十二枚}，$u{龙骨}，$u{牡蛎}$w{各三两} $s{右七味}，以水七升，煮取三升，分温三服。', '2024-09-17T00:59:55.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('duFth7PLe3U', 1, '{"title":"天雄散","description":"<p>44、$f{天雄散} $m{4味} $u{天雄}$w{三两，炮}，$u{白术}$w{八两}，$u{桂枝}$w{六两}，$u{龙骨}$w{三两}</p>\n<p>\t$s{右四味}，杵为散，$u{酒}服半钱匕，日三服，不知，稍增之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":44,"yaoCount":5,"drinkNum":60,"yaoList":["天雄","白术","桂枝","龙骨","酒"],"fangList":[],"fangYaoList":[{"yaoId":"E5qbjuyOeWF","amount":"三两炮","weight":300,"suffix":"","showName":"天雄","extraProcess":"切"},{"yaoId":"UIYZOmiE2xW","amount":"八两","weight":800,"suffix":"","showName":"白术","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"六两","weight":600,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"vL3tFGA7NwL","amount":"三两","weight":300,"suffix":"","showName":"龙骨","extraProcess":"切"}]}}', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '44、$f{天雄散} $m{4味} $u{天雄}$w{三两，炮}，$u{白术}$w{八两}，$u{桂枝}$w{六两}，$u{龙骨}$w{三两} $s{右四味}，杵为散，$u{酒}服半钱匕，日三服，不知，稍增之。', '2024-09-17T00:59:55.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EBhIghdX4WC', 1, '{"title":"小建中汤","description":"<p>45、$f{小建中汤} $m{6味} $u{桂枝}$w{三两，去皮}，$u{甘草}$w{三两，炙}，$u{大枣}$w{十二枚}，$u{芍药}$w{六两}，$u{生姜}$w{二两}，$u{胶饴}$w{一升}</p>\n<p>\t$s{右六味}，以水七升，煮取三升，去滓，内胶饴，更上微火消解。温服一升，日三服。$a{呕家，不可用小建中汤，以甜故也。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":45,"yaoCount":6,"drinkNum":3,"yaoList":["桂枝","甘草","大枣","芍药","生姜","胶饴"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":null,"amount":"三两","weight":300,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"六两","weight":600,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"二两","weight":200,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"q7UHJJ3ORHQ","amount":"一升","weight":1000,"suffix":"","showName":"胶饴","extraProcess":"切"}]}}', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '45、$f{小建中汤} $m{6味} $u{桂枝}$w{三两，去皮}，$u{甘草}$w{三两，炙}，$u{大枣}$w{十二枚}，$u{芍药}$w{六两}，$u{生姜}$w{二两}，$u{胶饴}$w{一升} $s{右六味}，以水七升，煮取三升，去滓，内胶饴，更上微火消解。温服一升，日三服。$a{呕家，不可用小建中汤，以甜故也。}', '2024-09-17T00:59:55.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vId6aopLpwl', 1, '{"title":"黄芪建中汤","description":"<p>46、$f{黄芪建中汤} $m{7味} $u{桂枝}$w{三两，去皮}，$u{甘草}$w{三两，炙}，$u{大枣}$w{十二枚}，$u{芍药}$w{六两}，$u{生姜}$w{二两}，$u{胶饴}$w{一升}，$u{黄芪}$w{一两半}。</p>\n<p>\t$s{上七味}，以水七升，煮取三升，去滓，内胶饴，更上微火消解。温服一升，日三服。气短胸满者，加$u{生姜}；腹满者，去$u{枣}加$u{茯苓}$w{一两半}。及疗肺虚损不足，补气，加$u{半夏}$w{三两}。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":46,"yaoCount":7,"drinkNum":3,"yaoList":["桂枝","甘草","大枣","芍药","生姜","胶饴","黄芪","茯苓","半夏"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":null,"amount":"三两","weight":300,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"$x{腹满去大枣}12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"六两","weight":600,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"二两($x{气短胸闷加量})","weight":200,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"q7UHJJ3ORHQ","amount":"一升","weight":1000,"suffix":"","showName":"胶饴","extraProcess":"切"},{"yaoId":"i7j1zMcc48a","amount":"一两半","weight":150,"suffix":"","showName":"黄芪","extraProcess":"切"}]}}', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '46、$f{黄芪建中汤} $m{7味} $u{桂枝}$w{三两，去皮}，$u{甘草}$w{三两，炙}，$u{大枣}$w{十二枚}，$u{芍药}$w{六两}，$u{生姜}$w{二两}，$u{胶饴}$w{一升}，$u{黄芪}$w{一两半}。 $s{上七味}，以水七升，煮取三升，去滓，内胶饴，更上微火消解。温服一升，日三服。气短胸满者，加$u{生姜}；腹满者，去$u{枣}加$u{茯苓}$w{一两半}。及疗肺虚损不足，补气，加$u{半夏}$w{三两}。', '2024-09-17T00:59:55.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uRmbltiLHzs', 1, '{"title":"薯蓣丸","description":"<p>47、$f{薯蓣丸} $m{21味} $u{薯蓣}$w{三十分}，$u{当归}，$u{桂枝}，$u{曲}，$u{干地黄}，$u{豆黄卷}$w{各十分}，$u{甘草}$w{二十八分}，$u{人参}$w{七分}，$u{芎䓖}，$u{芍药}，$u{白术}，$u{麦门冬}，$u{杏仁}$w{各六分}，$u{柴胡}，$u{桔梗}，$u{茯苓}$w{各五分}，$u{阿胶}$w{七分}，$u{干姜}$w{三分}，$u{白敛}$w{二分}，$u{防风}$w{六分}，$u{大枣}$w{百枚，为膏}</p>\n<p>\t$s{右二十一味}，末之，炼$u{蜜}和丸，如弹子大。空腹$u{酒}服一丸，一百丸为剂。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":47,"yaoCount":23,"drinkNum":100,"yaoList":["薯蓣","当归","桂枝","曲","干地黄","豆黄卷","甘草","人参","芎䓖","芍药","白术","麦门冬","杏仁","柴胡","桔梗","茯苓","阿胶","干姜","白敛","防风","大枣","蜜","酒"],"fangList":[],"fangYaoList":[{"yaoId":"n7KV9vTrthx","amount":"三十分","weight":750,"suffix":"","showName":"薯蓣","extraProcess":"切"},{"yaoId":"JFnirDnffR9","amount":"十分","weight":250,"suffix":"","showName":"当归","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"十分","weight":250,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"5Z1Yvo95yHS","amount":"十分","weight":250,"suffix":"","showName":"曲","extraProcess":"切"},{"yaoId":"B2o1hdSD6X1","amount":"十分","weight":250,"suffix":"","showName":"干地黄","extraProcess":"切"},{"yaoId":"4u6mZMQmgVm","amount":"十分","weight":250,"suffix":"","showName":"豆黄卷","extraProcess":"切"},{"yaoId":null,"amount":"二十八分","weight":700,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"七分","weight":175,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"Sfmcy2PNzjm","amount":"六分","weight":150,"suffix":"","showName":"芎䓖","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"六分","weight":150,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"UIYZOmiE2xW","amount":"六分","weight":150,"suffix":"","showName":"白术","extraProcess":"切"},{"yaoId":"DDXydmiFQLK","amount":"六分","weight":150,"suffix":"","showName":"麦门冬","extraPro