INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7cICJTJ43Xm', 1, '{"title":"酸枣仁汤","description":"<p>48、$f{酸枣仁汤} $m{5味} $u{酸枣仁}$w{二升}，$u{甘草}$w{一两}，$u{知母}$w{二两}，$u{茯苓}$w{二两}，$u{芎䓖}$w{二两} $a{深师有生姜二两。}</p>\n<p>\t$s{右五味}，以水八升，煮酸枣仁，得六升，内诸药，煮取三升，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":48,"yaoCount":5,"drinkNum":3,"yaoList":["酸枣仁","甘草","知母","茯苓","芎䓖"],"fangList":[],"fangYaoList":[{"yaoId":"ODZGxGssDUt","amount":"二升","weight":2000,"suffix":"","showName":"酸枣仁","extraProcess":"切"},{"yaoId":null,"amount":"一两","weight":100,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"PeV28d5T6et","amount":"二两","weight":200,"suffix":"","showName":"知母","extraProcess":"切"},{"yaoId":"VHE7Y68l232","amount":"二两","weight":200,"suffix":"","showName":"茯苓","extraProcess":"切"},{"yaoId":"Sfmcy2PNzjm","amount":"二两","weight":200,"suffix":"","showName":"芎䓖","extraProcess":"切"}]}}', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '48、$f{酸枣仁汤} $m{5味} $u{酸枣仁}$w{二升}，$u{甘草}$w{一两}，$u{知母}$w{二两}，$u{茯苓}$w{二两}，$u{芎䓖}$w{二两} $a{深师有生姜二两。} $s{右五味}，以水八升，煮酸枣仁，得六升，内诸药，煮取三升，分温三服。', '2024-09-17T00:59:55.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ejv1CheIuVB', 1, '{"title":"大黄䗪虫丸","description":"<p>49、$f{大黄䗪虫丸} $m{12味} $u{大黄}$w{十分，蒸}，$u{黄芩}$w{二两}，$u{甘草}$w{三两}，$u{桃仁}$w{一升}，$u{杏仁}$w{一升}，$u{芍药}$w{四两}，$u{干地黄}$w{十两}，$u{干漆}$w{一两}，$u{虻虫}$w{一升}，$u{水蛭}$w{百枚}，$u{蛴螬}$w{一升}，$u{䗪虫}$w{半升}。</p>\n<p>\t$s{右十二味}，末之，炼$u{蜜}和丸小豆大。$u{酒}饮服五丸，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":49,"yaoCount":14,"drinkNum":100,"yaoList":["大黄","黄芩","甘草","桃仁","杏仁","芍药","干地黄","干漆","虻虫","水蛭","蛴螬","䗪虫","蜜","酒"],"fangList":[],"fangYaoList":[{"yaoId":"To31b37bc6Z","amount":"十分","weight":250,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"二两","weight":200,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":null,"amount":"三两","weight":300,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"k2cI79Wat6h","amount":"一升约267枚","weight":2670,"suffix":"","showName":"桃仁","extraProcess":"切"},{"yaoId":"Hs7PKqMqKRj","amount":"一升约300枚","weight":3000,"suffix":"","showName":"杏仁","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"四两","weight":400,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"B2o1hdSD6X1","amount":"十两","weight":1000,"suffix":"","showName":"干地黄","extraProcess":"切"},{"yaoId":"41gTtXf6W3Z","amount":"一两","weight":100,"suffix":"","showName":"干漆","extraProcess":"切"},{"yaoId":"L1yNgzB2bxB","amount":"一升约53个","weight":530,"suffix":"","showName":"虻虫","extraProcess":"切"},{"yaoId":"biroLUs3POn","amount":"100枚","weight":1000,"suffix":"","showName":"水蛭","extraProcess":"切"},{"yaoId":"97tN0MlutoJ","amount":"一升","weight":1000,"suffix":"","showName":"蛴螬","extraProcess":"切"},{"yaoId":"nMnl8EhuWTn","amount":"半升","weight":150,"suffix":"","showName":"䗪虫","extraProcess":"切"}]}}', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '49、$f{大黄䗪虫丸} $m{12味} $u{大黄}$w{十分，蒸}，$u{黄芩}$w{二两}，$u{甘草}$w{三两}，$u{桃仁}$w{一升}，$u{杏仁}$w{一升}，$u{芍药}$w{四两}，$u{干地黄}$w{十两}，$u{干漆}$w{一两}，$u{虻虫}$w{一升}，$u{水蛭}$w{百枚}，$u{蛴螬}$w{一升}，$u{䗪虫}$w{半升}。 $s{右十二味}，末之，炼$u{蜜}和丸小豆大。$u{酒}饮服五丸，日三服。', '2024-09-17T00:59:55.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ryaP46LHGjt', 1, '{"title":"炙甘草汤","description":"<p>50、$q{附方《千金翼》}$f{炙甘草汤} $m{9味} $a{一云复脉汤。}治虚劳不足，汗出而闷，脉结悸，行动如常，不出百日，危急者，十一日死。另有$q{《外台》}炙甘草汤，治肺痿涎唾多，心中温温液液者。</p>\n<p>\t$u{甘草}$w{四两，炙}，$u{桂枝}，$u{生姜}$w{各三两}，$u{麦门冬}$w{半升}，$u{麻子仁}$w{半升}，$u{人参}，$u{阿胶}$w{各二两}，$u{大枣}$w{三十枚}，$u{生地黄}$w{一斤}</p>\n<p>\t$s{右九味}，以$u{酒}七升，水八升，先煮八味，取三升，去滓，内胶消尽。温服一升，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":50,"yaoCount":10,"drinkNum":3,"yaoList":["甘草","桂枝","生姜","麦门冬","麻子仁","人参","阿胶","大枣","生地黄","酒"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"四两","weight":400,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"DDXydmiFQLK","amount":"半升","weight":300,"suffix":"","showName":"麦门冬","extraProcess":"切"},{"yaoId":"H0hYG4VYtXF","amount":"半升","weight":500,"suffix":"","showName":"麻子仁","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"二两","weight":200,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"T3B7gaA2R03","amount":"二两","weight":200,"suffix":"","showName":"阿胶","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"30枚","weight":300,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"B2o1hdSD6X1","amount":"一斤","weight":1600,"suffix":"","showName":"生地黄","extraProcess":"切"}]}}', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '50、$q{附方《千金翼》}$f{炙甘草汤} $m{9味} $a{一云复脉汤。}治虚劳不足，汗出而闷，脉结悸，行动如常，不出百日，危急者，十一日死。另有$q{《外台》}炙甘草汤，治肺痿涎唾多，心中温温液液者。 $u{甘草}$w{四两，炙}，$u{桂枝}，$u{生姜}$w{各三两}，$u{麦门冬}$w{半升}，$u{麻子仁}$w{半升}，$u{人参}，$u{阿胶}$w{各二两}，$u{大枣}$w{三十枚}，$u{生地黄}$w{一斤} $s{右九味}，以$u{酒}七升，水八升，先煮八味，取三升，去滓，内胶消尽。温服一升，日三服。', '2024-09-17T00:59:55.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('j4PAbHpndUJ', 1, '{"title":"獭肝散","description":"<p>51、$q{《肘后》}$f{獭肝散} $m{1味} 治冷劳，又主鬼疰一门相染。</p>\n<p>\t$u{獭肝}$w{一具}，炙干，末之。水服方寸匕，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":51,"yaoCount":1,"drinkNum":10,"yaoList":["獭肝"],"fangList":[],"fangYaoList":[{"yaoId":"A2daxyQ36Xs","amount":"一具","weight":100,"suffix":"","showName":"獭肝","extraProcess":"切"}]}}', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '51、$q{《肘后》}$f{獭肝散} $m{1味} 治冷劳，又主鬼疰一门相染。 $u{獭肝}$w{一具}，炙干，末之。水服方寸匕，日三服。', '2024-09-17T00:59:55.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aXA19PFwMeb', 1, '{"title":"甘草干姜汤","description":"<p>52、$f{甘草干姜汤} $m{2味} $u{甘草}$w{四两，炙}，$u{干姜}$w{二两，炮}</p>\n<p>\t$s{右㕮咀}，以水三升，煮取一升五合，去滓，分温再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":52,"yaoCount":2,"drinkNum":2,"yaoList":["甘草","干姜"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"四两","weight":400,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"二两","weight":200,"suffix":"","showName":"干姜","extraProcess":"切"}]}}', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '52、$f{甘草干姜汤} $m{2味} $u{甘草}$w{四两，炙}，$u{干姜}$w{二两，炮} $s{右㕮咀}，以水三升，煮取一升五合，去滓，分温再服。', '2024-09-17T00:59:55.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5EROqUgz1Lq', 1, '{"title":"射干麻黄汤","description":"<p>53、$f{射干麻黄汤} $m{9味} $u{射干}$w{十三枚。一法三两}，$u{麻黄}$w{四两}，$u{生姜}$w{四两}，$u{细辛}，$u{紫菀}，$u{款冬花}$w{各三两}，$u{五味子}$w{半升}，$u{大枣}$w{七枚}，$u{半夏}$w{大者，洗，八枚。一法半升}</p>\n<p>\t$s{右九味}，以水一斗二升，先煮麻黄两沸，去上沫，内诸药，煮取三升，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":53,"yaoCount":9,"drinkNum":3,"yaoList":["射干","麻黄","生姜","细辛","紫菀","款冬花","五味子","大枣","半夏"],"fangList":[],"fangYaoList":[{"yaoId":"PEcY2j6wjoH","amount":"13枚","weight":130,"suffix":"","showName":"射干","extraProcess":"切"},{"yaoId":"nxz0hvgpJJf","amount":"四两","weight":400,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"四两","weight":400,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"MCBshcFNHhk","amount":"三两","weight":300,"suffix":"","showName":"细辛","extraProcess":"切"},{"yaoId":"iNByjKej50u","amount":"三两","weight":300,"suffix":"","showName":"紫菀","extraProcess":"切"},{"yaoId":"CPNE5J4Tnwm","amount":"三两","weight":300,"suffix":"","showName":"款冬花","extraProcess":"切"},{"yaoId":"C74sm5pJRdN","amount":"半升","weight":500,"suffix":"","showName":"五味子","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"7枚","weight":70,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"8枚大者","weight":67,"suffix":"","showName":"半夏","extraProcess":"切"}]}}', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '2024-09-17T00:59:55.000Z', '53、$f{射干麻黄汤} $m{9味} $u{射干}$w{十三枚。一法三两}，$u{麻黄}$w{四两}，$u{生姜}$w{四两}，$u{细辛}，$u{紫菀}，$u{款冬花}$w{各三两}，$u{五味子}$w{半升}，$u{大枣}$w{七枚}，$u{半夏}$w{大者，洗，八枚。一法半升} $s{右九味}，以水一斗二升，先煮麻黄两沸，去上沫，内诸药，煮取三升，分温三服。', '2024-09-17T00:59:55.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8p674dVa017', 1, '{"title":"皂荚丸","description":"<p>54、$f{皂荚丸} $m{1味} $u{皂荚}$w{八两，刮去皮，用酥炙}</p>\n<p>\t$s{右一味}，末之，$u{蜜}丸梧子大。以$u{枣膏}和汤服三丸，日三、夜一服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":54,"yaoCount":3,"drinkNum":100,"yaoList":["皂荚","蜜","枣膏"],"fangList":[],"fangYaoList":[{"yaoId":"hmJnKWK15KJ","amount":"八两","weight":800,"suffix":"","showName":"皂荚","extraProcess":"切"}]}}', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '54、$f{皂荚丸} $m{1味} $u{皂荚}$w{八两，刮去皮，用酥炙} $s{右一味}，末之，$u{蜜}丸梧子大。以$u{枣膏}和汤服三丸，日三、夜一服。', '2024-09-17T00:59:56.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EqI2XolBi09', 1, '{"title":"厚朴麻黄汤","description":"<p>55、$f{厚朴麻黄汤} $m{9味} $u{厚朴}$w{五两}，$u{麻黄}$w{四两}，$u{石膏}$w{如鸡子大}，$u{杏仁}$w{半升}，$u{半夏}$w{半升}，$u{干姜}$w{二两}，$u{细辛}$w{二两}，$u{小麦}$w{一升}，$u{五味子}$w{半升}</p>\n<p>\t$s{右九味}，以水一斗二升，先煮小麦熟，去滓，内诸药，煮取三升。温服一升，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":55,"yaoCount":9,"drinkNum":3,"yaoList":["厚朴","麻黄","石膏","杏仁","半夏","干姜","细辛","小麦","五味子"],"fangList":[],"fangYaoList":[{"yaoId":"8714SID7nWu","amount":"五两","weight":500,"suffix":"","showName":"厚朴","extraProcess":"切"},{"yaoId":"nxz0hvgpJJf","amount":"四两","weight":400,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"S7mhkBtEhPL","amount":"如鸡子大","weight":750,"suffix":"","showName":"石膏","extraProcess":"切"},{"yaoId":"Hs7PKqMqKRj","amount":"半升约150枚","weight":1500,"suffix":"","showName":"杏仁","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"半升","weight":500,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"二两","weight":200,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"MCBshcFNHhk","amount":"二两","weight":200,"suffix":"","showName":"细辛","extraProcess":"切"},{"yaoId":"CdBvjhzVtG6","amount":"一升","weight":1000,"suffix":"","showName":"小麦","extraProcess":"切"},{"yaoId":"C74sm5pJRdN","amount":"半升","weight":500,"suffix":"","showName":"五味子","extraProcess":"切"}]}}', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '55、$f{厚朴麻黄汤} $m{9味} $u{厚朴}$w{五两}，$u{麻黄}$w{四两}，$u{石膏}$w{如鸡子大}，$u{杏仁}$w{半升}，$u{半夏}$w{半升}，$u{干姜}$w{二两}，$u{细辛}$w{二两}，$u{小麦}$w{一升}，$u{五味子}$w{半升} $s{右九味}，以水一斗二升，先煮小麦熟，去滓，内诸药，煮取三升。温服一升，日三服。', '2024-09-17T00:59:56.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aR5H5KW412u', 1, '{"title":"泽漆汤","description":"<p>56、$f{泽漆汤} $m{9味} $u{半夏}$w{半升}，$u{紫参}$w{五两。一作紫菀}，$u{泽漆}$w{三斤，以东流水五斗，煮取一斗五升}，$u{生姜}$w{五两}，$u{白前}$w{五两}，$u{甘草}，$u{黄芩}，$u{人参}，$u{桂枝}$w{各三两}</p>\n<p>\t$s{右九味}，㕮咀，内泽漆汁中，煮取五升。温服五合，至夜尽。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":56,"yaoCount":9,"drinkNum":10,"yaoList":["半夏","紫参","泽漆","生姜","白前","甘草","黄芩","人参","桂枝"],"fangList":[],"fangYaoList":[{"yaoId":"axI8tfBmKAx","amount":"半升","weight":500,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"ErucDpix02e","amount":"五两","weight":500,"suffix":"","showName":"紫参","extraProcess":"切"},{"yaoId":"Rw6Mqj3o4qB","amount":"三斤","weight":4800,"suffix":"","showName":"泽漆","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"五两","weight":500,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"LoZ0ORbfbD5","amount":"五两","weight":500,"suffix":"","showName":"白前","extraProcess":"切"},{"yaoId":null,"amount":"三两","weight":300,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"三两","weight":300,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"三两","weight":300,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"}]}}', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '56、$f{泽漆汤} $m{9味} $u{半夏}$w{半升}，$u{紫参}$w{五两。一作紫菀}，$u{泽漆}$w{三斤，以东流水五斗，煮取一斗五升}，$u{生姜}$w{五两}，$u{白前}$w{五两}，$u{甘草}，$u{黄芩}，$u{人参}，$u{桂枝}$w{各三两} $s{右九味}，㕮咀，内泽漆汁中，煮取五升。温服五合，至夜尽。', '2024-09-17T00:59:56.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KcWzqpnPYoV', 1, '{"title":"麦门冬汤","description":"<p>57、$f{麦门冬汤} $m{6味} $u{麦门冬}$w{七升}，$u{半夏}$w{一升}，$u{人参}$w{二两}，$u{甘草}$w{二两}，$u{粳米}$w{三合}，$u{大枣}$w{十二枚}</p>\n<p>\t$s{右六味}，以水一斗二升，煮取六升。温服一升，日三、夜一服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":57,"yaoCount":6,"drinkNum":6,"yaoList":["麦门冬","半夏","人参","甘草","粳米","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"DDXydmiFQLK","amount":"七升","weight":4200,"suffix":"","showName":"麦门冬","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"一升","weight":1000,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"二两","weight":200,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"2gRWUBY7CiY","amount":"三合","weight":300,"suffix":"","showName":"粳米","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '57、$f{麦门冬汤} $m{6味} $u{麦门冬}$w{七升}，$u{半夏}$w{一升}，$u{人参}$w{二两}，$u{甘草}$w{二两}，$u{粳米}$w{三合}，$u{大枣}$w{十二枚} $s{右六味}，以水一斗二升，煮取六升。温服一升，日三、夜一服。', '2024-09-17T00:59:56.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pcGDrymGyiU', 1, '{"title":"葶苈大枣泻肺汤","description":"<p>58、$f{葶苈大枣泻肺汤} $m{2味} $u{葶苈}$w{熬令黄色，捣丸如弹丸大}，$u{大枣}$w{十二枚}</p>\n<p>\t$s{右先以水三升}，煮枣取二升，去枣，内葶苈，煮取一升，顿服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":58,"yaoCount":2,"drinkNum":1,"yaoList":["葶苈","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"jD7lvOl6QAj","amount":"弹丸大","weight":170,"suffix":"","showName":"葶苈","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '58、$f{葶苈大枣泻肺汤} $m{2味} $u{葶苈}$w{熬令黄色，捣丸如弹丸大}，$u{大枣}$w{十二枚} $s{右先以水三升}，煮枣取二升，去枣，内葶苈，煮取一升，顿服。', '2024-09-17T00:59:56.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LB8NFi5xeYx', 1, '{"title":"桔梗汤","description":"<p>59、$f{桔梗汤} $m{2味} $a{亦治血痹。}</p>\n<p>\t$u{桔梗}$w{一两}，$u{甘草}$w{二两}</p>\n<p>\t$s{右二味}，以水三升，煮取一升。分温再服，则吐脓血也。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":59,"yaoCount":2,"drinkNum":2,"yaoList":["桔梗","甘草"],"fangList":[],"fangYaoList":[{"yaoId":"t7DkIvGNO8b","amount":"一两","weight":100,"suffix":"","showName":"桔梗","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"}]}}', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '59、$f{桔梗汤} $m{2味} $a{亦治血痹。} $u{桔梗}$w{一两}，$u{甘草}$w{二两} $s{右二味}，以水三升，煮取一升。分温再服，则吐脓血也。', '2024-09-17T00:59:56.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uHMhT0jxdDu', 1, '{"title":"越婢加半夏汤","description":"<p>60、$f{越婢加半夏汤} $m{6味} $u{麻黄}$w{六两}，$u{石膏}$w{半斤}，$u{生姜}$w{三两}，$u{大枣}$w{十五枚}，$u{甘草}$w{二两}，$u{半夏}$w{半升}</p>\n<p>\t$s{右六味}，以水六升，先煮麻黄，去上沫，内诸药，煮取三升，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":60,"yaoCount":6,"drinkNum":3,"yaoList":["麻黄","石膏","生姜","大枣","甘草","半夏"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"六两","weight":600,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"S7mhkBtEhPL","amount":"半斤","weight":800,"suffix":"","showName":"石膏","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"15枚","weight":150,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":0,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"半升","weight":500,"suffix":"","showName":"半夏","extraProcess":"切"}]}}', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '60、$f{越婢加半夏汤} $m{6味} $u{麻黄}$w{六两}，$u{石膏}$w{半斤}，$u{生姜}$w{三两}，$u{大枣}$w{十五枚}，$u{甘草}$w{二两}，$u{半夏}$w{半升} $s{右六味}，以水六升，先煮麻黄，去上沫，内诸药，煮取三升，分温三服。', '2024-09-17T00:59:56.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('x6ay5b3abXl', 1, '{"title":"小青龙加石膏汤","description":"<p>61、$f{小青龙加石膏汤} $m{9味} $q{《千金》}$a{证治同，外更加胁下痛引缺盆。}</p>\n<p>\t$u{麻黄}，$u{芍药}，$u{桂枝}，$u{细辛}，$u{甘草}，$u{干姜}$w{各三两}，$u{五味子}，$u{半夏}$w{各半升}，$u{石膏}$w{二两}</p>\n<p>\t$s{右九味}，以水一斗，先煮麻黄，去上沫，内诸药，煮取三升。强人服一升，羸者减之，日三服，小儿服四合。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":61,"yaoCount":9,"drinkNum":3,"yaoList":["麻黄","芍药","桂枝","细辛","甘草","干姜","五味子","半夏","石膏"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"三两","weight":300,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":300,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"MCBshcFNHhk","amount":"三两","weight":300,"suffix":"","showName":"细辛","extraProcess":"切"},{"yaoId":null,"amount":"三两","weight":300,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"三两","weight":300,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"C74sm5pJRdN","amount":"半升","weight":500,"suffix":"","showName":"五味子","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"半升","weight":500,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"S7mhkBtEhPL","amount":"二两","weight":200,"suffix":"","showName":"石膏","extraProcess":"切"}]}}', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '61、$f{小青龙加石膏汤} $m{9味} $q{《千金》}$a{证治同，外更加胁下痛引缺盆。} $u{麻黄}，$u{芍药}，$u{桂枝}，$u{细辛}，$u{甘草}，$u{干姜}$w{各三两}，$u{五味子}，$u{半夏}$w{各半升}，$u{石膏}$w{二两} $s{右九味}，以水一斗，先煮麻黄，去上沫，内诸药，煮取三升。强人服一升，羸者减之，日三服，小儿服四合。', '2024-09-17T00:59:56.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wlv1KB9nVpm', 1, '{"title":"甘草汤","description":"<p>62、$q{《千金》}$f{甘草汤} $m{1味} $a{此方本出于$q{《肘后》}而$q{《千金》}主疗，与$q{《外台》}炙甘草汤同，但唾多下，有出血二字。}</p>\n<p>\t$u{甘草}$w{诸本缺铢两，$q{《肘后》}，$q{《千金》}用$w{二两}。}</p>\n<p>\t$s{右一味}，以水三升，煮减半，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":62,"yaoCount":1,"drinkNum":3,"yaoList":["甘草"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"}]}}', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '62、$q{《千金》}$f{甘草汤} $m{1味} $a{此方本出于$q{《肘后》}而$q{《千金》}主疗，与$q{《外台》}炙甘草汤同，但唾多下，有出血二字。} $u{甘草}$w{诸本缺铢两，$q{《肘后》}，$q{《千金》}用$w{二两}。} $s{右一味}，以水三升，煮减半，分温三服。', '2024-09-17T00:59:56.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('E1Gcqauhec6', 1, '{"title":"生姜甘草汤","description":"<p>63、$q{《千金》}$f{生姜甘草汤} $m{4味} 治肺痿咳唾涎沫不止，咽燥而渴。</p>\n<p>\t$u{生姜}$w{五两}，$u{人参}$w{二两}，$u{甘草}$w{四两}，$u{大枣}$w{十五枚}</p>\n<p>\t$s{右四味}，以水七升，煮取三升，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":63,"yaoCount":4,"drinkNum":3,"yaoList":["生姜","人参","甘草","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"VcvhqvKkSct","amount":"五两","weight":500,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"二两","weight":200,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":null,"amount":"四两","weight":400,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"15枚","weight":150,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '63、$q{《千金》}$f{生姜甘草汤} $m{4味} 治肺痿咳唾涎沫不止，咽燥而渴。 $u{生姜}$w{五两}，$u{人参}$w{二两}，$u{甘草}$w{四两}，$u{大枣}$w{十五枚} $s{右四味}，以水七升，煮取三升，分温三服。', '2024-09-17T00:59:56.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tYOguV05zQa', 1, '{"title":"桂枝去芍药加皂荚汤","description":"<p>64、$q{《千金》}$f{桂枝去芍药加皂荚汤} $m{5味} 治肺痿吐涎沫。</p>\n<p>\t$u{桂枝}，$u{生姜}$w{各三两}，$u{甘草}$w{二两}，$u{大枣}$w{十枚}，$u{皂荚}$w{一枚，去皮子，炙焦}</p>\n<p>\t$s{右五味}，以水七升，微微火煮取三升，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":64,"yaoCount":5,"drinkNum":3,"yaoList":["桂枝","生姜","甘草","大枣","皂荚"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"10枚","weight":100,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"hmJnKWK15KJ","amount":"1枚","weight":20,"suffix":"","showName":"皂荚","extraProcess":"切"}]}}', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '64、$q{《千金》}$f{桂枝去芍药加皂荚汤} $m{5味} 治肺痿吐涎沫。 $u{桂枝}，$u{生姜}$w{各三两}，$u{甘草}$w{二两}，$u{大枣}$w{十枚}，$u{皂荚}$w{一枚，去皮子，炙焦} $s{右五味}，以水七升，微微火煮取三升，分温三服。', '2024-09-17T00:59:56.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('D1iz4HrG2G2', 1, '{"title":"桔梗白散","description":"<p>65、$q{《外台》}$f{桔梗白散} $m{3味} 治咳而胸满，振寒，脉数，咽干不渴，时出浊唾腥臭，久久吐脓如米粥者，为肺痈。</p>\n<p>\t$u{桔梗}，$u{贝母}$w{各三分}，$u{巴豆}$w{一分，去皮，熬，研如脂}</p>\n<p>\t$s{右三味}，为散，强人饮服半钱匕，羸者减之。病在膈上者吐脓血，膈下者泻出。若下多不止，饮冷水一杯则定。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":65,"yaoCount":3,"drinkNum":10,"yaoList":["桔梗","贝母","巴豆"],"fangList":[],"fangYaoList":[{"yaoId":"t7DkIvGNO8b","amount":"三分","weight":75,"suffix":"","showName":"桔梗","extraProcess":"切"},{"yaoId":"lzOM54GtZJW","amount":"三分","weight":75,"suffix":"","showName":"贝母","extraProcess":"切"},{"yaoId":"1n7R7kiLFv1","amount":"一分","weight":25,"suffix":"","showName":"巴豆","extraProcess":"切"}]}}', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '65、$q{《外台》}$f{桔梗白散} $m{3味} 治咳而胸满，振寒，脉数，咽干不渴，时出浊唾腥臭，久久吐脓如米粥者，为肺痈。 $u{桔梗}，$u{贝母}$w{各三分}，$u{巴豆}$w{一分，去皮，熬，研如脂} $s{右三味}，为散，强人饮服半钱匕，羸者减之。病在膈上者吐脓血，膈下者泻出。若下多不止，饮冷水一杯则定。', '2024-09-17T00:59:56.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KR9v1X3qePI', 1, '{"title":"苇茎汤","description":"<p>66、$q{《千金》}$f{苇茎汤} $m{4味} 治咳有微热烦满，胸中甲错，是为肺痈。</p>\n<p>\t$u{苇茎}$w{二升}，$u{薏苡仁}$w{半升}，$u{桃仁}$w{五十枚}，$u{瓜瓣}$w{半升}</p>\n<p>\t$s{右四味}，以水一斗，先煮苇茎得五升，去滓，内诸药，煮取二升。服一升，再服，当吐如脓。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":66,"yaoCount":4,"drinkNum":2,"yaoList":["苇茎","薏苡仁","桃仁","瓜瓣"],"fangList":[],"fangYaoList":[{"yaoId":"n6qtCRViVs3","amount":"二升","weight":320,"suffix":"","showName":"苇茎","extraProcess":"切"},{"yaoId":"rOi0RaqbWeB","amount":"半升","weight":500,"suffix":"","showName":"薏苡仁","extraProcess":"切"},{"yaoId":"k2cI79Wat6h","amount":"50枚","weight":500,"suffix":"","showName":"桃仁","extraProcess":"切"},{"yaoId":"hIgLFvn83se","amount":"半升","weight":500,"suffix":"","showName":"瓜瓣","extraProcess":"切"}]}}', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '66、$q{《千金》}$f{苇茎汤} $m{4味} 治咳有微热烦满，胸中甲错，是为肺痈。 $u{苇茎}$w{二升}，$u{薏苡仁}$w{半升}，$u{桃仁}$w{五十枚}，$u{瓜瓣}$w{半升} $s{右四味}，以水一斗，先煮苇茎得五升，去滓，内诸药，煮取二升。服一升，再服，当吐如脓。', '2024-09-17T00:59:56.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('m2wHY568YZB', 1, '{"title":"奔豚汤","description":"<p>67、$f{奔豚汤} $m{9味} $u{甘草}，$u{芎䓖}，$u{当归}$w{各二两}，$u{半夏}$w{四两}，$u{黄芩}$w{二两}，$u{生葛}$w{五两}，$u{芍药}$w{二两}，$u{生姜}$w{四两}，$u{甘李根白皮}$w{一升}</p>\n<p>\t$s{右九味}，以水二斗，煮取五升。温服一升，日三、夜一服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":67,"yaoCount":9,"drinkNum":5,"yaoList":["甘草","芎䓖","当归","半夏","黄芩","生葛","芍药","生姜","甘李根白皮"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"Sfmcy2PNzjm","amount":"二两","weight":200,"suffix":"","showName":"芎䓖","extraProcess":"切"},{"yaoId":"JFnirDnffR9","amount":"二两","weight":200,"suffix":"","showName":"当归","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"四两","weight":400,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"二两","weight":200,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"MzvPguhXJ5G","amount":"五两","weight":500,"suffix":"","showName":"生葛","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"二两","weight":200,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"四两","weight":400,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"HzvDkKxaeBg","amount":"一升","weight":1000,"suffix":"","showName":"甘李根白皮","extraProcess":"切"}]}}', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '2024-09-17T00:59:56.000Z', '67、$f{奔豚汤} $m{9味} $u{甘草}，$u{芎䓖}，$u{当归}$w{各二两}，$u{半夏}$w{四两}，$u{黄芩}$w{二两}，$u{生葛}$w{五两}，$u{芍药}$w{二两}，$u{生姜}$w{四两}，$u{甘李根白皮}$w{一升} $s{右九味}，以水二斗，煮取五升。温服一升，日三、夜一服。', '2024-09-17T00:59:56.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qz0UyTSEMHd', 1, '{"title":"桂枝加桂汤","description":"<p>68、$f{桂枝加桂汤} $m{5味} $u{桂枝}$w{五两}，$u{芍药}$w{三两}，$u{甘草}$w{二两，炙}，$u{生姜}$w{三两}，$u{大枣}$w{十二枚}</p>\n<p>\t$s{右五味}，以水七升，微火煮取三升，去滓，温服一升。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":68,"yaoCount":5,"drinkNum":3,"yaoList":["桂枝","芍药","甘草","生姜","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"五两","weight":500,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":300,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '68、$f{桂枝加桂汤} $m{5味} $u{桂枝}$w{五两}，$u{芍药}$w{三两}，$u{甘草}$w{二两，炙}，$u{生姜}$w{三两}，$u{大枣}$w{十二枚} $s{右五味}，以水七升，微火煮取三升，去滓，温服一升。', '2024-09-17T00:59:57.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gMZ8ol7fMk4', 1, '{"title":"茯苓桂枝甘草大枣汤","description":"<p>69、$f{茯苓桂枝甘草大枣汤} $m{4味} $u{茯苓}$w{半斤}，$u{甘草}$w{二两，炙}，$u{大枣}$w{十五枚}，$u{桂枝}$w{四两}</p>\n<p>\t$s{右四味}，以$u{甘澜水}$w{一斗}，先煮茯苓，减二升，内诸药，煮取三升，去滓。温服一升，日三服。$a{甘澜水法：取水二斗，置大盆内，以杓扬之，水上有珠子五六千颗相逐，取用之。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":69,"yaoCount":5,"drinkNum":3,"yaoList":["茯苓","甘草","大枣","桂枝","甘澜水"],"fangList":[],"fangYaoList":[{"yaoId":"VHE7Y68l232","amount":"半斤","weight":800,"suffix":"","showName":"茯苓","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"15枚","weight":150,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"四两","weight":400,"suffix":"","showName":"桂枝","extraProcess":"切"}]}}', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '69、$f{茯苓桂枝甘草大枣汤} $m{4味} $u{茯苓}$w{半斤}，$u{甘草}$w{二两，炙}，$u{大枣}$w{十五枚}，$u{桂枝}$w{四两} $s{右四味}，以$u{甘澜水}$w{一斗}，先煮茯苓，减二升，内诸药，煮取三升，去滓。温服一升，日三服。$a{甘澜水法：取水二斗，置大盆内，以杓扬之，水上有珠子五六千颗相逐，取用之。}', '2024-09-17T00:59:57.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wL9TUgp4pIa', 1, '{"title":"栝楼薤白白酒汤","description":"<p>70、$f{栝楼薤白白酒汤} $m{3味} $u{栝楼实}$w{一枚，捣}，$u{薤白}$w{半升}，$u{白酒}$w{七升}</p>\n<p>\t$s{右三味}，同煮，取二升，分温再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":70,"yaoCount":3,"drinkNum":2,"yaoList":["栝楼实","薤白","白酒"],"fangList":[],"fangYaoList":[{"yaoId":"9BxIgk2gITY","amount":"1枚","weight":100,"suffix":"","showName":"栝楼实","extraProcess":"切"},{"yaoId":"PLFElISYWYO","amount":"半升","weight":350,"suffix":"","showName":"薤白","extraProcess":"切"},{"yaoId":"JMpy06saY9b","amount":"七升","weight":7000,"suffix":"","showName":"白酒","extraProcess":"切"}]}}', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '70、$f{栝楼薤白白酒汤} $m{3味} $u{栝楼实}$w{一枚，捣}，$u{薤白}$w{半升}，$u{白酒}$w{七升} $s{右三味}，同煮，取二升，分温再服。', '2024-09-17T00:59:57.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
