INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8XCr9oO5mby', 1, '{"title":"枳实薤白桂枝汤","description":"<p>72、$f{枳实薤白桂枝汤} $m{5味} $u{枳实}$w{四枚}，$u{厚朴}$w{四两}，$u{薤白}$w{半斤}，$u{桂枝}$w{一两}，$u{栝楼}$w{一枚，捣}</p>\n<p>\t$s{右五味}，以水五升，先煮枳实、厚朴，取二升，去滓，内诸药，煮数沸，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":72,"yaoCount":5,"drinkNum":3,"yaoList":["枳实","厚朴","薤白","桂枝","栝楼"],"fangList":[],"fangYaoList":[{"yaoId":"FRaBwjHoVui","amount":"4枚","weight":40,"suffix":"","showName":"枳实","extraProcess":"切"},{"yaoId":"8714SID7nWu","amount":"四两","weight":400,"suffix":"","showName":"厚朴","extraProcess":"切"},{"yaoId":"PLFElISYWYO","amount":"半斤","weight":800,"suffix":"","showName":"薤白","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"一两","weight":100,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"9BxIgk2gITY","amount":"1枚","weight":100,"suffix":"","showName":"栝楼","extraProcess":"切"}]}}', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '72、$f{枳实薤白桂枝汤} $m{5味} $u{枳实}$w{四枚}，$u{厚朴}$w{四两}，$u{薤白}$w{半斤}，$u{桂枝}$w{一两}，$u{栝楼}$w{一枚，捣} $s{右五味}，以水五升，先煮枳实、厚朴，取二升，去滓，内诸药，煮数沸，分温三服。', '2024-09-17T00:59:57.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('afd0J41ar9L', 1, '{"title":"人参汤","description":"<p>73、$f{人参汤} $m{4味} $u{人参}，$u{甘草}，$u{干姜}，$u{白术}$w{各三两}</p>\n<p>\t$s{右四味}，以水八升，煮取三升。温服一升，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":73,"yaoCount":4,"drinkNum":3,"yaoList":["人参","甘草","干姜","白术"],"fangList":[],"fangYaoList":[{"yaoId":"GIXSHBaFv0L","amount":"三两","weight":300,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":null,"amount":"三两","weight":300,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"三两","weight":300,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"UIYZOmiE2xW","amount":"三两","weight":300,"suffix":"","showName":"白术","extraProcess":"切"}]}}', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '73、$f{人参汤} $m{4味} $u{人参}，$u{甘草}，$u{干姜}，$u{白术}$w{各三两} $s{右四味}，以水八升，煮取三升。温服一升，日三服。', '2024-09-17T00:59:57.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RX7F2Hhemd7', 1, '{"title":"茯苓杏仁甘草汤","description":"<p>74、$f{茯苓杏仁甘草汤} $m{3味} $u{茯苓}$w{三两}，$u{杏仁}$w{五十个}，$u{甘草}$w{一两}</p>\n<p>\t$s{右三味}，以水一斗，煮取五升。温服一升，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":74,"yaoCount":3,"drinkNum":5,"yaoList":["茯苓","杏仁","甘草"],"fangList":[],"fangYaoList":[{"yaoId":"VHE7Y68l232","amount":"三两","weight":300,"suffix":"","showName":"茯苓","extraProcess":"切"},{"yaoId":"Hs7PKqMqKRj","amount":"50个","weight":500,"suffix":"","showName":"杏仁","extraProcess":"切"},{"yaoId":null,"amount":"一两","weight":100,"suffix":"","showName":"甘草","extraProcess":"切"}]}}', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '74、$f{茯苓杏仁甘草汤} $m{3味} $u{茯苓}$w{三两}，$u{杏仁}$w{五十个}，$u{甘草}$w{一两} $s{右三味}，以水一斗，煮取五升。温服一升，日三服。', '2024-09-17T00:59:57.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6pTk0kMBKLI', 1, '{"title":"橘枳姜汤","description":"<p>75、$f{橘枳姜汤} $m{3味} $u{橘皮}$w{一斤}，$u{枳实}$w{三两}，$u{生姜}$w{半斤}</p>\n<p>\t$s{右三味}，以水五升，煮取二升，分温再服。$a{$q{《肘后》}、$q{《千金》}云：治胸痹，胸中愊愊如满，噎塞习习如痒，喉中涩燥，唾沫}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":75,"yaoCount":3,"drinkNum":2,"yaoList":["橘皮","枳实","生姜"],"fangList":[],"fangYaoList":[{"yaoId":"216GW1qIoXb","amount":"一斤","weight":1600,"suffix":"","showName":"橘皮","extraProcess":"切"},{"yaoId":"FRaBwjHoVui","amount":"三两","weight":25,"suffix":"","showName":"枳实","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"半斤","weight":800,"suffix":"","showName":"生姜","extraProcess":"切"}]}}', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '75、$f{橘枳姜汤} $m{3味} $u{橘皮}$w{一斤}，$u{枳实}$w{三两}，$u{生姜}$w{半斤} $s{右三味}，以水五升，煮取二升，分温再服。$a{$q{《肘后》}、$q{《千金》}云：治胸痹，胸中愊愊如满，噎塞习习如痒，喉中涩燥，唾沫}', '2024-09-17T00:59:57.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BLXm4VjDGG0', 1, '{"title":"薏苡附子散","description":"<p>76、$f{薏苡附子散} $m{2味} $u{薏苡仁}$w{十五两}，$u{大附子}$w{十枚，炮}</p>\n<p>\t$s{右二味}，杵为散，服方寸匕，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":76,"yaoCount":2,"drinkNum":100,"yaoList":["薏苡仁","大附子"],"fangList":[],"fangYaoList":[{"yaoId":"rOi0RaqbWeB","amount":"十五两","weight":1500,"suffix":"","showName":"薏苡仁","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"10枚大者炮","weight":1000,"suffix":"","showName":"大附子","extraProcess":"切"}]}}', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '76、$f{薏苡附子散} $m{2味} $u{薏苡仁}$w{十五两}，$u{大附子}$w{十枚，炮} $s{右二味}，杵为散，服方寸匕，日三服。', '2024-09-17T00:59:57.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
