INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xBtWcGFCpwj', 1, '{"title":"乌头赤石脂丸","description":"<p>78、$f{乌头赤石脂丸} $m{5味} $u{蜀椒}$w{一两。一法二分}，$u{乌头}$w{一分，炮}，$u{附子}$w{半两，炮。一法一分}，$u{干姜}$w{一两。一法一分}，$u{赤石脂}$w{一两。一法二分}</p>\n<p>\t$s{右五味}，末之，$u{蜜}丸如梧子大。先食服一丸，日三服。不知，稍加服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":78,"yaoCount":6,"drinkNum":100,"yaoList":["蜀椒","乌头","附子","干姜","赤石脂","蜜"],"fangList":[],"fangYaoList":[{"yaoId":"03dIYYkyQRn","amount":"一两","weight":100,"suffix":"","showName":"蜀椒","extraProcess":"切"},{"yaoId":"dFbCWGnQmeQ","amount":"一分炮","weight":25,"suffix":"","showName":"乌头","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"半两炮","weight":50,"suffix":"","showName":"附子","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"一两","weight":100,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"1rOkrjGOCab","amount":"一两","weight":100,"suffix":"","showName":"赤石脂","extraProcess":"切"}]}}', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '78、$f{乌头赤石脂丸} $m{5味} $u{蜀椒}$w{一两。一法二分}，$u{乌头}$w{一分，炮}，$u{附子}$w{半两，炮。一法一分}，$u{干姜}$w{一两。一法一分}，$u{赤石脂}$w{一两。一法二分} $s{右五味}，末之，$u{蜜}丸如梧子大。先食服一丸，日三服。不知，稍加服。', '2024-09-17T00:59:57.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0Cx15nvXxBV', 1, '{"title":"九痛丸","description":"<p>79、$f{九痛丸} $m{6味} 治九种心痛。</p>\n<p>\t$u{附子}$w{三两，炮}，$u{生狼牙}$w{一两，炙香}，$u{巴豆}$w{一两，去皮心，熬，研如脂}，$u{人参}，$u{干姜}，$u{吴茱萸}$w{各一两}。</p>\n<p>\t$s{上六味}，末之，炼$u{蜜}丸如梧子大，$u{酒}下。强人初服三丸，日三服；弱者，二丸。兼治卒中恶，腹胀痛，口不能言。又治连年积冷，流注，心胸痛并冷冲上气，落马、坠车、血疾等皆主之。忌口如常法。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":79,"yaoCount":8,"drinkNum":50,"yaoList":["附子","生狼牙","巴豆","人参","干姜","吴茱萸","蜜","酒"],"fangList":[],"fangYaoList":[{"yaoId":"jT011T7yIVO","amount":"三两炮","weight":300,"suffix":"","showName":"附子","extraProcess":"切"},{"yaoId":"SsbIoYn21JT","amount":"一两","weight":100,"suffix":"","showName":"生狼牙","extraProcess":"切"},{"yaoId":"1n7R7kiLFv1","amount":"一两","weight":100,"suffix":"","showName":"巴豆","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"一两","weight":100,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"一两","weight":100,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"ZJN7O318dPD","amount":"一两","weight":100,"suffix":"","showName":"吴茱萸","extraProcess":"切"}]}}', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '79、$f{九痛丸} $m{6味} 治九种心痛。 $u{附子}$w{三两，炮}，$u{生狼牙}$w{一两，炙香}，$u{巴豆}$w{一两，去皮心，熬，研如脂}，$u{人参}，$u{干姜}，$u{吴茱萸}$w{各一两}。 $s{上六味}，末之，炼$u{蜜}丸如梧子大，$u{酒}下。强人初服三丸，日三服；弱者，二丸。兼治卒中恶，腹胀痛，口不能言。又治连年积冷，流注，心胸痛并冷冲上气，落马、坠车、血疾等皆主之。忌口如常法。', '2024-09-17T00:59:57.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GGGrZxqoGov', 1, '{"title":"厚朴七物汤","description":"<p>80、$f{厚朴七物汤} $m{7味} $u{厚朴}$w{半斤}，$u{甘草}，$u{大黄}$w{各三两}，$u{大枣}$w{十枚}，$u{枳实}$w{五枚}，$u{桂枝}$w{二两}，$u{生姜}$w{五两}</p>\n<p>\t$s{右七味}，以水一斗，煮取四升，温服八合，日三服。呕者，加$u{半夏}$w{五合}，下利去$u{大黄}；寒多者，加$u{生姜}$w{至半斤}。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":80,"yaoCount":7,"drinkNum":5,"yaoList":["厚朴","甘草","大黄","大枣","枳实","桂枝","生姜","半夏"],"fangList":[],"fangYaoList":[{"yaoId":"8714SID7nWu","amount":"半斤","weight":800,"suffix":"","showName":"厚朴","extraProcess":"切"},{"yaoId":null,"amount":"三两","weight":300,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"To31b37bc6Z","amount":"$x{下利去大黄}三两","weight":300,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"10枚","weight":100,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"FRaBwjHoVui","amount":"5枚","weight":50,"suffix":"","showName":"枳实","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"二两","weight":200,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"五两($x{寒多加}至半斤)","weight":500,"suffix":"","showName":"生姜","extraProcess":"切"}]}}', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '80、$f{厚朴七物汤} $m{7味} $u{厚朴}$w{半斤}，$u{甘草}，$u{大黄}$w{各三两}，$u{大枣}$w{十枚}，$u{枳实}$w{五枚}，$u{桂枝}$w{二两}，$u{生姜}$w{五两} $s{右七味}，以水一斗，煮取四升，温服八合，日三服。呕者，加$u{半夏}$w{五合}，下利去$u{大黄}；寒多者，加$u{生姜}$w{至半斤}。', '2024-09-17T00:59:57.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qF3jILMLtI1', 1, '{"title":"附子粳米汤","description":"<p>81、$f{附子粳米汤} $m{5味} $u{附子}$w{一枚，炮}，$u{半夏}$w{半升}，$u{甘草}$w{一两}，$u{大枣}$w{十枚}，$u{粳米}$w{半升}</p>\n<p>\t$s{右五味}，以水八升，煮米熟汤成，去滓。温服一升，三日服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":81,"yaoCount":5,"drinkNum":3,"yaoList":["附子","半夏","甘草","大枣","粳米"],"fangList":[],"fangYaoList":[{"yaoId":"jT011T7yIVO","amount":"1枚炮","weight":100,"suffix":"","showName":"附子","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"半升","weight":500,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":null,"amount":"一两","weight":100,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"10枚","weight":100,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"2gRWUBY7CiY","amount":"半升","weight":500,"suffix":"","showName":"粳米","extraProcess":"切"}]}}', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '2024-09-17T00:59:57.000Z', '81、$f{附子粳米汤} $m{5味} $u{附子}$w{一枚，炮}，$u{半夏}$w{半升}，$u{甘草}$w{一两}，$u{大枣}$w{十枚}，$u{粳米}$w{半升} $s{右五味}，以水八升，煮米熟汤成，去滓。温服一升，三日服。', '2024-09-17T00:59:57.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('32OJVcwc47K', 1, '{"title":"厚朴三物汤","description":"<p>82、$f{厚朴三物汤} $m{3味} $u{厚朴}$w{八两}，$u{大黄}$w{四两}，$u{枳实}$w{五枚}</p>\n<p>\t$s{右三味}，以水一斗二升，先煮二味，取五升，内大黄，煮取三升。温服一升，以利为度。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":82,"yaoCount":3,"drinkNum":3,"yaoList":["厚朴","大黄","枳实"],"fangList":[],"fangYaoList":[{"yaoId":"8714SID7nWu","amount":"八两","weight":800,"suffix":"","showName":"厚朴","extraProcess":"切"},{"yaoId":"To31b37bc6Z","amount":"四两","weight":400,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":"FRaBwjHoVui","amount":"5枚","weight":50,"suffix":"","showName":"枳实","extraProcess":"切"}]}}', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '82、$f{厚朴三物汤} $m{3味} $u{厚朴}$w{八两}，$u{大黄}$w{四两}，$u{枳实}$w{五枚} $s{右三味}，以水一斗二升，先煮二味，取五升，内大黄，煮取三升。温服一升，以利为度。', '2024-09-17T00:59:58.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vd0smgfgYX8', 1, '{"title":"大柴胡汤","description":"<p>83、$f{大柴胡汤} $m{8味} $u{柴胡}$w{半斤}，$u{黄芩}$w{三两}，$u{芍药}$w{三两}，$u{半夏}$w{半升，洗}，$u{枳实}$w{四枚，炙}，$u{大黄}$w{二两}，$u{大枣}$w{十二枚}，$u{生姜}$w{五两}</p>\n<p>\t$s{右八味}，以水一斗二升，煮取六升，去滓，再煎。温服一升，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":83,"yaoCount":8,"drinkNum":3,"yaoList":["柴胡","黄芩","芍药","半夏","枳实","大黄","大枣","生姜"],"fangList":[],"fangYaoList":[{"yaoId":"JMfcgoRTH0J","amount":"半斤","weight":800,"suffix":"","showName":"柴胡","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"三两","weight":300,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":300,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"半升","weight":500,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"FRaBwjHoVui","amount":"4枚","weight":40,"suffix":"","showName":"枳实","extraProcess":"切"},{"yaoId":"To31b37bc6Z","amount":"二两","weight":200,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"五两","weight":500,"suffix":"","showName":"生姜","extraProcess":"切"}]}}', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '83、$f{大柴胡汤} $m{8味} $u{柴胡}$w{半斤}，$u{黄芩}$w{三两}，$u{芍药}$w{三两}，$u{半夏}$w{半升，洗}，$u{枳实}$w{四枚，炙}，$u{大黄}$w{二两}，$u{大枣}$w{十二枚}，$u{生姜}$w{五两} $s{右八味}，以水一斗二升，煮取六升，去滓，再煎。温服一升，日三服。', '2024-09-17T00:59:58.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('03db4jD2eq5', 1, '{"title":"大建中汤","description":"<p>84、$f{大建中汤} $m{4味} $u{蜀椒}$w{二合，去汗}，$u{干姜}$w{四两}，$u{人参}$w{二两}，$u{胶饴}$w{一升}</p>\n<p>\t$s{右三味}，以水四升，煮取二升，去滓，内胶饴一升，微火煎取一升半。分温再服，如一炊顷，可饮粥二升，后更服，当一日食糜，温覆之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":84,"yaoCount":4,"drinkNum":2,"yaoList":["蜀椒","干姜","人参","胶饴"],"fangList":[],"fangYaoList":[{"yaoId":"03dIYYkyQRn","amount":"二合","weight":80,"suffix":"","showName":"蜀椒","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"四两","weight":400,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"二两","weight":200,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"q7UHJJ3ORHQ","amount":"一升","weight":1000,"suffix":"","showName":"胶饴","extraProcess":"切"}]}}', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '84、$f{大建中汤} $m{4味} $u{蜀椒}$w{二合，去汗}，$u{干姜}$w{四两}，$u{人参}$w{二两}，$u{胶饴}$w{一升} $s{右三味}，以水四升，煮取二升，去滓，内胶饴一升，微火煎取一升半。分温再服，如一炊顷，可饮粥二升，后更服，当一日食糜，温覆之。', '2024-09-17T00:59:58.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('o6A35izINbR', 1, '{"title":"大黄附子汤","description":"<p>85、$f{大黄附子汤} $m{3味} $u{大黄}$w{三两}，$u{附子}$w{三枚，炮}，$u{细辛}$w{二两}</p>\n<p>\t$s{右三味}，以水五升，煮取二升，分温三服。若强人煮二升半，分温三服。服后如人行四五里，进一服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":85,"yaoCount":3,"drinkNum":3,"yaoList":["大黄","附子","细辛"],"fangList":[],"fangYaoList":[{"yaoId":"To31b37bc6Z","amount":"三两","weight":300,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"3枚炮","weight":300,"suffix":"","showName":"附子","extraProcess":"切"},{"yaoId":"MCBshcFNHhk","amount":"二两","weight":200,"suffix":"","showName":"细辛","extraProcess":"切"}]}}', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '85、$f{大黄附子汤} $m{3味} $u{大黄}$w{三两}，$u{附子}$w{三枚，炮}，$u{细辛}$w{二两} $s{右三味}，以水五升，煮取二升，分温三服。若强人煮二升半，分温三服。服后如人行四五里，进一服。', '2024-09-17T00:59:58.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nA7Sn6uD87q', 1, '{"title":"赤丸","description":"<p>86、$f{赤丸} $m{4味} $u{茯苓}$w{四两}，$u{乌头}$w{二两，炮}，$u{半夏}$w{四两，洗。一方用$u{桂枝}}，$u{细辛}$w{一两}。$a{$q{《千金》}作$u{人参}}</p>\n<p>\t$s{右四味}，末之，内$u{真朱}为色，炼$u{蜜}丸如麻子大。先食$u{酒}饮下三丸，日再、夜一服；不知，稍增之，以知为度。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":86,"yaoCount":9,"drinkNum":100,"yaoList":["茯苓","乌头","半夏","桂枝","细辛","人参","真朱","蜜","酒"],"fangList":[],"fangYaoList":[{"yaoId":"VHE7Y68l232","amount":"四两","weight":400,"suffix":"","showName":"茯苓","extraProcess":"切"},{"yaoId":"dFbCWGnQmeQ","amount":"二两炮","weight":200,"suffix":"","showName":"乌头","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"四两","weight":400,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"MCBshcFNHhk","amount":"一两","weight":100,"suffix":"","showName":"细辛","extraProcess":"切"}]}}', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '86、$f{赤丸} $m{4味} $u{茯苓}$w{四两}，$u{乌头}$w{二两，炮}，$u{半夏}$w{四两，洗。一方用$u{桂枝}}，$u{细辛}$w{一两}。$a{$q{《千金》}作$u{人参}} $s{右四味}，末之，内$u{真朱}为色，炼$u{蜜}丸如麻子大。先食$u{酒}饮下三丸，日再、夜一服；不知，稍增之，以知为度。', '2024-09-17T00:59:58.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UQKTyXGWIu5', 1, '{"title":"大乌头煎","description":"<p>87、$f{大乌头煎} $m{1味} $u{乌头}$w{大者五枚，熬，去皮，不㕮咀}</p>\n<p>\t$s{右以水三升}，煮取一升，去滓，内$u{蜜}二升，煎令水气尽，取二升。强人服七合，弱人服五合。不差，明日更服，不可一日再服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":87,"yaoCount":1,"drinkNum":3,"yaoList":["乌头","蜜"],"fangList":[],"fangYaoList":[{"yaoId":"dFbCWGnQmeQ","amount":"5枚大者熬","weight":750,"suffix":"","showName":"乌头","extraProcess":"切"}]}}', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '87、$f{大乌头煎} $m{1味} $u{乌头}$w{大者五枚，熬，去皮，不㕮咀} $s{右以水三升}，煮取一升，去滓，内$u{蜜}二升，煎令水气尽，取二升。强人服七合，弱人服五合。不差，明日更服，不可一日再服。', '2024-09-17T00:59:58.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3KqrPhKmWnR', 1, '{"title":"当归生姜羊肉汤","description":"<p>88、$f{当归生姜羊肉汤} $m{3味} $u{当归}$w{三两}，$u{生姜}$w{五两}，$u{羊肉}$w{一斤}</p>\n<p>\t$s{右三味}，以水八升，煮取三升，温服七合，日三服。若寒多者，加$u{生姜}$w{成一斤}；痛多而呕者，加$u{橘皮}$w{二两}、$u{白术}$w{一两}。加生姜者，亦加水五升，煮取三升二合，服之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":88,"yaoCount":5,"drinkNum":4,"yaoList":["当归","生姜","羊肉","橘皮","白术"],"fangList":[],"fangYaoList":[{"yaoId":"JFnirDnffR9","amount":"三两","weight":300,"suffix":"","showName":"当归","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"五两($x{寒多加}至一斤)","weight":500,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"FwMZI5JA24k","amount":"一斤","weight":1600,"suffix":"","showName":"羊肉","extraProcess":"切"}]}}', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '88、$f{当归生姜羊肉汤} $m{3味} $u{当归}$w{三两}，$u{生姜}$w{五两}，$u{羊肉}$w{一斤} $s{右三味}，以水八升，煮取三升，温服七合，日三服。若寒多者，加$u{生姜}$w{成一斤}；痛多而呕者，加$u{橘皮}$w{二两}、$u{白术}$w{一两}。加生姜者，亦加水五升，煮取三升二合，服之。', '2024-09-17T00:59:58.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RLOpknGHdkv', 1, '{"title":"乌头桂枝汤","description":"<p>89、$f{乌头桂枝汤} $m{1味} $u{乌头}</p>\n<p>\t$s{右一味}，以$u{蜜}$w{二斤}，煎减半，去滓，以$f{桂枝汤}$w{五合}解之，得一升后，初服二合；不知，即取三合；又不知，复加至五合。其知者，如醉状，得吐者，为中病。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":89,"yaoCount":6,"drinkNum":5,"yaoList":["乌头","蜜","桂枝","芍药","甘草","生姜","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"dFbCWGnQmeQ","amount":"三两","weight":0,"suffix":"","showName":"乌头","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"半两","weight":50,"suffix":"","showName":"桂枝","extraProcess":"去皮"},{"yaoId":"Ro0664U6sTQ","amount":"半两","weight":50,"suffix":"","showName":"芍药","extraProcess":""},{"yaoId":null,"amount":"1/3两","weight":33,"suffix":"","showName":"甘草","extraProcess":"炙"},{"yaoId":"VcvhqvKkSct","amount":"半两","weight":50,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"2枚","weight":20,"suffix":"","showName":"大枣","extraProcess":"擘"}]}}', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '89、$f{乌头桂枝汤} $m{1味} $u{乌头} $s{右一味}，以$u{蜜}$w{二斤}，煎减半，去滓，以$f{桂枝汤}$w{五合}解之，得一升后，初服二合；不知，即取三合；又不知，复加至五合。其知者，如醉状，得吐者，为中病。', '2024-09-17T00:59:58.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2jgK1ocdns6', 1, '{"title":"桂枝汤","description":"<p>90、$f{桂枝汤} $m{5味} $u{桂枝}$w{三两，去皮}，$u{芍药}$w{三两}，$u{甘草}$w{二两，炙}，$u{生姜}$w{三两}，$u{大枣}$w{十二枚}</p>\n<p>\t$s{右五味}，剉，以水七升，微火煮取三升，去滓。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":90,"yaoCount":5,"drinkNum":3,"yaoList":["桂枝","芍药","甘草","生姜","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":300,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '90、$f{桂枝汤} $m{5味} $u{桂枝}$w{三两，去皮}，$u{芍药}$w{三两}，$u{甘草}$w{二两，炙}，$u{生姜}$w{三两}，$u{大枣}$w{十二枚} $s{右五味}，剉，以水七升，微火煮取三升，去滓。', '2024-09-17T00:59:58.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('b5AYPnRGwbM', 1, '{"title":"柴胡桂枝汤","description":"<p>91、$q{《外台》}$f{柴胡桂枝汤} $m{9味} 治心腹卒中痛者。</p>\n<p>\t$u{柴胡}$w{四两}，$u{黄芩}，$u{人参}，$u{芍药}，$u{桂枝}，$u{生姜}$w{各一两半}，$u{甘草}$w{一两}，$u{半夏}$w{二合半}，$u{大枣}$w{六枚}</p>\n<p>\t$s{右九味}，以水六升，煮取三升。温服一升，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":91,"yaoCount":9,"drinkNum":3,"yaoList":["柴胡","黄芩","人参","芍药","桂枝","生姜","甘草","半夏","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"JMfcgoRTH0J","amount":"四两","weight":400,"suffix":"","showName":"柴胡","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"一两半","weight":150,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"一两半","weight":150,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"一两半","weight":150,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"一两半","weight":150,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"一两半","weight":150,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":null,"amount":"一两","weight":100,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"二合半","weight":250,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"6枚","weight":60,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '91、$q{《外台》}$f{柴胡桂枝汤} $m{9味} 治心腹卒中痛者。 $u{柴胡}$w{四两}，$u{黄芩}，$u{人参}，$u{芍药}，$u{桂枝}，$u{生姜}$w{各一两半}，$u{甘草}$w{一两}，$u{半夏}$w{二合半}，$u{大枣}$w{六枚} $s{右九味}，以水六升，煮取三升。温服一升，日三服。', '2024-09-17T00:59:58.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XGPG9xEKKWk', 1, '{"title":"走马汤","description":"<p>92、$q{《外台》}$f{走马汤} $m{2味} 治中恶心痛腹胀，大便不通。</p>\n<p>\t$u{巴豆}$w{二枚，去皮心，熬}，$u{杏仁}$w{二枚}</p>\n<p>\t$s{右二味}，以绵缠，搥令碎，热汤二合，捻取白汁饮之，当下。老小量之。通治飞尸、鬼击病。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":92,"yaoCount":2,"drinkNum":1,"yaoList":["巴豆","杏仁"],"fangList":[],"fangYaoList":[{"yaoId":"1n7R7kiLFv1","amount":"2枚","weight":2,"suffix":"","showName":"巴豆","extraProcess":"切"},{"yaoId":"Hs7PKqMqKRj","amount":"2枚","weight":20,"suffix":"","showName":"杏仁","extraProcess":"切"}]}}', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '92、$q{《外台》}$f{走马汤} $m{2味} 治中恶心痛腹胀，大便不通。 $u{巴豆}$w{二枚，去皮心，熬}，$u{杏仁}$w{二枚} $s{右二味}，以绵缠，搥令碎，热汤二合，捻取白汁饮之，当下。老小量之。通治飞尸、鬼击病。', '2024-09-17T00:59:58.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hWhbws71ZIn', 1, '{"title":"瓜蒂散","description":"<p>93、$f{瓜蒂散} $m{3味} $u{瓜蒂}$w{一枚，熬黄}，$u{赤小豆}$w{一分，煮}</p>\n<p>\t$s{右二味}，杵为散，以$u{香豉}$w{七合}煮取汁，和散一钱匕，温服之。不吐者，少加之，以快吐为度而止。$a{亡血及虚者不可与之。}</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":93,"yaoCount":3,"drinkNum":1,"yaoList":["瓜蒂","赤小豆","香豉"],"fangList":[],"fangYaoList":[{"yaoId":"zdySy9e78kG","amount":"1枚(用半钱匕)","weight":5,"suffix":"","showName":"瓜蒂","extraProcess":"切"},{"yaoId":"xoqRCmUZylQ","amount":"一分(用半钱匕)","weight":5,"suffix":"","showName":"赤小豆","extraProcess":"切"},{"yaoId":"sx4xviDfH00","amount":"七合","weight":700,"suffix":"","showName":"香豉","extraProcess":"切"}]}}', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '93、$f{瓜蒂散} $m{3味} $u{瓜蒂}$w{一枚，熬黄}，$u{赤小豆}$w{一分，煮} $s{右二味}，杵为散，以$u{香豉}$w{七合}煮取汁，和散一钱匕，温服之。不吐者，少加之，以快吐为度而止。$a{亡血及虚者不可与之。}', '2024-09-17T00:59:58.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zyihgzYXfRu', 1, '{"title":"麻子仁丸","description":"<p>94、$f{麻子仁丸} $m{6味} $u{麻子仁}$w{二升}，$u{芍药}$w{半斤}，$u{枳实}$w{一斤}，$u{大黄}$w{一斤}，$u{厚朴}$w{一尺}，$u{杏仁}$w{一升}</p>\n<p>\t$s{右六味}，末之，炼$u{蜜}和丸梧子大。饮服十丸，日三，以知为度。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":94,"yaoCount":7,"drinkNum":100,"yaoList":["麻子仁","芍药","枳实","大黄","厚朴","杏仁","蜜"],"fangList":[],"fangYaoList":[{"yaoId":"H0hYG4VYtXF","amount":"二升","weight":2000,"suffix":"","showName":"麻子仁","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"半斤","weight":800,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"FRaBwjHoVui","amount":"一斤","weight":140,"suffix":"","showName":"枳实","extraProcess":"切"},{"yaoId":"To31b37bc6Z","amount":"一斤","weight":1600,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":"8714SID7nWu","amount":"一尺","weight":500,"suffix":"","showName":"厚朴","extraProcess":"切"},{"yaoId":"Hs7PKqMqKRj","amount":"一升约300枚","weight":3000,"suffix":"","showName":"杏仁","extraProcess":"切"}]}}', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '2024-09-17T00:59:58.000Z', '94、$f{麻子仁丸} $m{6味} $u{麻子仁}$w{二升}，$u{芍药}$w{半斤}，$u{枳实}$w{一斤}，$u{大黄}$w{一斤}，$u{厚朴}$w{一尺}，$u{杏仁}$w{一升} $s{右六味}，末之，炼$u{蜜}和丸梧子大。饮服十丸，日三，以知为度。', '2024-09-17T00:59:58.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yF6DTLw9y8c', 1, '{"title":"甘草干姜茯苓白术汤","description":"<p>95、$f{甘草干姜茯苓白术汤} $m{4味} $u{甘草}，$u{白术}$w{各二两}，$u{干姜}，$u{茯苓}$w{各四两}</p>\n<p>\t$s{右四味}，以水五升，煮取三升。分温三服，腰中即温。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":95,"yaoCount":4,"drinkNum":3,"yaoList":["甘草","白术","干姜","茯苓"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"UIYZOmiE2xW","amount":"二两","weight":200,"suffix":"","showName":"白术","extraProcess":"切"},{"yaoId":"0p1dUWRsS6D","amount":"四两","weight":400,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"VHE7Y68l232","amount":"四两","weight":400,"suffix":"","showName":"茯苓","extraProcess":"切"}]}}', '2024-09-17T00:59:59.000Z', '2024-09-17T00:59:59.000Z', '2024-09-17T00:59:59.000Z', '95、$f{甘草干姜茯苓白术汤} $m{4味} $u{甘草}，$u{白术}$w{各二两}，$u{干姜}，$u{茯苓}$w{各四两} $s{右四味}，以水五升，煮取三升。分温三服，腰中即温。', '2024-09-17T00:59:59.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NZovPT7NDni', 1, '{"title":"茯苓桂枝白术甘草汤","description":"<p>96、$f{茯苓桂枝白术甘草汤} $m{4味} $u{茯苓}$w{四两}，$u{桂枝}，$u{白术}$w{各三两}，$u{甘草}$w{二两}</p>\n<p>\t$s{右四味}，以水六升，煮取三升。分温三服，小便则利。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":96,"yaoCount":4,"drinkNum":3,"yaoList":["茯苓","桂枝","白术","甘草"],"fangList":[],"fangYaoList":[{"yaoId":"VHE7Y68l232","amount":"四两","weight":400,"suffix":"","showName":"茯苓","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"UIYZOmiE2xW","amount":"三两","weight":300,"suffix":"","showName":"白术","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"}]}}', '2024-09-17T00:59:59.000Z', '2024-09-17T00:59:59.000Z', '2024-09-17T00:59:59.000Z', '96、$f{茯苓桂枝白术甘草汤} $m{4味} $u{茯苓}$w{四两}，$u{桂枝}，$u{白术}$w{各三两}，$u{甘草}$w{二两} $s{右四味}，以水六升，煮取三升。分温三服，小便则利。', '2024-09-17T00:59:59.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3TWx4etQo1m', 1, '{"title":"甘遂半夏汤","description":"<p>97、$f{甘遂半夏汤} $m{4味} $u{甘遂}$w{大者，三枚}，$u{半夏}$w{十二枚，以水一升，煮取半升，去滓}，$u{芍药}$w{五枚}，$u{甘草}$w{如指大一枚，炙}</p>\n<p>\t$s{右四味}，以水二升，煮取半升，去滓，以$u{蜜}$w{半升}和药汁，煎取八合，顿服之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":97,"yaoCount":5,"drinkNum":1,"yaoList":["甘遂","半夏","芍药","甘草","蜜"],"fangList":[],"fangYaoList":[{"yaoId":"7nTRDUdzsoW","amount":"3枚大者","weight":140,"suffix":"","showName":"甘遂","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"12枚","weight":50,"suffix":"","showName":"半夏","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"5枚","weight":100,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":null,"amount":"如指大1枚","weight":70,"suffix":"","showName":"甘草","extraProcess":"切"}]}}', '2024-09-17T00:59:59.000Z', '2024-09-17T00:59:59.000Z', '2024-09-17T00:59:59.000Z', '97、$f{甘遂半夏汤} $m{4味} $u{甘遂}$w{大者，三枚}，$u{半夏}$w{十二枚，以水一升，煮取半升，去滓}，$u{芍药}$w{五枚}，$u{甘草}$w{如指大一枚，炙} $s{右四味}，以水二升，煮取半升，去滓，以$u{蜜}$w{半升}和药汁，煎取八合，顿服之。', '2024-09-17T00:59:59.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5eiHYjO1OOv', 1, '{"title":"十枣汤","description":"<p>98、$f{十枣汤} $m{4味} $u{芫花}$w{熬}，$u{甘遂}，$u{大戟}$w{各等分}，$u{大枣}$w{肥大者十枚}</p>\n<p>\t$s{右三味}，捣筛，以水一升五合，先煮肥大枣十枚，取八合，去滓，内药末。强人服一钱匕，羸人服半钱，平旦温服之；不下者，明日更加半钱。得快下后，糜粥自养。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":98,"yaoCount":4,"drinkNum":1,"yaoList":["芫花","甘遂","大戟","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"ME53uu1RfSN","amount":"1/3钱匕","weight":3,"suffix":"","showName":"芫花","extraProcess":"切"},{"yaoId":"7nTRDUdzsoW","amount":"1/3钱匕","weight":3,"suffix":"","showName":"甘遂","extraProcess":"切"},{"yaoId":"gZLQX87OyZG","amount":"1/3钱匕","weight":3,"suffix":"","showName":"大戟","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"10枚肥大者","weight":150,"suffix":"","showName":"大枣","extraProcess":"切"}]}}', '2024-09-17T00:59:59.000Z', '2024-09-17T00:59:59.000Z', '2024-09-17T00:59:59.000Z', '98、$f{十枣汤} $m{4味} $u{芫花}$w{熬}，$u{甘遂}，$u{大戟}$w{各等分}，$u{大枣}$w{肥大者十枚} $s{右三味}，捣筛，以水一升五合，先煮肥大枣十枚，取八合，去滓，内药末。强人服一钱匕，羸人服半钱，平旦温服之；不下者，明日更加半钱。得快下后，糜粥自养。', '2024-09-17T00:59:59.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SjbloMpKdqf', 1, '{"title":"大青龙汤","description":"<p>99、$f{大青龙汤} $m{7味} $u{麻黄}$w{六两，去节}，$u{桂枝}$w{二两，去皮}，$u{甘草}$w{二两，炙}，$u{杏仁}$w{四十个，去皮尖}，$u{生姜}$w{三两，切}，$u{大枣}$w{十二枚}，$u{石膏}$w{如鸡子大，碎}</p>\n<p>\t$s{右七味}，以水九升，先煮麻黄，减二升，去上沫，内诸药，煮取三升，去滓。温服一升，取微似汗。汗多者，温粉粉之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":99,"yaoCount":7,"drinkNum":3,"yaoList":["麻黄","桂枝","甘草","杏仁","生姜","大枣","石膏"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"六两","weight":600,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"二两","weight":200,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"Hs7PKqMqKRj","amount":"40个","weight":400,"suffix":"","showName":"杏仁","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"S7mhkBtEhPL","amount":"如鸡子大","weight":750,"suffix":"","showName":"石膏","extraProcess":"切"}]}}', '2024-09-17T00:59:59.000Z', '2024-09-17T00:59:59.000Z', '2024-09-17T00:59:59.000Z', '99、$f{大青龙汤} $m{7味} $u{麻黄}$w{六两，去节}，$u{桂枝}$w{二两，去皮}，$u{甘草}$w{二两，炙}，$u{杏仁}$w{四十个，去皮尖}，$u{生姜}$w{三两，切}，$u{大枣}$w{十二枚}，$u{石膏}$w{如鸡子大，碎} $s{右七味}，以水九升，先煮麻黄，减二升，去上沫，内诸药，煮取三升，去滓。温服一升，取微似汗。汗多者，温粉粉之。', '2024-09-17T00:59:59.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
