INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZMXcpM2QceS', 1, '{"title":"茯苓饮","description":"<p>109、$q{附方《外台》}$f{茯苓饮} $m{6味} 治心胸中有停痰宿水，自吐出水后，心胸间虚，气满不能食，消痰气，令能食。</p>\n<p>\t$u{茯苓}，$u{人参}，$u{白术}$w{各三两}，$u{枳实}$w{二两}，$u{橘皮}$w{二两半}，$u{生姜}$w{四两}。</p>\n<p>\t$s{右六味}，水六升，煮取一升八合。分温三服，如人行八九里进之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":109,"yaoCount":6,"drinkNum":3,"yaoList":["茯苓","人参","白术","枳实","橘皮","生姜"],"fangList":[],"fangYaoList":[{"yaoId":"VHE7Y68l232","amount":"三两","weight":300,"suffix":"","showName":"茯苓","extraProcess":"切"},{"yaoId":"GIXSHBaFv0L","amount":"三两","weight":300,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"UIYZOmiE2xW","amount":"三两","weight":300,"suffix":"","showName":"白术","extraProcess":"切"},{"yaoId":"FRaBwjHoVui","amount":"二两","weight":16,"suffix":"","showName":"枳实","extraProcess":"切"},{"yaoId":"216GW1qIoXb","amount":"二两","weight":200,"suffix":"","showName":"橘皮","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"四两","weight":400,"suffix":"","showName":"生姜","extraProcess":"切"}]}}', '2024-09-17T01:00:00.000Z', '2024-09-17T01:00:00.000Z', '2024-09-17T01:00:00.000Z', '109、$q{附方《外台》}$f{茯苓饮} $m{6味} 治心胸中有停痰宿水，自吐出水后，心胸间虚，气满不能食，消痰气，令能食。 $u{茯苓}，$u{人参}，$u{白术}$w{各三两}，$u{枳实}$w{二两}，$u{橘皮}$w{二两半}，$u{生姜}$w{四两}。 $s{右六味}，水六升，煮取一升八合。分温三服，如人行八九里进之。', '2024-09-17T01:00:00.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
