INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DdhVtfmq8J6', 1, '{"title":"茯苓戎盐汤","description":"<p>119、$f{茯苓戎盐汤} $m{3味} $u{茯苓}$w{半斤}，$u{白术}$w{二两}，$u{戎盐}$w{弹丸大，一枚}</p>\n<p>\t$s{右三味}，先将茯苓、白术煎成，入戎盐，再煎，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":119,"yaoCount":3,"drinkNum":3,"yaoList":["茯苓","白术","戎盐"],"fangList":[],"fangYaoList":[{"yaoId":"VHE7Y68l232","amount":"半斤","weight":800,"suffix":"","showName":"茯苓","extraProcess":"切"},{"yaoId":"UIYZOmiE2xW","amount":"二两","weight":200,"suffix":"","showName":"白术","extraProcess":"切"},{"yaoId":"Aj1WLaM2FzC","amount":"弹丸大1枚","weight":200,"suffix":"","showName":"戎盐","extraProcess":"切"}]}}', '2024-09-17T01:00:00.000Z', '2024-09-17T01:00:00.000Z', '2024-09-17T01:00:00.000Z', '119、$f{茯苓戎盐汤} $m{3味} $u{茯苓}$w{半斤}，$u{白术}$w{二两}，$u{戎盐}$w{弹丸大，一枚} $s{右三味}，先将茯苓、白术煎成，入戎盐，再煎，分温三服。', '2024-09-17T01:00:00.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xoOuX8JYGRq', 1, '{"title":"猪苓汤","description":"<p>120、$f{猪苓汤} $m{5味} $u{猪苓}$w{去皮}，$u{茯苓}，$u{阿胶}，$u{滑石}，$u{泽泻}$w{各一两}</p>\n<p>\t$s{右五味}，以水四升，先煮四味，取二升，去滓，内胶烊消。温服七合，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":120,"yaoCount":5,"drinkNum":3,"yaoList":["猪苓","茯苓","阿胶","滑石","泽泻"],"fangList":[],"fangYaoList":[{"yaoId":"VBp4qtisnQR","amount":"一两","weight":100,"suffix":"","showName":"猪苓","extraProcess":"切"},{"yaoId":"VHE7Y68l232","amount":"一两","weight":100,"suffix":"","showName":"茯苓","extraProcess":"切"},{"yaoId":"T3B7gaA2R03","amount":"一两","weight":100,"suffix":"","showName":"阿胶","extraProcess":"切"},{"yaoId":"u6WaDjpcWhR","amount":"一两","weight":100,"suffix":"","showName":"滑石","extraProcess":"切"},{"yaoId":"TvTXZli2dE7","amount":"一两","weight":100,"suffix":"","showName":"泽泻","extraProcess":"切"}]}}', '2024-09-17T01:00:00.000Z', '2024-09-17T01:00:00.000Z', '2024-09-17T01:00:00.000Z', '120、$f{猪苓汤} $m{5味} $u{猪苓}$w{去皮}，$u{茯苓}，$u{阿胶}，$u{滑石}，$u{泽泻}$w{各一两} $s{右五味}，以水四升，先煮四味，取二升，去滓，内胶烊消。温服七合，日三服。', '2024-09-17T01:00:00.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ElS40Cs5mZY', 1, '{"title":"越婢汤","description":"<p>121、$f{越婢汤} $m{5味} $u{麻黄}$w{六两}，$u{石膏}$w{半斤}，$u{生姜}$w{三两}，$u{大枣}$w{十五枚}，$u{甘草}$w{二两}</p>\n<p>\t$s{右五味}，以水六升，先煮麻黄，去上沫，内诸药，煮取三升，分温三服。恶风者，加$u{附子}$w{一枚，炮}；风水加$u{术}$w{四两}。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":121,"yaoCount":7,"drinkNum":3,"yaoList":["麻黄","石膏","生姜","大枣","甘草","附子","术"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"六两","weight":600,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"S7mhkBtEhPL","amount":"半斤","weight":800,"suffix":"","showName":"石膏","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"15枚","weight":150,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"}]}}', '2024-09-17T01:00:00.000Z', '2024-09-17T01:00:00.000Z', '2024-09-17T01:00:00.000Z', '121、$f{越婢汤} $m{5味} $u{麻黄}$w{六两}，$u{石膏}$w{半斤}，$u{生姜}$w{三两}，$u{大枣}$w{十五枚}，$u{甘草}$w{二两} $s{右五味}，以水六升，先煮麻黄，去上沫，内诸药，煮取三升，分温三服。恶风者，加$u{附子}$w{一枚，炮}；风水加$u{术}$w{四两}。', '2024-09-17T01:00:00.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
