INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dteoTshvW4u', 1, '{"title":"甘草麻黄汤","description":"<p>123、$f{甘草麻黄汤} $m{2味} $u{甘草}$w{二两}，$u{麻黄}$w{四两}</p>\n<p>\t$s{右二味}，以水五升，先煮麻黄，去上沫，内甘草，煮取三升。温服一升，重复汗出，不汗，再服，慎风寒。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":123,"yaoCount":2,"drinkNum":3,"yaoList":["甘草","麻黄"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"nxz0hvgpJJf","amount":"四两","weight":400,"suffix":"","showName":"麻黄","extraProcess":"切"}]}}', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '123、$f{甘草麻黄汤} $m{2味} $u{甘草}$w{二两}，$u{麻黄}$w{四两} $s{右二味}，以水五升，先煮麻黄，去上沫，内甘草，煮取三升。温服一升，重复汗出，不汗，再服，慎风寒。', '2024-09-17T01:00:01.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Woxo1FonpiH', 1, '{"title":"麻黄附子汤","description":"<p>124、$f{麻黄附子汤} $m{3味} $u{麻黄}$w{三两}，$u{甘草}$w{二两}，$u{附子}$w{一枚，炮}</p>\n<p>\t$s{右三味}，以水七升，先煮麻黄，去上沫，内诸药，煮取二升半。温服八分，日三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":124,"yaoCount":3,"drinkNum":3,"yaoList":["麻黄","甘草","附子"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"三两","weight":300,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"1枚炮","weight":100,"suffix":"","showName":"附子","extraProcess":"切"}]}}', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '124、$f{麻黄附子汤} $m{3味} $u{麻黄}$w{三两}，$u{甘草}$w{二两}，$u{附子}$w{一枚，炮} $s{右三味}，以水七升，先煮麻黄，去上沫，内诸药，煮取二升半。温服八分，日三服。', '2024-09-17T01:00:01.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6LR1a5saZEp', 1, '{"title":"杏子汤","description":"<p>125、$f{杏子汤} 方未见。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":125,"yaoCount":0,"drinkNum":1,"yaoList":[],"fangList":[],"fangYaoList":[]}}', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '125、$f{杏子汤} 方未见。', '2024-09-17T01:00:01.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('78VZlhUYnsw', 1, '{"title":"芪芍桂酒汤","description":"<p>126、$f{芪芍桂酒汤} $m{4味} $u{黄芪}$w{五两}，$u{芍药}$w{三两}，$u{桂枝}$w{三两}，$u{苦酒}$w{一升}。</p>\n<p>\t$s{右三味}，以苦酒一升，水七升，相和，煮取三升。温服一升，当心烦，服至六七日乃解。若心烦不止者，以苦酒阻故也。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":126,"yaoCount":4,"drinkNum":3,"yaoList":["黄芪","芍药","桂枝","苦酒"],"fangList":[],"fangYaoList":[{"yaoId":"i7j1zMcc48a","amount":"五两","weight":500,"suffix":"","showName":"黄芪","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":300,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"uUYyOFNioq6","amount":"一升","weight":1000,"suffix":"","showName":"苦酒","extraProcess":"切"}]}}', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '126、$f{芪芍桂酒汤} $m{4味} $u{黄芪}$w{五两}，$u{芍药}$w{三两}，$u{桂枝}$w{三两}，$u{苦酒}$w{一升}。 $s{右三味}，以苦酒一升，水七升，相和，煮取三升。温服一升，当心烦，服至六七日乃解。若心烦不止者，以苦酒阻故也。', '2024-09-17T01:00:01.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NMI9jbyZov5', 1, '{"title":"桂枝加黄芪汤","description":"<p>127、$f{桂枝加黄芪汤} $m{6味} $u{桂枝}，$u{芍药}$w{各三两}，$u{甘草}$w{二两}，$u{生姜}$w{三两}，$u{大枣}$w{十二枚}，$u{黄芪}$w{二两}</p>\n<p>\t$s{右六味}，以水八升，煮取三升。温服一升，须臾饮热稀粥一升余，以助药力，温服取微汗；若不汗，更取。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":127,"yaoCount":6,"drinkNum":3,"yaoList":["桂枝","芍药","甘草","生姜","大枣","黄芪"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":300,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"i7j1zMcc48a","amount":"二两","weight":200,"suffix":"","showName":"黄芪","extraProcess":"切"}]}}', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '127、$f{桂枝加黄芪汤} $m{6味} $u{桂枝}，$u{芍药}$w{各三两}，$u{甘草}$w{二两}，$u{生姜}$w{三两}，$u{大枣}$w{十二枚}，$u{黄芪}$w{二两} $s{右六味}，以水八升，煮取三升。温服一升，须臾饮热稀粥一升余，以助药力，温服取微汗；若不汗，更取。', '2024-09-17T01:00:01.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('go3BARtUvNW', 1, '{"title":"桂枝去芍药加麻黄细辛附子汤","description":"<p>128、$f{桂枝去芍药加麻黄细辛附子汤} $m{7味} $u{桂枝}$w{三两}，$u{生姜}$w{三两}，$u{甘草}$w{二两}，$u{大枣}$w{十二枚}，$u{麻黄}，$u{细辛}$w{各二两}，$u{附子}$w{一枚，炮}</p>\n<p>\t$s{右七味}，以水七升，煮麻黄，去上沫，内诸药，煮取二升。分温三服，当汗出，如虫行皮中，即愈。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":128,"yaoCount":7,"drinkNum":3,"yaoList":["桂枝","生姜","甘草","大枣","麻黄","细辛","附子"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"nxz0hvgpJJf","amount":"二两","weight":200,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"MCBshcFNHhk","amount":"二两","weight":200,"suffix":"","showName":"细辛","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"1枚炮","weight":100,"suffix":"","showName":"附子","extraProcess":"切"}]}}', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '128、$f{桂枝去芍药加麻黄细辛附子汤} $m{7味} $u{桂枝}$w{三两}，$u{生姜}$w{三两}，$u{甘草}$w{二两}，$u{大枣}$w{十二枚}，$u{麻黄}，$u{细辛}$w{各二两}，$u{附子}$w{一枚，炮} $s{右七味}，以水七升，煮麻黄，去上沫，内诸药，煮取二升。分温三服，当汗出，如虫行皮中，即愈。', '2024-09-17T01:00:01.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uYoXM05uHlf', 1, '{"title":"枳术汤","description":"<p>129、$f{枳术汤} $m{2味} $u{枳实}$w{七枚}，$u{白术}$w{二两}</p>\n<p>\t$s{右二味}，以水五升，煮取三升。分温三服，腹中耎，即当散也。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":129,"yaoCount":2,"drinkNum":3,"yaoList":["枳实","白术"],"fangList":[],"fangYaoList":[{"yaoId":"FRaBwjHoVui","amount":"7枚","weight":70,"suffix":"","showName":"枳实","extraProcess":"切"},{"yaoId":"UIYZOmiE2xW","amount":"二两","weight":200,"suffix":"","showName":"白术","extraProcess":"切"}]}}', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '129、$f{枳术汤} $m{2味} $u{枳实}$w{七枚}，$u{白术}$w{二两} $s{右二味}，以水五升，煮取三升。分温三服，腹中耎，即当散也。', '2024-09-17T01:00:01.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cfmIITCMfN3', 1, '{"title":"茵陈蒿汤","description":"<p>130、$f{茵陈蒿汤} $m{3味} $u{茵陈蒿}$w{六两}，$u{栀子}$w{十四枚}，$u{大黄}$w{二两}</p>\n<p>\t$s{右三味}，以水一斗，先煮茵陈，减六升，内二味，煮取三升，去滓。分温三服，小便当利，尿如皂角汁状，色正赤，一宿腹减，黄从小便去也。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":130,"yaoCount":3,"drinkNum":3,"yaoList":["茵陈蒿","栀子","大黄"],"fangList":[],"fangYaoList":[{"yaoId":"UCM21bJfrih","amount":"六两","weight":600,"suffix":"","showName":"茵陈蒿","extraProcess":"切"},{"yaoId":"7fWzC6yB6Yy","amount":"14枚","weight":140,"suffix":"","showName":"栀子","extraProcess":"切"},{"yaoId":"To31b37bc6Z","amount":"二两","weight":200,"suffix":"","showName":"大黄","extraProcess":"切"}]}}', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '130、$f{茵陈蒿汤} $m{3味} $u{茵陈蒿}$w{六两}，$u{栀子}$w{十四枚}，$u{大黄}$w{二两} $s{右三味}，以水一斗，先煮茵陈，减六升，内二味，煮取三升，去滓。分温三服，小便当利，尿如皂角汁状，色正赤，一宿腹减，黄从小便去也。', '2024-09-17T01:00:01.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UBDuPoO4Ku3', 1, '{"title":"硝石矾石散","description":"<p>131、$f{硝石矾石散} $m{2味} $u{硝石}，$u{矾石}$w{烧，等分}</p>\n<p>\t$s{右二味}，为散。以$u{大麦粥汁}和服方寸匕，日三服，病随大小便去，小便正黄，大便正黑，是候也。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":131,"yaoCount":2,"drinkNum":1,"yaoList":["硝石","矾石","大麦粥汁"],"fangList":[],"fangYaoList":[{"yaoId":"VbIDIYURZdR","amount":"半方寸匕","weight":2,"suffix":"","showName":"硝石","extraProcess":"切"},{"yaoId":"ozDrmO1Ighz","amount":"半方寸匕","weight":2,"suffix":"","showName":"矾石","extraProcess":"切"}]}}', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '131、$f{硝石矾石散} $m{2味} $u{硝石}，$u{矾石}$w{烧，等分} $s{右二味}，为散。以$u{大麦粥汁}和服方寸匕，日三服，病随大小便去，小便正黄，大便正黑，是候也。', '2024-09-17T01:00:01.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3XlPdaod61f', 1, '{"title":"栀子大黄汤","description":"<p>132、$f{栀子大黄汤} $m{4味} $u{栀子}$w{十四枚}，$u{大黄}$w{一两}，$u{枳实}$w{五枚}，$u{豉}$w{一升}</p>\n<p>\t$s{右四味}，以水六升，煮取二升，分温三服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":132,"yaoCount":4,"drinkNum":3,"yaoList":["栀子","大黄","枳实","豉"],"fangList":[],"fangYaoList":[{"yaoId":"7fWzC6yB6Yy","amount":"14枚","weight":140,"suffix":"","showName":"栀子","extraProcess":"切"},{"yaoId":"To31b37bc6Z","amount":"一两","weight":100,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":"FRaBwjHoVui","amount":"5枚","weight":50,"suffix":"","showName":"枳实","extraProcess":"切"},{"yaoId":"sx4xviDfH00","amount":"一升","weight":1000,"suffix":"","showName":"豉","extraProcess":"切"}]}}', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '132、$f{栀子大黄汤} $m{4味} $u{栀子}$w{十四枚}，$u{大黄}$w{一两}，$u{枳实}$w{五枚}，$u{豉}$w{一升} $s{右四味}，以水六升，煮取二升，分温三服。', '2024-09-17T01:00:01.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
