INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cpyOu2HQykv', 1, '{"title":"大黄硝石汤","description":"<p>135、$f{大黄硝石汤} $m{4味} $u{大黄}，$u{黄柏}，$u{硝石}$w{各四两}，$u{栀子}$w{十五枚}</p>\n<p>\t$s{右四味}，以水六升，煮取二升，去滓，内硝，更煮取一升，顿服。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":135,"yaoCount":4,"drinkNum":1,"yaoList":["大黄","黄柏","硝石","栀子"],"fangList":[],"fangYaoList":[{"yaoId":"To31b37bc6Z","amount":"四两","weight":400,"suffix":"","showName":"大黄","extraProcess":"切"},{"yaoId":"Z5xEswEFq4S","amount":"三两","weight":400,"suffix":"","showName":"黄柏","extraProcess":"切"},{"yaoId":"VbIDIYURZdR","amount":"三两","weight":400,"suffix":"","showName":"硝石","extraProcess":"切"},{"yaoId":"7fWzC6yB6Yy","amount":"15枚","weight":150,"suffix":"","showName":"栀子","extraProcess":"切"}]}}', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '135、$f{大黄硝石汤} $m{4味} $u{大黄}，$u{黄柏}，$u{硝石}$w{各四两}，$u{栀子}$w{十五枚} $s{右四味}，以水六升，煮取二升，去滓，内硝，更煮取一升，顿服。', '2024-09-17T01:00:01.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DQkzEQP5Pkv', 1, '{"title":"麻黄醇酒汤","description":"<p>136、$q{《千金》}$f{麻黄醇酒汤} $m{1味} 治黄疸。</p>\n<p>\t$u{麻黄}$w{三两}</p>\n<p>\t$s{右一味}，以美$u{清酒}五升，煮取二升半，顿服尽。冬月用酒，春月用水煮之。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":136,"yaoCount":2,"drinkNum":1,"yaoList":["麻黄","清酒"],"fangList":[],"fangYaoList":[{"yaoId":"nxz0hvgpJJf","amount":"三两","weight":300,"suffix":"","showName":"麻黄","extraProcess":"切"},{"yaoId":"JMpy06saY9b","amount":"五升","weight":5000,"suffix":"","showName":"清酒","extraProcess":"切"}]}}', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '2024-09-17T01:00:01.000Z', '136、$q{《千金》}$f{麻黄醇酒汤} $m{1味} 治黄疸。 $u{麻黄}$w{三两} $s{右一味}，以美$u{清酒}五升，煮取二升半，顿服尽。冬月用酒，春月用水煮之。', '2024-09-17T01:00:01.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t7h81USCpXK', 1, '{"title":"桂枝去芍药加蜀漆牡蛎龙骨救逆汤","description":"<p>137、$f{桂枝去芍药加蜀漆牡蛎龙骨救逆汤} $m{7味} $u{桂枝}$w{三两，去皮}，$u{甘草}$w{二两，炙}，$u{生姜}$w{三两}，$u{牡蛎}$w{五两，熬}，$u{龙骨}$w{四两}，$u{大枣}$w{十二枚}，$u{蜀漆}$w{三两，洗去腥}</p>\n<p>\t$s{右为末}，以水一斗二升，先煮蜀漆，减二升，内诸药，煮取三升，去滓，温服一升。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"ydyQltIuQv6","no":137,"yaoCount":7,"drinkNum":3,"yaoList":["桂枝","甘草","生姜","牡蛎","龙骨","大枣","蜀漆"],"fangList":[],"fangYaoList":[{"yaoId":"7S7n1dzieYK","amount":"三两","weight":300,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":200,"suffix":"","showName":"甘草","extraProcess":"切"},{"yaoId":"VcvhqvKkSct","amount":"三两","weight":300,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"MDfiJ4S7u0U","amount":"五两","weight":500,"suffix":"","showName":"牡蛎","extraProcess":"切"},{"yaoId":"vL3tFGA7NwL","amount":"四两","weight":400,"suffix":"","showName":"龙骨","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"12枚","weight":120,"suffix":"","showName":"大枣","extraProcess":"切"},{"yaoId":"gFgG38KNuFm","amount":"三两","weight":300,"suffix":"","showName":"蜀漆","extraProcess":"切"}]}}', '2024-09-17T01:00:02.000Z', '2024-09-17T01:00:02.000Z', '2024-09-17T01:00:02.000Z', '137、$f{桂枝去芍药加蜀漆牡蛎龙骨救逆汤} $m{7味} $u{桂枝}$w{三两，去皮}，$u{甘草}$w{二两，炙}，$u{生姜}$w{三两}，$u{牡蛎}$w{五两，熬}，$u{龙骨}$w{四两}，$u{大枣}$w{十二枚}，$u{蜀漆}$w{三两，洗去腥} $s{右为末}，以水一斗二升，先煮蜀漆，减二升，内诸药，煮取三升，去滓，温服一升。', '2024-09-17T01:00:02.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
